-- InkTelligence / Alexei "Inkseer" Novak
-- Generated from the synchronized JSON fallback and alexy.zip by generate_t1000_sql.mjs.
-- Target: MariaDB 10.11+ / MySQL 8.0+
-- The import is non-destructive at database level and can be executed repeatedly.

SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;
SET @OLD_FOREIGN_KEY_CHECKS = @@FOREIGN_KEY_CHECKS;
SET FOREIGN_KEY_CHECKS = 0;

CREATE DATABASE IF NOT EXISTS `t1000`
  CHARACTER SET utf8mb4
  COLLATE utf8mb4_unicode_ci;
USE `t1000`;

CREATE TABLE IF NOT EXISTS import_manifest (
  manifest_id TINYINT UNSIGNED NOT NULL,
  source_name VARCHAR(190) NOT NULL,
  source_version VARCHAR(32) NOT NULL,
  source_date DATE NULL,
  source_language VARCHAR(16) NOT NULL,
  tattoo_database_sha256 CHAR(64) NOT NULL,
  alexy_package_sha256 CHAR(64) NOT NULL,
  source_meta JSON NOT NULL,
  source_counts JSON NOT NULL,
  imported_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (manifest_id)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS style_categories (
  category_id VARCHAR(100) NOT NULL,
  name VARCHAR(190) NOT NULL,
  description TEXT NOT NULL,
  source_payload JSON NOT NULL,
  PRIMARY KEY (category_id),
  UNIQUE KEY uq_style_category_name (name)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS technique_categories (
  category_id VARCHAR(100) NOT NULL,
  name VARCHAR(190) NOT NULL,
  description TEXT NOT NULL,
  source_payload JSON NOT NULL,
  PRIMARY KEY (category_id),
  UNIQUE KEY uq_technique_category_name (name)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS styles (
  style_id VARCHAR(100) NOT NULL,
  category_id VARCHAR(100) NOT NULL,
  name VARCHAR(190) NOT NULL,
  description TEXT NOT NULL,
  history TEXT NOT NULL,
  distinct_features TEXT NOT NULL,
  narrative_description LONGTEXT NOT NULL,
  narrative_language VARCHAR(16) NOT NULL DEFAULT 'en',
  source_payload JSON NOT NULL,
  PRIMARY KEY (style_id),
  UNIQUE KEY uq_style_name (name),
  KEY ix_styles_category (category_id),
  FULLTEXT KEY ft_styles_compendium (name, description, history, distinct_features, narrative_description),
  CONSTRAINT fk_styles_category FOREIGN KEY (category_id)
    REFERENCES style_categories (category_id)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS techniques (
  technique_id VARCHAR(100) NOT NULL,
  category_id VARCHAR(100) NOT NULL,
  name VARCHAR(190) NOT NULL,
  description TEXT NOT NULL,
  difficulty ENUM('basic', 'beginner', 'intermediate', 'advanced', 'expert', 'unspecified') NOT NULL DEFAULT 'unspecified',
  narrative_description LONGTEXT NOT NULL,
  narrative_language VARCHAR(16) NOT NULL DEFAULT 'en',
  source_payload JSON NOT NULL,
  PRIMARY KEY (technique_id),
  UNIQUE KEY uq_technique_name (name),
  KEY ix_techniques_category (category_id),
  KEY ix_techniques_difficulty (difficulty),
  FULLTEXT KEY ft_techniques_compendium (name, description, narrative_description),
  CONSTRAINT fk_techniques_category FOREIGN KEY (category_id)
    REFERENCES technique_categories (category_id)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS style_motifs (
  style_id VARCHAR(100) NOT NULL,
  motif VARCHAR(190) NOT NULL,
  display_order SMALLINT UNSIGNED NOT NULL,
  PRIMARY KEY (style_id, motif),
  KEY ix_style_motifs_motif (motif),
  CONSTRAINT fk_style_motifs_style FOREIGN KEY (style_id)
    REFERENCES styles (style_id) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS style_techniques (
  style_id VARCHAR(100) NOT NULL,
  technique_id VARCHAR(100) NOT NULL,
  display_order SMALLINT UNSIGNED NOT NULL,
  relation_source ENUM('style.relatedTechniques', 'inferred') NOT NULL DEFAULT 'style.relatedTechniques',
  PRIMARY KEY (style_id, technique_id),
  KEY ix_style_techniques_technique (technique_id),
  CONSTRAINT fk_style_techniques_style FOREIGN KEY (style_id)
    REFERENCES styles (style_id) ON DELETE CASCADE,
  CONSTRAINT fk_style_techniques_technique FOREIGN KEY (technique_id)
    REFERENCES techniques (technique_id) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS related_styles (
  style_id VARCHAR(100) NOT NULL,
  related_style_id VARCHAR(100) NOT NULL,
  display_order SMALLINT UNSIGNED NOT NULL,
  PRIMARY KEY (style_id, related_style_id),
  KEY ix_related_styles_target (related_style_id),
  CONSTRAINT fk_related_styles_style FOREIGN KEY (style_id)
    REFERENCES styles (style_id) ON DELETE CASCADE,
  CONSTRAINT fk_related_styles_target FOREIGN KEY (related_style_id)
    REFERENCES styles (style_id) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS technique_style_usage (
  technique_id VARCHAR(100) NOT NULL,
  style_id VARCHAR(100) NOT NULL,
  display_order SMALLINT UNSIGNED NOT NULL,
  PRIMARY KEY (technique_id, style_id),
  KEY ix_technique_usage_style (style_id),
  CONSTRAINT fk_technique_usage_technique FOREIGN KEY (technique_id)
    REFERENCES techniques (technique_id) ON DELETE CASCADE,
  CONSTRAINT fk_technique_usage_style FOREIGN KEY (style_id)
    REFERENCES styles (style_id) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS mixed_styles (
  mixed_style_id VARCHAR(100) NOT NULL,
  name VARCHAR(190) NOT NULL,
  description TEXT NOT NULL,
  narrative_description LONGTEXT NOT NULL,
  narrative_language VARCHAR(16) NOT NULL DEFAULT 'en',
  PRIMARY KEY (mixed_style_id),
  UNIQUE KEY uq_mixed_style_name (name),
  FULLTEXT KEY ft_mixed_styles (name, description, narrative_description)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS mixed_style_components (
  mixed_style_id VARCHAR(100) NOT NULL,
  component_order SMALLINT UNSIGNED NOT NULL,
  component_id VARCHAR(100) NOT NULL,
  component_type ENUM('style', 'technique', 'unknown') NOT NULL,
  PRIMARY KEY (mixed_style_id, component_order),
  KEY ix_mixed_components_component (component_id),
  CONSTRAINT fk_mixed_components_mixed_style FOREIGN KEY (mixed_style_id)
    REFERENCES mixed_styles (mixed_style_id) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS library_articles (
  article_id VARCHAR(20) NOT NULL,
  slug VARCHAR(190) NOT NULL,
  module ENUM('styles', 'techniques', 'history') NOT NULL,
  display_order SMALLINT UNSIGNED NOT NULL,
  title VARCHAR(255) NOT NULL,
  paper_title VARCHAR(500) NOT NULL,
  dek TEXT NOT NULL,
  curator_note TEXT NOT NULL,
  tags JSON NOT NULL,
  file_name VARCHAR(255) NOT NULL,
  word_count MEDIUMINT UNSIGNED NOT NULL,
  reading_minutes SMALLINT UNSIGNED NOT NULL,
  published_at DATE NOT NULL,
  body LONGTEXT NOT NULL,
  source_sha256 CHAR(64) NOT NULL,
  PRIMARY KEY (article_id),
  UNIQUE KEY uq_library_article_slug (slug),
  UNIQUE KEY uq_library_article_order (display_order),
  KEY ix_library_articles_module (module),
  FULLTEXT KEY ft_library_articles (title, paper_title, dek, body)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS library_article_entries (
  article_id VARCHAR(20) NOT NULL,
  catalog_id VARCHAR(100) NOT NULL,
  catalog_type ENUM('style', 'technique', 'unknown') NOT NULL,
  display_order SMALLINT UNSIGNED NOT NULL,
  PRIMARY KEY (article_id, catalog_id),
  KEY ix_library_article_entries_catalog (catalog_id),
  CONSTRAINT fk_library_article_entries_article FOREIGN KEY (article_id)
    REFERENCES library_articles (article_id) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS history_periods (
  period_id VARCHAR(100) NOT NULL,
  display_order SMALLINT UNSIGNED NOT NULL,
  date_label VARCHAR(100) NOT NULL,
  title VARCHAR(190) NOT NULL,
  summary TEXT NOT NULL,
  source_label VARCHAR(190) NULL,
  source_url VARCHAR(1000) NULL,
  PRIMARY KEY (period_id),
  UNIQUE KEY uq_history_period_order (display_order),
  FULLTEXT KEY ft_history_periods (title, summary)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS history_period_styles (
  period_id VARCHAR(100) NOT NULL,
  style_id VARCHAR(100) NOT NULL,
  display_order SMALLINT UNSIGNED NOT NULL,
  PRIMARY KEY (period_id, style_id),
  CONSTRAINT fk_history_period_styles_period FOREIGN KEY (period_id)
    REFERENCES history_periods (period_id) ON DELETE CASCADE,
  CONSTRAINT fk_history_period_styles_style FOREIGN KEY (style_id)
    REFERENCES styles (style_id) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS anthropology_lenses (
  lens_id VARCHAR(100) NOT NULL,
  display_order SMALLINT UNSIGNED NOT NULL,
  title VARCHAR(190) NOT NULL,
  description TEXT NOT NULL,
  icon_key VARCHAR(50) NOT NULL,
  PRIMARY KEY (lens_id),
  UNIQUE KEY uq_anthropology_lens_order (display_order)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS app_roles (
  role_id VARCHAR(100) NOT NULL,
  name VARCHAR(190) NOT NULL,
  description TEXT NOT NULL,
  is_active BOOLEAN NOT NULL DEFAULT FALSE,
  PRIMARY KEY (role_id),
  UNIQUE KEY uq_app_role_name (name)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS app_users (
  user_id CHAR(36) NOT NULL,
  login VARCHAR(190) NOT NULL,
  display_name VARCHAR(190) NOT NULL,
  role_id VARCHAR(100) NOT NULL,
  credential_source ENUM('environment', 'password_hash', 'oauth') NOT NULL DEFAULT 'environment',
  status ENUM('active', 'dormant', 'suspended') NOT NULL DEFAULT 'dormant',
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (user_id),
  UNIQUE KEY uq_app_user_login (login),
  CONSTRAINT fk_app_users_role FOREIGN KEY (role_id)
    REFERENCES app_roles (role_id)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS membership_packages (
  package_id VARCHAR(100) NOT NULL,
  name VARCHAR(190) NOT NULL,
  audience VARCHAR(255) NOT NULL,
  description TEXT NOT NULL,
  monthly_price_eur DECIMAL(8,2) NULL,
  future_image_credits INT UNSIGNED NOT NULL DEFAULT 0,
  features JSON NOT NULL,
  display_order SMALLINT UNSIGNED NOT NULL,
  status ENUM('draft', 'active', 'retired') NOT NULL DEFAULT 'draft',
  PRIMARY KEY (package_id),
  UNIQUE KEY uq_membership_package_order (display_order)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS app_feature_flags (
  flag_key VARCHAR(100) NOT NULL,
  enabled BOOLEAN NOT NULL DEFAULT FALSE,
  description TEXT NOT NULL,
  PRIMARY KEY (flag_key)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS ai_personas (
  persona_id VARCHAR(100) NOT NULL,
  schema_version VARCHAR(32) NOT NULL,
  persona_type VARCHAR(100) NOT NULL,
  display_name VARCHAR(190) NOT NULL,
  description TEXT NOT NULL,
  payload JSON NOT NULL,
  source_sha256 CHAR(64) NOT NULL,
  PRIMARY KEY (persona_id)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS ai_knowledge_bases (
  knowledge_base_id VARCHAR(100) NOT NULL,
  schema_version VARCHAR(32) NOT NULL,
  title VARCHAR(255) NOT NULL,
  description TEXT NOT NULL,
  payload JSON NOT NULL,
  source_sha256 CHAR(64) NOT NULL,
  PRIMARY KEY (knowledge_base_id)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS ai_documents (
  document_name VARCHAR(190) NOT NULL,
  document_role ENUM('overview', 'persona', 'knowledge_base', 'system_prompt', 'image_prompt_template', 'example') NOT NULL,
  media_type VARCHAR(100) NOT NULL,
  content LONGTEXT NOT NULL,
  source_sha256 CHAR(64) NOT NULL,
  PRIMARY KEY (document_name),
  KEY ix_ai_documents_role (document_role),
  FULLTEXT KEY ft_ai_documents_content (content)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS ai_packages (
  package_id VARCHAR(100) NOT NULL,
  file_name VARCHAR(190) NOT NULL,
  media_type VARCHAR(100) NOT NULL,
  archive_blob LONGBLOB NOT NULL,
  source_sha256 CHAR(64) NOT NULL,
  PRIMARY KEY (package_id),
  UNIQUE KEY uq_ai_package_file_name (file_name)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS ai_agents (
  agent_id VARCHAR(100) NOT NULL,
  persona_id VARCHAR(100) NOT NULL,
  knowledge_base_id VARCHAR(100) NOT NULL,
  display_name VARCHAR(190) NOT NULL,
  default_language VARCHAR(16) NOT NULL DEFAULT 'en',
  system_prompt_document VARCHAR(190) NOT NULL,
  image_prompt_document VARCHAR(190) NOT NULL,
  example_document VARCHAR(190) NOT NULL,
  runtime_config JSON NOT NULL,
  is_active BOOLEAN NOT NULL DEFAULT TRUE,
  PRIMARY KEY (agent_id),
  CONSTRAINT fk_ai_agents_persona FOREIGN KEY (persona_id)
    REFERENCES ai_personas (persona_id),
  CONSTRAINT fk_ai_agents_knowledge FOREIGN KEY (knowledge_base_id)
    REFERENCES ai_knowledge_bases (knowledge_base_id),
  CONSTRAINT fk_ai_agents_system_prompt FOREIGN KEY (system_prompt_document)
    REFERENCES ai_documents (document_name),
  CONSTRAINT fk_ai_agents_image_prompt FOREIGN KEY (image_prompt_document)
    REFERENCES ai_documents (document_name),
  CONSTRAINT fk_ai_agents_example FOREIGN KEY (example_document)
    REFERENCES ai_documents (document_name)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS consultation_sessions (
  session_id CHAR(36) NOT NULL,
  agent_id VARCHAR(100) NOT NULL DEFAULT 'alexei_inkseer',
  language_code VARCHAR(16) NOT NULL DEFAULT 'en',
  client_name VARCHAR(190) NULL,
  current_phase TINYINT UNSIGNED NOT NULL DEFAULT 1,
  status ENUM('active', 'completed', 'archived') NOT NULL DEFAULT 'active',
  context_payload JSON NULL,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (session_id),
  KEY ix_sessions_agent_status (agent_id, status),
  CONSTRAINT chk_sessions_phase CHECK (current_phase BETWEEN 1 AND 6),
  CONSTRAINT fk_sessions_agent FOREIGN KEY (agent_id)
    REFERENCES ai_agents (agent_id)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS consultation_messages (
  message_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  session_id CHAR(36) NOT NULL,
  role ENUM('system', 'user', 'assistant', 'tool') NOT NULL,
  content LONGTEXT NOT NULL,
  structured_payload JSON NULL,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (message_id),
  KEY ix_messages_session_time (session_id, created_at),
  CONSTRAINT fk_messages_session FOREIGN KEY (session_id)
    REFERENCES consultation_sessions (session_id) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS generated_designs (
  design_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  session_id CHAR(36) NOT NULL,
  design_spec JSON NOT NULL,
  image_prompt LONGTEXT NOT NULL,
  target_generator VARCHAR(100) NULL,
  studio_brief LONGTEXT NULL,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (design_id),
  KEY ix_designs_session (session_id),
  CONSTRAINT fk_designs_session FOREIGN KEY (session_id)
    REFERENCES consultation_sessions (session_id) ON DELETE CASCADE
) ENGINE=InnoDB;

-- Prompt build system -------------------------------------------------------
-- The generator registry is data, not code: a new image model is a row here,
-- and lib/prompt renders it from syntax_profile without a deploy.

CREATE TABLE IF NOT EXISTS image_models (
  model_key VARCHAR(100) NOT NULL,
  family VARCHAR(50) NOT NULL,
  vendor VARCHAR(100) NOT NULL,
  display_name VARCHAR(190) NOT NULL,
  model_version VARCHAR(50) NOT NULL,
  status ENUM('active', 'preview', 'deprecated') NOT NULL DEFAULT 'active',
  syntax_profile JSON NOT NULL,
  capabilities JSON NOT NULL,
  default_parameters JSON NOT NULL,
  notes TEXT NOT NULL,
  display_order SMALLINT UNSIGNED NOT NULL DEFAULT 0,
  is_default BOOLEAN NOT NULL DEFAULT FALSE,
  PRIMARY KEY (model_key),
  KEY ix_image_models_status (status, display_order)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS prompt_blocks (
  block_id VARCHAR(100) NOT NULL,
  block_type ENUM('surface', 'quality', 'lighting', 'longevity', 'cultural', 'negative') NOT NULL,
  render_mode ENUM('flash', 'on_skin', 'both') NOT NULL DEFAULT 'both',
  applies_to_family VARCHAR(50) NOT NULL DEFAULT 'all',
  content TEXT NOT NULL,
  weight DECIMAL(3,2) NULL,
  display_order SMALLINT UNSIGNED NOT NULL DEFAULT 0,
  is_active BOOLEAN NOT NULL DEFAULT TRUE,
  PRIMARY KEY (block_id),
  KEY ix_prompt_blocks_lookup (block_type, render_mode, applies_to_family, display_order)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS prompt_builds (
  build_id CHAR(36) NOT NULL,
  session_id CHAR(36) NULL,
  design_spec JSON NOT NULL,
  prompt_ir JSON NOT NULL,
  catalog_refs JSON NOT NULL,
  render_mode ENUM('flash', 'on_skin') NOT NULL DEFAULT 'flash',
  cultural_check ENUM('clear', 'inspired_not_copied', 'flagged') NOT NULL DEFAULT 'clear',
  warnings JSON NOT NULL,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (build_id),
  KEY ix_prompt_builds_session (session_id, created_at),
  CONSTRAINT fk_prompt_builds_session FOREIGN KEY (session_id)
    REFERENCES consultation_sessions (session_id) ON DELETE SET NULL
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS prompt_build_renders (
  render_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  build_id CHAR(36) NOT NULL,
  model_key VARCHAR(100) NOT NULL,
  prompt LONGTEXT NOT NULL,
  negative_prompt LONGTEXT NULL,
  parameters JSON NOT NULL,
  char_count INT UNSIGNED NOT NULL,
  truncated BOOLEAN NOT NULL DEFAULT FALSE,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (render_id),
  UNIQUE KEY uq_render_build_model (build_id, model_key),
  CONSTRAINT fk_renders_build FOREIGN KEY (build_id)
    REFERENCES prompt_builds (build_id) ON DELETE CASCADE,
  CONSTRAINT fk_renders_model FOREIGN KEY (model_key)
    REFERENCES image_models (model_key)
) ENGINE=InnoDB;

ALTER TABLE ai_agents
  MODIFY COLUMN default_language VARCHAR(16) NOT NULL DEFAULT 'en';
ALTER TABLE consultation_sessions
  MODIFY COLUMN language_code VARCHAR(16) NOT NULL DEFAULT 'en';

INSERT INTO `import_manifest` (`manifest_id`, `source_name`, `source_version`, `source_date`, `source_language`, `tattoo_database_sha256`, `alexy_package_sha256`, `source_meta`, `source_counts`)
VALUES
  (1, 'Master Tattoo Classification Database', '1.2', '2026-07-20', 'en', 'ec7e7bdf22d8d887c6a1db75e173b2092cdc0716e9a9a351203585aa544e0773', 'a1f49c1cfc85bf54b24ea4282ee418ac01ee6cb3e676bba8f57eae46f6814f7e', '{"name":"Master Tattoo Classification Database","version":"1.2","date":"2026-07-20","language":"en","sources":["style.txt","technics.txt","klasyfikacja.txt","extended taxonomy","InkTelligence research corpus (30 papers)"],"counts":{"styleCategories":12,"styles":66,"techniqueCategories":8,"techniques":44,"historyPeriods":6,"anthropologyLenses":4,"articles":30}}', '{"styleCategories":12,"styles":66,"techniqueCategories":8,"techniques":44,"historyPeriods":6,"anthropologyLenses":4,"articles":30,"mixedStyles":6,"alexyDocuments":6}')
ON DUPLICATE KEY UPDATE
  `source_name` = VALUES(`source_name`),
  `source_version` = VALUES(`source_version`),
  `source_date` = VALUES(`source_date`),
  `source_language` = VALUES(`source_language`),
  `tattoo_database_sha256` = VALUES(`tattoo_database_sha256`),
  `alexy_package_sha256` = VALUES(`alexy_package_sha256`),
  `source_meta` = VALUES(`source_meta`),
  `source_counts` = VALUES(`source_counts`);

INSERT INTO `style_categories` (`category_id`, `name`, `description`, `source_payload`)
VALUES
  ('traditional', 'Traditional & Old School', 'The codified Western idiom of the bold, readable badge — heavy black outlines, a restricted saturated palette, and flat fills descended from maritime folk marks and 20th-century American flash. Its descendants split into faithful revival and illustrative reinvention (neo- and new school). Its governing law is ''bold will hold'': everything here is built for the ten-year read.', '{"id":"traditional","name":"Traditional & Old School","description":"The codified Western idiom of the bold, readable badge — heavy black outlines, a restricted saturated palette, and flat fills descended from maritime folk marks and 20th-century American flash. Its descendants split into faithful revival and illustrative reinvention (neo- and new school). Its governing law is ''bold will hold'': everything here is built for the ten-year read."}'),
  ('realism', 'Realism', 'Lifelike representation carried from photography and painting into living skin, from 1970s Chicano single-needle black-and-grey to full-color hyperrealism. It is the most time-sensitive family in the atlas — fine detail and micro-scale must be compressed and spaced for the pigment spread the years will bring.', '{"id":"realism","name":"Realism","description":"Lifelike representation carried from photography and painting into living skin, from 1970s Chicano single-needle black-and-grey to full-color hyperrealism. It is the most time-sensitive family in the atlas — fine detail and micro-scale must be compressed and spaced for the pigment spread the years will bring."}'),
  ('blackwork', 'Blackwork & Geometric', 'Styles built on black ink as structure rather than color: solid fill, dot density, mathematical repetition, ornament, and negative skin. It spans ancient tribal and folk roots and a contemporary geometric-and-dotwork revival, and it holds contrast longer than almost anything else on the body.', '{"id":"blackwork","name":"Blackwork & Geometric","description":"Styles built on black ink as structure rather than color: solid fill, dot density, mathematical repetition, ornament, and negative skin. It spans ancient tribal and folk roots and a contemporary geometric-and-dotwork revival, and it holds contrast longer than almost anything else on the body."}'),
  ('cultural', 'Cultural & Tribal', 'Indigenous and heritage tattoo systems — Māori tā moko, Sāmoan tatau, Marquesan, Haida, Celtic, Mesoamerican — each a distinct language of genealogy, rank, and belonging, never a single generic ''tribal'' aesthetic. Many marks are held under community authority; some are restricted, and are honored through inspiration, not copying.', '{"id":"cultural","name":"Cultural & Tribal","description":"Indigenous and heritage tattoo systems — Māori tā moko, Sāmoan tatau, Marquesan, Haida, Celtic, Mesoamerican — each a distinct language of genealogy, rank, and belonging, never a single generic ''tribal'' aesthetic. Many marks are held under community authority; some are restricted, and are honored through inspiration, not copying."}'),
  ('japanese', 'Japanese', 'The Irezumi tradition and its descendants: large-scale, flowing, mythological compositions organized as a whole-body narrative and applied historically by hand (tebori). It carries a continuous iconography and a long history of legal stigma, distinct from the surface imitation of neo-Japanese and anime work.', '{"id":"japanese","name":"Japanese","description":"The Irezumi tradition and its descendants: large-scale, flowing, mythological compositions organized as a whole-body narrative and applied historically by hand (tebori). It carries a continuous iconography and a long history of legal stigma, distinct from the surface imitation of neo-Japanese and anime work."}'),
  ('illustrative', 'Illustrative & Artistic', 'Styles that borrow the marks of other media — etching and engraving, loose sketch, watercolor wash, abstraction, comic and Pop Art — and rebuild them in skin. The craft here is translation: what a brush or pen does easily, the needle must reconstruct in a medium that moves and ages.', '{"id":"illustrative","name":"Illustrative & Artistic","description":"Styles that borrow the marks of other media — etching and engraving, loose sketch, watercolor wash, abstraction, comic and Pop Art — and rebuild them in skin. The craft here is translation: what a brush or pen does easily, the needle must reconstruct in a medium that moves and ages."}'),
  ('modern', 'Modern & Experimental', 'Contemporary, avant-garde, and digital-culture-driven styles — Trash Polka, biomechanical, cyber sigilism, embroidery, glitch, sticker and patchwork — many named only in the last few years, often on social platforms. This is the atlas''s living edge, where new dialects arrive faster than the vocabulary to describe them.', '{"id":"modern","name":"Modern & Experimental","description":"Contemporary, avant-garde, and digital-culture-driven styles — Trash Polka, biomechanical, cyber sigilism, embroidery, glitch, sticker and patchwork — many named only in the last few years, often on social platforms. This is the atlas''s living edge, where new dialects arrive faster than the vocabulary to describe them."}'),
  ('fineline', 'Minimalist & Fine Line', 'Delicate, understated work built from the thinnest practical lines, minimal scale, and restraint — fine-line, pure linework, and single continuous line. Its elegance is real, but so is its cost: the less pigment a mark deposits, the more it asks of time. Placement and honest aftercare matter most here.', '{"id":"fineline","name":"Minimalist & Fine Line","description":"Delicate, understated work built from the thinnest practical lines, minimal scale, and restraint — fine-line, pure linework, and single continuous line. Its elegance is real, but so is its cost: the less pigment a mark deposits, the more it asks of time. Placement and honest aftercare matter most here."}'),
  ('lettering', 'Lettering & Script', 'The art of tattooed typography — from Chicano Old English and gothic blackletter to calligraphy and graffiti-derived calligraffiti. Letterforms demand their own discipline: consistent weight, controlled spacing, and flourish, with legibility that must survive years of skin movement.', '{"id":"lettering","name":"Lettering & Script","description":"The art of tattooed typography — from Chicano Old English and gothic blackletter to calligraphy and graffiti-derived calligraffiti. Letterforms demand their own discipline: consistent weight, controlled spacing, and flourish, with legibility that must survive years of skin movement."}'),
  ('dark', 'Dark Art & Horror', 'Macabre, gothic, occult, and horror imagery — fear, mortality, transgression, and the sublime rendered on skin, often through realist or blackwork execution. Subject and technique are separate here: the darkness is in what is depicted, not necessarily in how it is made.', '{"id":"dark","name":"Dark Art & Horror","description":"Macabre, gothic, occult, and horror imagery — fear, mortality, transgression, and the sublime rendered on skin, often through realist or blackwork execution. Subject and technique are separate here: the darkness is in what is depicted, not necessarily in how it is made."}'),
  ('chicano_urban', 'Chicano & Urban', 'Styles born from street, prison, and urban art cultures — Chicano fine-line and lettering out of 1960s–70s East Los Angeles, and graffiti translated from New York subway and hip-hop aesthetics. These are visual languages of identity and place, with histories that deserve to be named, not borrowed blindly.', '{"id":"chicano_urban","name":"Chicano & Urban","description":"Styles born from street, prison, and urban art cultures — Chicano fine-line and lettering out of 1960s–70s East Los Angeles, and graffiti translated from New York subway and hip-hop aesthetics. These are visual languages of identity and place, with histories that deserve to be named, not borrowed blindly."}'),
  ('special', 'Special Purpose & Novelty', 'Styles defined not by motif but by material and purpose — UV-reactive and white ink, negative-space and silhouette design, handpoke, and paramedical work such as areola and scar restoration. Here honesty is the craft: which pieces are art, which are healing, and which carry real, evidence-based risk.', '{"id":"special","name":"Special Purpose & Novelty","description":"Styles defined not by motif but by material and purpose — UV-reactive and white ink, negative-space and silhouette design, handpoke, and paramedical work such as areola and scar restoration. Here honesty is the craft: which pieces are art, which are healing, and which carry real, evidence-based risk."}')
ON DUPLICATE KEY UPDATE
  `name` = VALUES(`name`),
  `description` = VALUES(`description`),
  `source_payload` = VALUES(`source_payload`);

INSERT INTO `technique_categories` (`category_id`, `name`, `description`, `source_payload`)
VALUES
  ('shading', 'Shading', 'Methods of building tone, gradient, and dimension in skin — soft and hard shading, whip and pepper texture, black-and-grey wash, crosshatching, and large-area gradient blending. Each is a different conversation between needle motion, ink dilution, and how the trauma will heal into value.', '{"id":"shading","name":"Shading","description":"Methods of building tone, gradient, and dimension in skin — soft and hard shading, whip and pepper texture, black-and-grey wash, crosshatching, and large-area gradient blending. Each is a different conversation between needle motion, ink dilution, and how the trauma will heal into value."}'),
  ('linework', 'Linework', 'Methods of constructing lines of different weight and character — fine, bold, broken, continuous, single-needle, script, and tapered. Needle grouping and pressure decide not only how a line looks fresh but how it holds or spreads over a decade; ''bold will hold'' is the governing rule.', '{"id":"linework","name":"Linework","description":"Methods of constructing lines of different weight and character — fine, bold, broken, continuous, single-needle, script, and tapered. Needle grouping and pressure decide not only how a line looks fresh but how it holds or spreads over a decade; ''bold will hold'' is the governing rule."}'),
  ('coloring', 'Coloring', 'Methods of placing, packing, and blending pigment — flat saturated fills, single-hue shading, wet-in-wet blends, white highlights, and watercolor effects. Every color negotiates with the skin tone beneath it and with the fading the years will bring.', '{"id":"coloring","name":"Coloring","description":"Methods of placing, packing, and blending pigment — flat saturated fills, single-hue shading, wet-in-wet blends, white highlights, and watercolor effects. Every color negotiates with the skin tone beneath it and with the fading the years will bring."}'),
  ('dotwork', 'Dotwork & Pointillism', 'Building image and tone from individual points of contact — structured dotwork, soft line-free stippling, and engineered dot-gradients. Patience is the medium: density, spacing, and scale decide whether the field reads as shadow or dissolves as it heals.', '{"id":"dotwork","name":"Dotwork & Pointillism","description":"Building image and tone from individual points of contact — structured dotwork, soft line-free stippling, and engineered dot-gradients. Patience is the medium: density, spacing, and scale decide whether the field reads as shadow or dissolves as it heals."}'),
  ('dimensional', '3D & Optical', 'Techniques that create depth, realism, and illusion — full realist rendering, cast-shadow and embossed depth effects, and optical trompe-l''œil. Their test is durability: the impact that stuns in fresh ink must still read once contrast softens with age.', '{"id":"dimensional","name":"3D & Optical","description":"Techniques that create depth, realism, and illusion — full realist rendering, cast-shadow and embossed depth effects, and optical trompe-l''œil. Their test is durability: the impact that stuns in fresh ink must still read once contrast softens with age."}'),
  ('manual', 'Manual (Machine-free)', 'Hand methods that predate or bypass the machine — hand poke, Japanese tebori, hand-tapped Pacific tatau, and Arctic skin stitching. These are not interchangeable: each carries its own tools, gestures, apprenticeship, and, in living traditions, its own lines of cultural authority.', '{"id":"manual","name":"Manual (Machine-free)","description":"Hand methods that predate or bypass the machine — hand poke, Japanese tebori, hand-tapped Pacific tatau, and Arctic skin stitching. These are not interchangeable: each carries its own tools, gestures, apprenticeship, and, in living traditions, its own lines of cultural authority."}'),
  ('specialized', 'Specialized & Effects', 'Special inks, effects, and signature textures — blackout fill, negative-space reversal, precise geometry, silhouette, tribal blackfill, etching, UV, smoke, and fire. Several depend on materials or scale whose long-term behavior and safety must be weighed honestly, not just admired fresh.', '{"id":"specialized","name":"Specialized & Effects","description":"Special inks, effects, and signature textures — blackout fill, negative-space reversal, precise geometry, silhouette, tribal blackfill, etching, UV, smoke, and fire. Several depend on materials or scale whose long-term behavior and safety must be weighed honestly, not just admired fresh."}'),
  ('process', 'Process & Craft', 'Workflow techniques rather than looks — freehand composition drawn straight onto anatomy, multi-session layering, and remedial work (cover-up and blast-over). This is the craft of sequencing and judgment, including the discipline to assess old ink and, when needed, to refuse.', '{"id":"process","name":"Process & Craft","description":"Workflow techniques rather than looks — freehand composition drawn straight onto anatomy, multi-session layering, and remedial work (cover-up and blast-over). This is the craft of sequencing and judgment, including the discipline to assess old ink and, when needed, to refuse."}')
ON DUPLICATE KEY UPDATE
  `name` = VALUES(`name`),
  `description` = VALUES(`description`),
  `source_payload` = VALUES(`source_payload`);

INSERT INTO `styles` (`style_id`, `category_id`, `name`, `description`, `history`, `distinct_features`, `narrative_description`, `narrative_language`, `source_payload`)
VALUES
  ('american_traditional', 'traditional', 'American Traditional', 'Bright, bold colors with iconic imagery like eagles, hearts, roses, daggers and nautical themes.', 'Originated in the 1930s USA, shaped by sailor and military culture; codified by Sailor Jerry Collins.', 'Bold black outlines, limited vibrant palette (red, yellow, green, blue), heavy black shading, flat two-dimensional look.', 'American Traditional belongs to the Traditional & Old School family. Bright, bold colors with iconic imagery like eagles, hearts, roses, daggers and nautical themes. Its story begins here: Originated in the 1930s USA, shaped by sailor and military culture; codified by Sailor Jerry Collins. On skin, it is recognized by bold black outlines, limited vibrant palette (red, yellow, green, blue), heavy black shading, flat two-dimensional look. Its visual vocabulary often includes eagle, anchor, swallow, rose, dagger, pin-up, and ship. The craft is commonly built with Bold Line, Color Packing, and Hard Shading. For a broader design conversation, compare it with Old School and Neo-Traditional.', 'en', '{"id":"american_traditional","name":"American Traditional","category":"traditional","description":"Bright, bold colors with iconic imagery like eagles, hearts, roses, daggers and nautical themes.","history":"Originated in the 1930s USA, shaped by sailor and military culture; codified by Sailor Jerry Collins.","distinctFeatures":"Bold black outlines, limited vibrant palette (red, yellow, green, blue), heavy black shading, flat two-dimensional look.","commonMotifs":["eagle","anchor","swallow","rose","dagger","pin-up","ship"],"relatedTechniques":["bold_line","color_packing","hard_shading"],"relatedStyles":["old_school","neo_traditional"],"sourcePaper":"STY-01","fieldNote":"The mother tongue of Western ink — say little, say it boldly, and it will still be speaking on your skin in forty years.","keyFacts":[{"text":"A U.S. lineage of bold, flash-based tattooing was codified c. 1900–1950 by Coleman, Dietzel, Grimm, Rogers, and Collins.","evidence":"synthesized"},{"text":"Its palette is a restricted set of black, red, green, yellow, and limited blue, applied as flat fills within heavy black outlines.","evidence":"direct"}]}'),
  ('old_school', 'traditional', 'Old School', 'Predecessor of American Traditional: simpler designs, minimal shading, very limited bold palette.', 'Early 20th-century Western tattooing, rooted in maritime and circus culture.', 'Simple iconic symbols, little to no depth or gradient, thick outlines.', 'Old School belongs to the Traditional & Old School family. Predecessor of American Traditional: simpler designs, minimal shading, very limited bold palette. Its story begins here: Early 20th-century Western tattooing, rooted in maritime and circus culture. On skin, it is recognized by simple iconic symbols, little to no depth or gradient, thick outlines. Its visual vocabulary often includes anchor, heart, banner, and swallow. The craft is commonly built with Bold Line and Color Packing. For a broader design conversation, compare it with American Traditional.', 'en', '{"id":"old_school","name":"Old School","category":"traditional","description":"Predecessor of American Traditional: simpler designs, minimal shading, very limited bold palette.","history":"Early 20th-century Western tattooing, rooted in maritime and circus culture.","distinctFeatures":"Simple iconic symbols, little to no depth or gradient, thick outlines.","commonMotifs":["anchor","heart","banner","swallow"],"relatedTechniques":["bold_line","color_packing"],"relatedStyles":["american_traditional"],"sourcePaper":"STY-01","fieldNote":"The same heavy grammar as American Traditional, worn as heritage; when someone says a piece will ''hold,'' this is the promise they mean.","keyFacts":[{"text":"\\"Old School\\" denotes the early-to-mid-20th-century Western idiom and functions as the antonym of \\"New School.\\"","evidence":"direct"},{"text":"It is near-synonymous with American Traditional, differing mainly in emphasis (era vs. national lineage).","evidence":"synthesized"}]}'),
  ('neo_traditional', 'traditional', 'Neo-Traditional', 'Evolution of American Traditional with more complex imagery, expanded color schemes and modern aesthetics.', 'Emerged late 20th century, blending traditional foundations with Art Nouveau and illustration influences.', 'Varied line weights, richer palettes, decorative detail, dimensional shading while keeping strong outlines.', 'Neo-Traditional belongs to the Traditional & Old School family. Evolution of American Traditional with more complex imagery, expanded color schemes and modern aesthetics. Its story begins here: Emerged late 20th century, blending traditional foundations with Art Nouveau and illustration influences. On skin, it is recognized by varied line weights, richer palettes, decorative detail, dimensional shading while keeping strong outlines. Its visual vocabulary often includes animal portraits, female faces, flowers, and ornamental frames. The craft is commonly built with Bold Line, Fine Line, Color Shading, and Color Packing. For a broader design conversation, compare it with American Traditional, New School, and Illustrative.', 'en', '{"id":"neo_traditional","name":"Neo-Traditional","category":"traditional","description":"Evolution of American Traditional with more complex imagery, expanded color schemes and modern aesthetics.","history":"Emerged late 20th century, blending traditional foundations with Art Nouveau and illustration influences.","distinctFeatures":"Varied line weights, richer palettes, decorative detail, dimensional shading while keeping strong outlines.","commonMotifs":["animal portraits","female faces","flowers","ornamental frames"],"relatedTechniques":["bold_line","fine_line","color_shading","color_packing"],"relatedStyles":["american_traditional","new_school","illustrative"],"sourcePaper":"STY-01","fieldNote":"Tradition that learned to breathe — the bold barrier stays, but the palette opens and the image gains depth.","keyFacts":[{"text":"Retains bold black outlines and color-holding black barrier while adding variable line weight, expanded palette, and depth.","evidence":"direct"},{"text":"Draws on Art Nouveau, Art Deco, and Japanese ukiyo-e.","evidence":"direct"},{"text":"Emerged in the late 20th century; exact dating contested (1970s–80s vs. late 1980s–90s).","evidence":"contested"}]}'),
  ('new_school', 'traditional', 'New School', 'Cartoon-like aesthetics with dynamic, exaggerated forms and bright colors.', 'Late 1980s–1990s, influenced by graffiti, hip-hop, comics and skate culture.', 'Exaggerated proportions, caricature, extreme color saturation, bubble-like 3D forms.', 'New School belongs to the Traditional & Old School family. Cartoon-like aesthetics with dynamic, exaggerated forms and bright colors. Its story begins here: Late 1980s–1990s, influenced by graffiti, hip-hop, comics and skate culture. On skin, it is recognized by exaggerated proportions, caricature, extreme color saturation, bubble-like 3D forms. Its visual vocabulary often includes cartoon characters, graffiti elements, and caricatures. The craft is commonly built with Bold Line, Color Packing, and Color Shading. For a broader design conversation, compare it with Neo-Traditional, Graffiti, and Cartoon.', 'en', '{"id":"new_school","name":"New School","category":"traditional","description":"Cartoon-like aesthetics with dynamic, exaggerated forms and bright colors.","history":"Late 1980s–1990s, influenced by graffiti, hip-hop, comics and skate culture.","distinctFeatures":"Exaggerated proportions, caricature, extreme color saturation, bubble-like 3D forms.","commonMotifs":["cartoon characters","graffiti elements","caricatures"],"relatedTechniques":["bold_line","color_packing","color_shading"],"relatedStyles":["neo_traditional","graffiti","cartoon"],"sourcePaper":"STY-01","fieldNote":"Volume turned all the way up: cartoon proportion, acid color, and a joy that refuses to sit still.","keyFacts":[{"text":"Characterized by heavy outlines, vivid unrestricted color, and exaggerated/cartoonish proportions.","evidence":"direct"},{"text":"Subject matter draws on comics, animation, video games, graffiti, and hip-hop culture.","evidence":"direct"},{"text":"Origins contested: 1970s West Coast vs. late 1980s–90s emergence with 1990s boom.","evidence":"contested"}]}'),
  ('realism_bg', 'realism', 'Black & Grey Realism', 'Lifelike grayscale representation emphasizing shadow, contrast and fine detail.', 'Grew from portraiture and photography traditions; refined in 1970s California prison and street culture.', 'No outlines, smooth grey wash gradients, high detail and depth.', 'Black & Grey Realism belongs to the Realism family. Lifelike grayscale representation emphasizing shadow, contrast and fine detail. Its story begins here: Grew from portraiture and photography traditions; refined in 1970s California prison and street culture. On skin, it is recognized by no outlines, smooth grey wash gradients, high detail and depth. Its visual vocabulary often includes portraits, animals, statues, and nature scenes. The craft is commonly built with Black & Grey Wash, Soft Shading, and Layering. For a broader design conversation, compare it with Color Realism, Portrait, and Chicano.', 'en', '{"id":"realism_bg","name":"Black & Grey Realism","category":"realism","description":"Lifelike grayscale representation emphasizing shadow, contrast and fine detail.","history":"Grew from portraiture and photography traditions; refined in 1970s California prison and street culture.","distinctFeatures":"No outlines, smooth grey wash gradients, high detail and depth.","commonMotifs":["portraits","animals","statues","nature scenes"],"relatedTechniques":["black_and_grey_wash","soft_shading","layering"],"relatedStyles":["realism_color","portrait","chicano"],"sourcePaper":"STY-02","fieldNote":"Born in California prisons from a single needle and diluted black — restraint became its own kind of beauty.","keyFacts":[{"text":"Black & grey realism originated in 1960s–70s California prisons among Chicano inmates using homemade single-needle machines and diluted black ink.","evidence":"direct"},{"text":"Good Time Charlie''s Tattooland, opened 1975 on Whittier Blvd, East LA, by Charlie Cartwright with Jack Rudy, was the first professional shop to commit fully to single-needle black-and-grey custom work.","evidence":"direct"}]}'),
  ('realism_color', 'realism', 'Color Realism', 'Full-color, lifelike depiction of subjects with photographic accuracy.', 'Enabled by advances in pigments and machines from the 1990s onward.', 'Lifelike coloration, subtle color transitions, no visible outlines, painterly layering.', 'Color Realism belongs to the Realism family. Full-color, lifelike depiction of subjects with photographic accuracy. Its story begins here: Enabled by advances in pigments and machines from the 1990s onward. On skin, it is recognized by lifelike coloration, subtle color transitions, no visible outlines, painterly layering. Its visual vocabulary often includes portraits, flowers, animals, and film characters. The craft is commonly built with Color Blending, Layering, White Highlights, and Soft Shading. For a broader design conversation, compare it with Black & Grey Realism and Hyperrealism.', 'en', '{"id":"realism_color","name":"Color Realism","category":"realism","description":"Full-color, lifelike depiction of subjects with photographic accuracy.","history":"Enabled by advances in pigments and machines from the 1990s onward.","distinctFeatures":"Lifelike coloration, subtle color transitions, no visible outlines, painterly layering.","commonMotifs":["portraits","flowers","animals","film characters"],"relatedTechniques":["color_blending","layering","white_highlights","soft_shading"],"relatedStyles":["realism_bg","hyperrealism"],"sourcePaper":"STY-02","fieldNote":"The full spectrum of a photograph laid into skin; wait for the machines and pigments that make it possible, then respect what fades.","keyFacts":[{"text":"Color realism emerged after black-and-grey, enabled by 1990s–2000s advances in rotary machines, fine needle cartridges, and pigment chemistry.","evidence":"synthesized"},{"text":"Nikko Hurtado (b. 1981) is widely credited in trade sources as a pioneer of color realism/portraiture, beginning tattooing in 2002.","evidence":"community_attested"}]}'),
  ('portrait', 'realism', 'Portrait', 'Realistic depiction of human or animal faces capturing likeness and expression.', 'Gained popularity with the rise of photorealism in the late 20th century.', 'Extreme attention to facial nuance, eyes and skin texture; usually from photo reference.', 'Portrait belongs to the Realism family. Realistic depiction of human or animal faces capturing likeness and expression. Its story begins here: Gained popularity with the rise of photorealism in the late 20th century. On skin, it is recognized by extreme attention to facial nuance, eyes and skin texture; usually from photo reference. Its visual vocabulary often includes family members, celebrities, pets, and memorial portraits. The craft is commonly built with Soft Shading, Black & Grey Wash, Layering, and White Highlights. For a broader design conversation, compare it with Black & Grey Realism, Color Realism, and Micro Realism.', 'en', '{"id":"portrait","name":"Portrait","category":"realism","description":"Realistic depiction of human or animal faces capturing likeness and expression.","history":"Gained popularity with the rise of photorealism in the late 20th century.","distinctFeatures":"Extreme attention to facial nuance, eyes and skin texture; usually from photo reference.","commonMotifs":["family members","celebrities","pets","memorial portraits"],"relatedTechniques":["soft_shading","black_and_grey_wash","layering","white_highlights"],"relatedStyles":["realism_bg","realism_color","micro_realism"],"sourcePaper":"STY-02","fieldNote":"A face is a promise to time — carve it so it is still that face when the years have softened every line.","keyFacts":[{"text":"Portrait tattooing is a subject-matter specialization practiced within both black-and-grey and color-realism technique.","evidence":"synthesized"},{"text":"Bob Tyrrell began tattooing at 29, completed apprenticeship at 34, and is known primarily for black-and-grey portrait realism.","evidence":"direct"}]}'),
  ('micro_realism', 'realism', 'Micro Realism', 'Realistic subjects rendered at very small scale with intricate detail work.', '2010s trend driven by single-needle cartridges and social media aesthetics.', 'Miniaturized yet detailed depictions, fine needles, delicate greywash.', 'Micro Realism belongs to the Realism family. Realistic subjects rendered at very small scale with intricate detail work. Its story begins here: 2010s trend driven by single-needle cartridges and social media aesthetics. On skin, it is recognized by miniaturized yet detailed depictions, fine needles, delicate greywash. Its visual vocabulary often includes tiny portraits, miniature landscapes, and small objects. The craft is commonly built with Single Needle, Fine Line, and Soft Shading. For a broader design conversation, compare it with Portrait, Fine Line, and Minimalist.', 'en', '{"id":"micro_realism","name":"Micro Realism","category":"realism","description":"Realistic subjects rendered at very small scale with intricate detail work.","history":"2010s trend driven by single-needle cartridges and social media aesthetics.","distinctFeatures":"Miniaturized yet detailed depictions, fine needles, delicate greywash.","commonMotifs":["tiny portraits","miniature landscapes","small objects"],"relatedTechniques":["single_needle","fine_line","soft_shading"],"relatedStyles":["portrait","fineline_style","minimalist"],"sourcePaper":"STY-02","fieldNote":"A whole scene the size of a coin; leave it room to spread, because the skin will insist.","keyFacts":[{"text":"Micro-realism''s technical roots trace to 1970s single-needle tattooing; its emergence as a named mainstream trend is a 2010s–2020s, social-media-driven phenomenon.","evidence":"synthesized"},{"text":"Micro-realism uses single-needle/very fine needle configurations (#3 round liner and smaller) and requires deliberate tonal compression and spacing calibrated for future pigment spread.","evidence":"direct"}]}'),
  ('hyperrealism', 'realism', 'Hyperrealism', 'Realism pushed beyond photographic accuracy — texture, moisture and light rendered in extreme detail.', '2000s evolution of realism paralleling the hyperrealist art movement.', 'Illusion of three-dimensionality, extreme micro-contrast, painstaking texture work.', 'Hyperrealism belongs to the Realism family. Realism pushed beyond photographic accuracy — texture, moisture and light rendered in extreme detail. Its story begins here: 2000s evolution of realism paralleling the hyperrealist art movement. On skin, it is recognized by illusion of three-dimensionality, extreme micro-contrast, painstaking texture work. Its visual vocabulary often includes eyes, water drops, torn-skin effects, and metallic surfaces. The craft is commonly built with Layering, Depth Effects, White Highlights, and Soft Shading. For a broader design conversation, compare it with Color Realism and 3D / Optical Illusion.', 'en', '{"id":"hyperrealism","name":"Hyperrealism","category":"realism","description":"Realism pushed beyond photographic accuracy — texture, moisture and light rendered in extreme detail.","history":"2000s evolution of realism paralleling the hyperrealist art movement.","distinctFeatures":"Illusion of three-dimensionality, extreme micro-contrast, painstaking texture work.","commonMotifs":["eyes","water drops","torn-skin effects","metallic surfaces"],"relatedTechniques":["layering","depth_effects","white_highlights","soft_shading"],"relatedStyles":["realism_color","3d_style"],"sourcePaper":"STY-02","fieldNote":"Realism that outshouts the photograph — impossible contrast and depth, dazzling now, demanding of the future.","keyFacts":[{"text":"Hyperrealism is defined in trade sources as realism pushed beyond photographic accuracy toward intensified contrast, impossible depth of field, and exaggerated reflective/textural effects.","evidence":"direct"},{"text":"A Russian/Eastern European wave (Dmitriy Samohin, Valentina Ryabova) is associated with pushing realism toward hyperrealism and softer, higher-fidelity gradients.","evidence":"community_attested"}]}'),
  ('surrealism', 'realism', 'Surrealism', 'Dream-like imagery blending realistic rendering with abstract or fantastical elements.', 'Inspired by the Surrealist art movement of the early 20th century (Dalí, Magritte).', 'Impossible juxtapositions, morphing objects, realistic technique applied to unreal scenes.', 'Surrealism belongs to the Realism family. Dream-like imagery blending realistic rendering with abstract or fantastical elements. Its story begins here: Inspired by the Surrealist art movement of the early 20th century (Dalí, Magritte). On skin, it is recognized by impossible juxtapositions, morphing objects, realistic technique applied to unreal scenes. Its visual vocabulary often includes melting objects, floating elements, and hybrid creatures. The craft is commonly built with Soft Shading, Color Blending, and Smoke Effect. For a broader design conversation, compare it with Color Realism, Trash Polka, and Abstract.', 'en', '{"id":"surrealism","name":"Surrealism","category":"realism","description":"Dream-like imagery blending realistic rendering with abstract or fantastical elements.","history":"Inspired by the Surrealist art movement of the early 20th century (Dalí, Magritte).","distinctFeatures":"Impossible juxtapositions, morphing objects, realistic technique applied to unreal scenes.","commonMotifs":["melting objects","floating elements","hybrid creatures"],"relatedTechniques":["soft_shading","color_blending","smoke_effect"],"relatedStyles":["realism_color","trash_polka","abstract"],"sourcePaper":"STY-02","fieldNote":"Dream logic rendered with a realist''s hand, so the impossible arrives looking true.","keyFacts":[{"text":"Surrealism as a tattoo style derives directly from the early-20th-century Surrealist art movement (Dalí, Magritte, Ernst), formally launched by Breton''s 1924 Manifesto.","evidence":"direct"},{"text":"Surrealist tattoos typically render dreamlike/impossible content (melting clocks, morphing forms, hybrid creatures) using realist technique to heighten the effect.","evidence":"direct"}]}'),
  ('trash_polka', 'modern', 'Trash Polka', 'Chaotic collage combining realism with graphic ''trash'' elements, almost always in black and red.', 'Created in the late 1990s by Simone Pfaff and Volko Merschky at Buena Vista Tattoo Club, Germany.', 'Black + red palette, mix of photorealism, smears, brush strokes, typography and geometric chaos.', 'Trash Polka belongs to the Modern & Experimental family. Chaotic collage combining realism with graphic ''trash'' elements, almost always in black and red. Its story begins here: Created in the late 1990s by Simone Pfaff and Volko Merschky at Buena Vista Tattoo Club, Germany. On skin, it is recognized by black + red palette, mix of photorealism, smears, brush strokes, typography and geometric chaos. Its visual vocabulary often includes realistic faces, lettering fragments, ink splatters, and crosses. The craft is commonly built with Brush Stroke, Soft Shading, Color Packing, and Bold Line. For a broader design conversation, compare it with Black & Grey Realism, Abstract, and Sketch Style.', 'en', '{"id":"trash_polka","name":"Trash Polka","category":"modern","description":"Chaotic collage combining realism with graphic ''trash'' elements, almost always in black and red.","history":"Created in the late 1990s by Simone Pfaff and Volko Merschky at Buena Vista Tattoo Club, Germany.","distinctFeatures":"Black + red palette, mix of photorealism, smears, brush strokes, typography and geometric chaos.","commonMotifs":["realistic faces","lettering fragments","ink splatters","crosses"],"relatedTechniques":["brush_stroke","soft_shading","color_packing","bold_line"],"relatedStyles":["realism_bg","abstract","sketch"],"sourcePaper":"STY-07","fieldNote":"Red, black, and controlled chaos — collage that feels torn from a life rather than composed for one.","keyFacts":[{"text":"Trash Polka was created in 1998 by Volker Merschky and Simone Pfaff at the Buena Vista Tattoo Club, Würzburg, Germany.","evidence":"direct"},{"text":"\\"TRASH POLKA®\\" is a registered trademark of its creators.","evidence":"direct"}]}'),
  ('biomechanical', 'modern', 'Biomechanical', 'Fuses organic anatomy with mechanical elements — pistons, gears and cables under torn skin.', 'Popularized in the 1980s–90s, heavily influenced by H.R. Giger''s Alien aesthetics.', 'Flowing fusion of muscle, bone and machine; strong 3D depth; usually follows body contours.', 'Biomechanical belongs to the Modern & Experimental family. Fuses organic anatomy with mechanical elements — pistons, gears and cables under torn skin. Its story begins here: Popularized in the 1980s–90s, heavily influenced by H.R. Giger''s Alien aesthetics. On skin, it is recognized by flowing fusion of muscle, bone and machine; strong 3D depth; usually follows body contours. Its visual vocabulary often includes gears, pistons, torn skin, and cybernetic limbs. The craft is commonly built with Depth Effects, Soft Shading, and Layering. For a broader design conversation, compare it with Bio-organic, 3D / Optical Illusion, and Horror.', 'en', '{"id":"biomechanical","name":"Biomechanical","category":"modern","description":"Fuses organic anatomy with mechanical elements — pistons, gears and cables under torn skin.","history":"Popularized in the 1980s–90s, heavily influenced by H.R. Giger''s Alien aesthetics.","distinctFeatures":"Flowing fusion of muscle, bone and machine; strong 3D depth; usually follows body contours.","commonMotifs":["gears","pistons","torn skin","cybernetic limbs"],"relatedTechniques":["depth_effects","soft_shading","layering"],"relatedStyles":["bioorganic","3d_style","horror"],"sourcePaper":"STY-07","fieldNote":"Giger''s machine-flesh, wrapped to the muscle so the metal seems to move when you do.","keyFacts":[{"text":"H.R. Giger (1940–2014) designed the creatures for Alien (1979); his 1977 book Necronomicon became foundational biomech reference material.","evidence":"direct"},{"text":"Guy Aitchison, alongside Aaron Cain, adapted Giger''s aesthetic into an original tattoo-specific style from the late 1980s–early 1990s, introducing color and 3D illusion techniques absent from Giger''s monochrome painting.","evidence":"direct"}]}'),
  ('bioorganic', 'modern', 'Bio-organic', 'Like biomechanical but purely organic: bone, sinew, alien flora and natural textures.', 'Offshoot of biomech from the 1990s, moving away from machinery toward natural forms.', 'Flowing organic shapes fitted to musculature, no mechanical parts.', 'Bio-organic belongs to the Modern & Experimental family. Like biomechanical but purely organic: bone, sinew, alien flora and natural textures. Its story begins here: Offshoot of biomech from the 1990s, moving away from machinery toward natural forms. On skin, it is recognized by flowing organic shapes fitted to musculature, no mechanical parts. Its visual vocabulary often includes bone structures, tendrils, shells, and alien plants. The craft is commonly built with Depth Effects and Soft Shading. For a broader design conversation, compare it with Biomechanical and Abstract.', 'en', '{"id":"bioorganic","name":"Bio-organic","category":"modern","description":"Like biomechanical but purely organic: bone, sinew, alien flora and natural textures.","history":"Offshoot of biomech from the 1990s, moving away from machinery toward natural forms.","distinctFeatures":"Flowing organic shapes fitted to musculature, no mechanical parts.","commonMotifs":["bone structures","tendrils","shells","alien plants"],"relatedTechniques":["depth_effects","soft_shading"],"relatedStyles":["biomechanical","abstract"],"sourcePaper":"STY-07","fieldNote":"Biomechanical''s softer cousin — the same flowing depth, but grown rather than built.","keyFacts":[{"text":"Bio-organic is an offshoot of biomechanical substituting organic forms for mechanical ones, with no specific named originator identified in sources reviewed.","evidence":"hypothesis"}]}'),
  ('chicano', 'chicano_urban', 'Chicano', 'Fine-line black and grey rooted in Mexican-American culture: script, religious icons and portraits.', 'Originated in Chicano communities and prisons of the 1940s–50s American Southwest; the Pachuco cross and single-needle style.', 'Smooth grey shading, fine single-needle lines, script lettering, religious and street iconography.', 'Chicano belongs to the Chicano & Urban family. Fine-line black and grey rooted in Mexican-American culture: script, religious icons and portraits. Its story begins here: Originated in Chicano communities and prisons of the 1940s–50s American Southwest; the Pachuco cross and single-needle style. On skin, it is recognized by smooth grey shading, fine single-needle lines, script lettering, religious and street iconography. Its visual vocabulary often includes Virgin Mary, payasas (clown girls), lowriders, rosaries, and script. The craft is commonly built with Single Needle, Fine Line, Black & Grey Wash, and Script Lettering. For a broader design conversation, compare it with Black & Grey Realism, Lettering / Script, and Religious / Spiritual.', 'en', '{"id":"chicano","name":"Chicano","category":"chicano_urban","description":"Fine-line black and grey rooted in Mexican-American culture: script, religious icons and portraits.","history":"Originated in Chicano communities and prisons of the 1940s–50s American Southwest; the Pachuco cross and single-needle style.","distinctFeatures":"Smooth grey shading, fine single-needle lines, script lettering, religious and street iconography.","commonMotifs":["Virgin Mary","payasas (clown girls)","lowriders","rosaries","script"],"relatedTechniques":["single_needle","fine_line","black_and_grey_wash","script_lettering"],"relatedStyles":["realism_bg","lettering_script","religious"],"sourcePaper":"STY-08","fieldNote":"Fine grey line out of East L.A. — devotion, lettering, and loyalty written in the quietest possible stroke.","keyFacts":[{"text":"Chicano tattooing''s fine-line, single-needle Old English/blackletter script tradition originated in 1960s–70s East Los Angeles Chicano prison and street culture (full sourcing in STY-02/STY-03).","evidence":"direct"},{"text":"This lettering tradition is a direct, documented historical source feeding the contemporary international calligraffiti movement via artists such as Big Sleeps.","evidence":"direct"}]}'),
  ('graffiti', 'chicano_urban', 'Graffiti', 'Street-art inspired style with bold colors, wildstyle lettering and urban themes.', 'Evolved from urban graffiti culture, entering tattooing in the late 20th century.', 'Spray-paint effects, drips, wildstyle typography, high saturation.', 'Graffiti belongs to the Chicano & Urban family. Street-art inspired style with bold colors, wildstyle lettering and urban themes. Its story begins here: Evolved from urban graffiti culture, entering tattooing in the late 20th century. On skin, it is recognized by spray-paint effects, drips, wildstyle typography, high saturation. Its visual vocabulary often includes tags, bubble letters, spray cans, and urban scenes. The craft is commonly built with Color Packing, Bold Line, and Brush Stroke. For a broader design conversation, compare it with New School, Lettering / Script, and Ignorant Style.', 'en', '{"id":"graffiti","name":"Graffiti","category":"chicano_urban","description":"Street-art inspired style with bold colors, wildstyle lettering and urban themes.","history":"Evolved from urban graffiti culture, entering tattooing in the late 20th century.","distinctFeatures":"Spray-paint effects, drips, wildstyle typography, high saturation.","commonMotifs":["tags","bubble letters","spray cans","urban scenes"],"relatedTechniques":["color_packing","bold_line","brush_stroke"],"relatedStyles":["new_school","lettering_script","ignorant"],"sourcePaper":"STY-08","fieldNote":"The subway wall brought to skin; keep the piece bold, because spray-paint delicacy will not survive the years.","keyFacts":[{"text":"Graffiti-style tattooing translates 1970s–80s New York subway/hip-hop street culture''s spray-paint aesthetics into tattoo form, sharing letterform DNA with lettering_script and calligraphy while retaining a distinct transmission history.","evidence":"synthesized"}]}'),
  ('tribal', 'cultural', 'Tribal (Modern)', 'Bold, symmetrical black patterns inspired by indigenous art, abstracted for modern tastes.', '1990s Western adaptation of Polynesian and Bornean motifs (''neotribal wave'').', 'Solid black fills, sharp spikes and curves, symmetry, flow along muscle lines.', 'Tribal (Modern) belongs to the Cultural & Tribal family. Bold, symmetrical black patterns inspired by indigenous art, abstracted for modern tastes. Its story begins here: 1990s Western adaptation of Polynesian and Bornean motifs (''neotribal wave''). On skin, it is recognized by solid black fills, sharp spikes and curves, symmetry, flow along muscle lines. Its visual vocabulary often includes abstract spikes, armbands, and sun symbols. The craft is commonly built with Color Packing, Bold Line, and Tribal Blackfill. For a broader design conversation, compare it with Polynesian, Māori / Tā Moko, Neo-Tribal, and Blackwork.', 'en', '{"id":"tribal","name":"Tribal (Modern)","category":"cultural","description":"Bold, symmetrical black patterns inspired by indigenous art, abstracted for modern tastes.","history":"1990s Western adaptation of Polynesian and Bornean motifs (''neotribal wave'').","distinctFeatures":"Solid black fills, sharp spikes and curves, symmetry, flow along muscle lines.","commonMotifs":["abstract spikes","armbands","sun symbols"],"relatedTechniques":["color_packing","bold_line","tribal_blackfill"],"relatedStyles":["polynesian","maori","neotribal","blackwork_style"],"sourcePaper":"STY-04","fieldNote":"A Western abstraction of borrowed Pacific vocabulary — beautiful, but know it is a translation, not a lineage.","keyFacts":[{"text":"Modern Western \\"tribal\\" tattooing is a late-20th-century abstraction of Polynesian/Bornean visual vocabulary for a non-Indigenous market, distinct from the living source traditions.","evidence":"synthesized"},{"text":"The style''s promotional framing (e.g., in blackout marketing) as drawing on Polynesian tradition should not be read as replicating that tradition''s ritual/status function.","evidence":"synthesized"}]}'),
  ('maori', 'cultural', 'Māori / Tā Moko', 'Complex spirals and patterns traditionally representing Māori genealogy, status and identity.', 'Indigenous art form of the Māori people of New Zealand; traditionally carved with uhi chisels.', 'Koru spirals, facial moko, flowing lines mapped to anatomy, deep cultural protocol.', 'Māori / Tā Moko belongs to the Cultural & Tribal family. Complex spirals and patterns traditionally representing Māori genealogy, status and identity. Its story begins here: Indigenous art form of the Māori people of New Zealand; traditionally carved with uhi chisels. On skin, it is recognized by koru spirals, facial moko, flowing lines mapped to anatomy, deep cultural protocol. Its visual vocabulary often includes koru (spiral), manaia, and facial moko. The craft is commonly built with Hand-Tapped (Tatau), Bold Line, and Tribal Blackfill. For a broader design conversation, compare it with Polynesian and Tribal (Modern).', 'en', '{"id":"maori","name":"Māori / Tā Moko","category":"cultural","description":"Complex spirals and patterns traditionally representing Māori genealogy, status and identity.","history":"Indigenous art form of the Māori people of New Zealand; traditionally carved with uhi chisels.","distinctFeatures":"Koru spirals, facial moko, flowing lines mapped to anatomy, deep cultural protocol.","commonMotifs":["koru (spiral)","manaia","facial moko"],"relatedTechniques":["hand_tapped","bold_line","tribal_blackfill"],"relatedStyles":["polynesian","tribal"],"sourcePaper":"STY-04","fieldNote":"Tā moko is whakapapa cut into the face under sacred authority; I can honor its rhythm, never reproduce its marks.","keyFacts":[{"text":"Tā moko is applied traditionally with uhi (chisels) under tohunga-tā-moko authority and tapu (sacred) protocol, encoding whakapapa and rank.","evidence":"direct"},{"text":"Colonial contact included the toi moko trade in preserved tattooed Māori heads, a significant disruption/commodification of the practice.","evidence":"direct"},{"text":"Views on whether/how non-Māori may appropriately receive adapted tā moko vary within the Māori community; this is an active, contested conversation.","evidence":"contested"}]}'),
  ('polynesian', 'cultural', 'Polynesian', 'Intricate geometric patterns telling stories of ancestry, protection and social status.', 'Ancient traditions of Samoa, Tahiti, Marquesas, Hawaii and Tonga; each island has a distinct visual language. Source of the word ''tattoo'' (tatau).', 'Dense band compositions of repeated symbols (shark teeth, waves, spearheads), solid black.', 'Polynesian belongs to the Cultural & Tribal family. Intricate geometric patterns telling stories of ancestry, protection and social status. Its story begins here: Ancient traditions of Samoa, Tahiti, Marquesas, Hawaii and Tonga; each island has a distinct visual language. Source of the word ''tattoo'' (tatau). On skin, it is recognized by dense band compositions of repeated symbols (shark teeth, waves, spearheads), solid black. Its visual vocabulary often includes enata (people), shark teeth, ocean waves, turtles, and tiki. The craft is commonly built with Hand-Tapped (Tatau), Tribal Blackfill, and Bold Line. For a broader design conversation, compare it with Māori / Tā Moko, Samoan (Pe''a / Malu), Marquesan, and Tribal (Modern).', 'en', '{"id":"polynesian","name":"Polynesian","category":"cultural","description":"Intricate geometric patterns telling stories of ancestry, protection and social status.","history":"Ancient traditions of Samoa, Tahiti, Marquesas, Hawaii and Tonga; each island has a distinct visual language. Source of the word ''tattoo'' (tatau).","distinctFeatures":"Dense band compositions of repeated symbols (shark teeth, waves, spearheads), solid black.","commonMotifs":["enata (people)","shark teeth","ocean waves","turtles","tiki"],"relatedTechniques":["hand_tapped","tribal_blackfill","bold_line"],"relatedStyles":["maori","samoan","marquesan","tribal"],"sourcePaper":"STY-04","fieldNote":"The very word ''tattoo'' sailed to us from tatau — the ocean''s own way of writing rank and belonging.","keyFacts":[{"text":"The English word \\"tattoo\\" derives from Tahitian/Samoan tatau (Marquesan tatu), first recorded in English via Joseph Banks''s journal and Captain Cook''s 1769 voyage account.","evidence":"direct"},{"text":"Omai (Mai), a Tahitian/Raiatean traveler, sailed to England with Cook''s second voyage (1774) and was portrayed tattooed by Joshua Reynolds.","evidence":"direct"}]}'),
  ('samoan', 'cultural', 'Samoan (Pe''a / Malu)', 'Traditional Samoan tattooing: the male pe''a (waist to knee) and female malu.', 'Unbroken hand-tapped tradition performed by tufuga tā tatau master artists.', 'Dense geometric coverage applied in ritual sessions with hand-made combs.', 'Samoan (Pe''a / Malu) belongs to the Cultural & Tribal family. Traditional Samoan tattooing: the male pe''a (waist to knee) and female malu. Its story begins here: Unbroken hand-tapped tradition performed by tufuga tā tatau master artists. On skin, it is recognized by dense geometric coverage applied in ritual sessions with hand-made combs. Its visual vocabulary often includes geometric bands, canoe motifs, and flying fox. The craft is commonly built with Hand-Tapped (Tatau) and Tribal Blackfill. For a broader design conversation, compare it with Polynesian and Māori / Tā Moko.', 'en', '{"id":"samoan","name":"Samoan (Pe''a / Malu)","category":"cultural","description":"Traditional Samoan tattooing: the male pe''a (waist to knee) and female malu.","history":"Unbroken hand-tapped tradition performed by tufuga tā tatau master artists.","distinctFeatures":"Dense geometric coverage applied in ritual sessions with hand-made combs.","commonMotifs":["geometric bands","canoe motifs","flying fox"],"relatedTechniques":["hand_tapped","tribal_blackfill"],"relatedStyles":["polynesian","maori"],"sourcePaper":"STY-04","fieldNote":"The pe''a and malu are given by a tufuga under hereditary authority — earned, not ordered from a menu.","keyFacts":[{"text":"Samoan tatau (pe''a for men, malu for women) has been practiced with Indigenous technique continuously since before European contact — one of the few Pacific traditions with this unbroken continuity.","evidence":"direct"},{"text":"The tufuga tā tatau role is hereditary, held primarily by the Sā Su''a and Sā Tulou''ena family lines.","evidence":"direct"}]}'),
  ('marquesan', 'cultural', 'Marquesan', 'Marquesas Islands patterns — among the most complex in Polynesia, once covering the whole body.', 'Ancient Marquesan practice documented by early European voyagers; revived in the 20th century.', 'Checkerboards, tiki faces, ipu motifs, dense symbolic grammar.', 'Marquesan belongs to the Cultural & Tribal family. Marquesas Islands patterns — among the most complex in Polynesia, once covering the whole body. Its story begins here: Ancient Marquesan practice documented by early European voyagers; revived in the 20th century. On skin, it is recognized by checkerboards, tiki faces, ipu motifs, dense symbolic grammar. Its visual vocabulary often includes tiki, mata hoata (eyes), and checkerboard. The craft is commonly built with Hand-Tapped (Tatau) and Tribal Blackfill. For a broader design conversation, compare it with Polynesian.', 'en', '{"id":"marquesan","name":"Marquesan","category":"cultural","description":"Marquesas Islands patterns — among the most complex in Polynesia, once covering the whole body.","history":"Ancient Marquesan practice documented by early European voyagers; revived in the 20th century.","distinctFeatures":"Checkerboards, tiki faces, ipu motifs, dense symbolic grammar.","commonMotifs":["tiki","mata hoata (eyes)","checkerboard"],"relatedTechniques":["hand_tapped","tribal_blackfill"],"relatedStyles":["polynesian"],"sourcePaper":"STY-04","fieldNote":"Dense geometric skin-cover documented by 18th-century voyagers — a full-body script of identity.","keyFacts":[{"text":"Marquesan tattooing (patutiki) was documented by 18th-century voyagers (Georg Forster, 1777; Étienne Marchand, 1791) as covering the body extensively in geometric and figurative motifs.","evidence":"direct"},{"text":"Tattooing was outlawed by colonial church and state authorities in the Marquesas in the early 20th century, compounding a population collapse to roughly 2,000 survivors (about 97% loss) by 1920.","evidence":"direct"}]}'),
  ('celtic', 'cultural', 'Celtic', 'Interlaced knotwork, spirals and crosses from Insular Celtic art.', 'Based on early medieval manuscript and stone art (Book of Kells); revived in 20th-century tattooing.', 'Endless knots, plaits, triskelions, usually blackwork or green-accented.', 'Celtic belongs to the Cultural & Tribal family. Interlaced knotwork, spirals and crosses from Insular Celtic art. Its story begins here: Based on early medieval manuscript and stone art (Book of Kells); revived in 20th-century tattooing. On skin, it is recognized by endless knots, plaits, triskelions, usually blackwork or green-accented. Its visual vocabulary often includes Celtic knot, triskelion, Celtic cross, and tree of life. The craft is commonly built with Bold Line, Fine Line, and Tribal Blackfill. For a broader design conversation, compare it with Blackwork and Ornamental.', 'en', '{"id":"celtic","name":"Celtic","category":"cultural","description":"Interlaced knotwork, spirals and crosses from Insular Celtic art.","history":"Based on early medieval manuscript and stone art (Book of Kells); revived in 20th-century tattooing.","distinctFeatures":"Endless knots, plaits, triskelions, usually blackwork or green-accented.","commonMotifs":["Celtic knot","triskelion","Celtic cross","tree of life"],"relatedTechniques":["bold_line","fine_line","tribal_blackfill"],"relatedStyles":["blackwork_style","ornamental"],"sourcePaper":"STY-04","fieldNote":"Interlace out of Insular manuscript art; its knots are medieval and Christian, not a generic ''ancient'' pattern.","keyFacts":[{"text":"Celtic interlace knotwork first appears in Insular Christian manuscript art of the 7th century CE (Book of Kells, c. 800 CE), not in the Iron Age Celtic period (c. 800 BCE–100 CE) popularly associated with the style.","evidence":"direct"},{"text":"Evidence for ancient (pre-Christian) Celtic tattooing is sparse and rests mainly on secondhand Roman accounts (Caesar, Herodian) of body paint/possible tattooing, not direct evidence of the specific knotwork patterns.","evidence":"contested"}]}'),
  ('aztec_maya', 'cultural', 'Aztec / Maya', 'Pre-Columbian Mesoamerican iconography: gods, calendars, warriors and glyphs.', 'Draws on Aztec and Maya stone carving and codices; strong in Chicano-adjacent culture.', 'Stone-relief texture, sun calendars, feathered serpents, often black and grey.', 'Aztec / Maya belongs to the Cultural & Tribal family. Pre-Columbian Mesoamerican iconography: gods, calendars, warriors and glyphs. Its story begins here: Draws on Aztec and Maya stone carving and codices; strong in Chicano-adjacent culture. On skin, it is recognized by stone-relief texture, sun calendars, feathered serpents, often black and grey. Its visual vocabulary often includes Quetzalcoatl, sun stone, eagle warrior, and glyphs. The craft is commonly built with Black & Grey Wash, Etching / Engraving, and Soft Shading. For a broader design conversation, compare it with Chicano, Black & Grey Realism, and Tribal (Modern).', 'en', '{"id":"aztec_maya","name":"Aztec / Maya","category":"cultural","description":"Pre-Columbian Mesoamerican iconography: gods, calendars, warriors and glyphs.","history":"Draws on Aztec and Maya stone carving and codices; strong in Chicano-adjacent culture.","distinctFeatures":"Stone-relief texture, sun calendars, feathered serpents, often black and grey.","commonMotifs":["Quetzalcoatl","sun stone","eagle warrior","glyphs"],"relatedTechniques":["black_and_grey_wash","etching_technique","soft_shading"],"relatedStyles":["chicano","realism_bg","tribal"],"sourcePaper":"STY-04","fieldNote":"Mesoamerican marks known mostly through colonial chronicles — hold the gaps in the record honestly.","keyFacts":[{"text":"Friar Diego de Landa''s 1566 *Relación de las cosas de Yucatán* provides key documentary evidence of Maya tattooing practice, describing its painful application and status significance.","evidence":"direct"},{"text":"Archaeological/iconographic evidence (Jaina Island, Palenque figurines) shows Maya facial tattooing/scarification tied to individual identity, sometimes incorporating hieroglyphic birth-date signs.","evidence":"direct"},{"text":"Evidence for Aztec/Mexica tattooing specifically is markedly weaker and disputed; the Florentine Codex references tattoo-like marking among the neighboring Huastec rather than confirming widespread Aztec practice.","evidence":"contested"}]}'),
  ('haida', 'cultural', 'Haida / Pacific Northwest', 'Formline art of the Pacific Northwest Coast peoples: ovoids, U-forms and split representations of animals.', 'Traditional crest art of Haida, Tlingit and neighboring nations, adapted to skin.', 'Black and red formline, bilateral symmetry, stylized ravens, orcas and bears.', 'Haida / Pacific Northwest belongs to the Cultural & Tribal family. Formline art of the Pacific Northwest Coast peoples: ovoids, U-forms and split representations of animals. Its story begins here: Traditional crest art of Haida, Tlingit and neighboring nations, adapted to skin. On skin, it is recognized by black and red formline, bilateral symmetry, stylized ravens, orcas and bears. Its visual vocabulary often includes raven, orca, bear, and thunderbird. The craft is commonly built with Bold Line and Color Packing. For a broader design conversation, compare it with Tribal (Modern) and Blackwork.', 'en', '{"id":"haida","name":"Haida / Pacific Northwest","category":"cultural","description":"Formline art of the Pacific Northwest Coast peoples: ovoids, U-forms and split representations of animals.","history":"Traditional crest art of Haida, Tlingit and neighboring nations, adapted to skin.","distinctFeatures":"Black and red formline, bilateral symmetry, stylized ravens, orcas and bears.","commonMotifs":["raven","orca","bear","thunderbird"],"relatedTechniques":["bold_line","color_packing"],"relatedStyles":["tribal","blackwork_style"],"sourcePaper":"STY-04","fieldNote":"Crest tattoos that name hereditary clan and house — ownership worn on the body under Northwest Coast authority.","keyFacts":[{"text":"Haida/Tlingit crest tattooing marked hereditary moiety/clan/house crest ownership, historically applied at potlatch ceremonies.","evidence":"direct"},{"text":"Colonial-era potlatch bans disrupted transmission of this practice; precise ban dates are inconsistently reported across sources reviewed.","evidence":"contested"}]}'),
  ('irezumi', 'japanese', 'Japanese Irezumi', 'Large-scale, colorful designs of mythological creatures, flowers, waves and warriors.', 'Developed during the Edo period (1603–1868), tied to ukiyo-e woodblock prints and firemen/laborer culture.', 'Full-body composition (bodysuit), background of wind/waves/clouds, strict motif symbolism and seasonal pairing.', 'Japanese Irezumi belongs to the Japanese family. Large-scale, colorful designs of mythological creatures, flowers, waves and warriors. Its story begins here: Developed during the Edo period (1603–1868), tied to ukiyo-e woodblock prints and firemen/laborer culture. On skin, it is recognized by full-body composition (bodysuit), background of wind/waves/clouds, strict motif symbolism and seasonal pairing. Its visual vocabulary often includes koi, dragon, hannya mask, peony, cherry blossom, tiger, and waves. The craft is commonly built with Bold Line, Color Packing, Color Shading, and Black & Grey Wash. For a broader design conversation, compare it with Tebori (Hand-carved Japanese) and Neo-Japanese.', 'en', '{"id":"irezumi","name":"Japanese Irezumi","category":"japanese","description":"Large-scale, colorful designs of mythological creatures, flowers, waves and warriors.","history":"Developed during the Edo period (1603–1868), tied to ukiyo-e woodblock prints and firemen/laborer culture.","distinctFeatures":"Full-body composition (bodysuit), background of wind/waves/clouds, strict motif symbolism and seasonal pairing.","commonMotifs":["koi","dragon","hannya mask","peony","cherry blossom","tiger","waves"],"relatedTechniques":["bold_line","color_packing","color_shading","black_and_grey_wash"],"relatedStyles":["tebori_style","neo_japanese"],"sourcePaper":"STY-05","fieldNote":"A river of myth read across the whole body — begun, in Edo, as punishment, now carried as devotion.","keyFacts":[{"text":"Edo-period Japan (1603–1868) used tattooing (irezumi kei) as a penal marking system for criminals, the direct root of irezumi''s enduring stigma.","evidence":"direct"},{"text":"Ukiyo-e artist Kuniyoshi''s Suikoden (Water Margin) print series is credited with driving mass public enthusiasm for large-scale figurative tattoo art.","evidence":"direct"}]}'),
  ('tebori_style', 'japanese', 'Tebori (Hand-carved Japanese)', 'Traditional Japanese hand-poked method and the aesthetic associated with it.', 'Manual technique predating machines, still practiced by horishi masters.', 'Distinctive soft color gradation achievable by hand, slower ritual process.', 'Tebori (Hand-carved Japanese) belongs to the Japanese family. Traditional Japanese hand-poked method and the aesthetic associated with it. Its story begins here: Manual technique predating machines, still practiced by horishi masters. On skin, it is recognized by distinctive soft color gradation achievable by hand, slower ritual process. Its visual vocabulary often includes same as Irezumi. The craft is commonly built with Tebori and Color Shading. For a broader design conversation, compare it with Japanese Irezumi.', 'en', '{"id":"tebori_style","name":"Tebori (Hand-carved Japanese)","category":"japanese","description":"Traditional Japanese hand-poked method and the aesthetic associated with it.","history":"Manual technique predating machines, still practiced by horishi masters.","distinctFeatures":"Distinctive soft color gradation achievable by hand, slower ritual process.","commonMotifs":["same as Irezumi"],"relatedTechniques":["tebori_technique","color_shading"],"relatedStyles":["irezumi"],"sourcePaper":"STY-05","fieldNote":"The hand-poked look no machine quite equals; you feel the patience in every shaded pass.","keyFacts":[{"text":"Tebori uses a bundle of needles on a bamboo/metal rod worked by hand, historically the sole method of executing irezumi.","evidence":"direct"},{"text":"Tebori mastery is reported to take longer to achieve than machine competency due to the number of simultaneously controlled variables (angle, speed, strength, timing, intervals).","evidence":"direct"}]}'),
  ('neo_japanese', 'japanese', 'Neo-Japanese', 'Modern reinterpretation of Irezumi with Western realism, new-school color or illustrative twists.', 'Late 20th–21st century fusion as Japanese imagery globalized.', 'Traditional motifs with modern shading, brighter palettes and looser composition rules.', 'Neo-Japanese belongs to the Japanese family. Modern reinterpretation of Irezumi with Western realism, new-school color or illustrative twists. Its story begins here: Late 20th–21st century fusion as Japanese imagery globalized. On skin, it is recognized by traditional motifs with modern shading, brighter palettes and looser composition rules. Its visual vocabulary often includes dragons, masks, koi, and samurai. The craft is commonly built with Color Blending, Bold Line, and Soft Shading. For a broader design conversation, compare it with Japanese Irezumi, Neo-Traditional, and Illustrative.', 'en', '{"id":"neo_japanese","name":"Neo-Japanese","category":"japanese","description":"Modern reinterpretation of Irezumi with Western realism, new-school color or illustrative twists.","history":"Late 20th–21st century fusion as Japanese imagery globalized.","distinctFeatures":"Traditional motifs with modern shading, brighter palettes and looser composition rules.","commonMotifs":["dragons","masks","koi","samurai"],"relatedTechniques":["color_blending","bold_line","soft_shading"],"relatedStyles":["irezumi","neo_traditional","illustrative"],"sourcePaper":"STY-05","fieldNote":"Japanese iconography rendered by Western hands — the imagery of irezumi without its lineage of authority.","keyFacts":[{"text":"Neo-Japanese tattooing emerged in the 1990s–2000s as Western artists began applying Japanese iconography with expanded color and contemporary shading, discarding irezumi''s structural rules.","evidence":"direct"},{"text":"Neo-Japanese incorporates cross-influence from Art Nouveau and Art Deco ornament, paralleling Western Neo-Traditional''s borrowings.","evidence":"direct"},{"text":"No single founding artist or moment is consistently credited for neo-Japanese''s emergence; it is better characterized as a multi-artist international trend.","evidence":"hypothesis"}]}'),
  ('anime', 'japanese', 'Anime / Manga', 'Faithful or stylized renditions of anime, manga and gaming characters.', '2010s boom driven by global anime fandom and color realism techniques.', 'Cel-shading look, vivid flat colors with realistic highlights, screen-accurate likeness.', 'Anime / Manga belongs to the Japanese family. Faithful or stylized renditions of anime, manga and gaming characters. Its story begins here: 2010s boom driven by global anime fandom and color realism techniques. On skin, it is recognized by cel-shading look, vivid flat colors with realistic highlights, screen-accurate likeness. Its visual vocabulary often includes anime characters, chibi figures, and game icons. The craft is commonly built with Color Packing, Fine Line, and White Highlights. For a broader design conversation, compare it with New School, Cartoon, and Color Realism.', 'en', '{"id":"anime","name":"Anime / Manga","category":"japanese","description":"Faithful or stylized renditions of anime, manga and gaming characters.","history":"2010s boom driven by global anime fandom and color realism techniques.","distinctFeatures":"Cel-shading look, vivid flat colors with realistic highlights, screen-accurate likeness.","commonMotifs":["anime characters","chibi figures","game icons"],"relatedTechniques":["color_packing","fine_line","white_highlights"],"relatedStyles":["new_school","cartoon","realism_color"],"sourcePaper":"STY-05","fieldNote":"Fandom brought to skin by television and the internet, not by any master''s lineage — keep the icon bold so it lasts.","keyFacts":[{"text":"Cartoon Network''s Toonami programming block (Dragon Ball Z, Sailor Moon, Outlaw Star, Gundam Wing) is credited as a key channel introducing anime to Western audiences who later became tattoo clients/artists.","evidence":"direct"},{"text":"Anime/manga tattoo influence contributed to the visual development of the Western New School tattoo style alongside Art Nouveau and Neo-Traditional influences.","evidence":"direct"}]}'),
  ('blackwork_style', 'blackwork', 'Blackwork', 'Bold and intricate designs using only black ink — from solid fills to detailed patterns.', 'Rooted in ancient tribal tattooing; modern resurgence for its graphic, minimalist power.', 'Exclusive use of black, high contrast, strong silhouettes and pattern density.', 'Blackwork belongs to the Blackwork & Geometric family. Bold and intricate designs using only black ink — from solid fills to detailed patterns. Its story begins here: Rooted in ancient tribal tattooing; modern resurgence for its graphic, minimalist power. On skin, it is recognized by exclusive use of black, high contrast, strong silhouettes and pattern density. Its visual vocabulary often includes patterns, botanical silhouettes, occult symbols, and abstract shapes. The craft is commonly built with Color Packing, Bold Line, Negative Space, and Dotwork. For a broader design conversation, compare it with Dotwork, Geometric, Blackout / Heavy Blackwork, and Tribal (Modern).', 'en', '{"id":"blackwork_style","name":"Blackwork","category":"blackwork","description":"Bold and intricate designs using only black ink — from solid fills to detailed patterns.","history":"Rooted in ancient tribal tattooing; modern resurgence for its graphic, minimalist power.","distinctFeatures":"Exclusive use of black, high contrast, strong silhouettes and pattern density.","commonMotifs":["patterns","botanical silhouettes","occult symbols","abstract shapes"],"relatedTechniques":["color_packing","bold_line","negative_space","dotwork_technique"],"relatedStyles":["dotwork_style","geometric","blackout_style","tribal"],"sourcePaper":"STY-03","fieldNote":"Black ink as the whole language — ancient in root, and the most faithful to time of anything we make.","keyFacts":[{"text":"Blackwork is a broad, material-defined category (black ink only) rooted in ancient tribal/folk tattooing, undergoing a Western revival in the 1970s–90s driven by the neo-tribal movement.","evidence":"synthesized"},{"text":"Leo Zulueta is credited in trade sources as \\"the father of modern tribal tattooing,\\" publishing a design collection in the 1990s.","evidence":"community_attested"}]}'),
  ('dotwork_style', 'blackwork', 'Dotwork', 'Entire designs created from individual dots, producing soft texture and gradients.', 'Modern style evolved alongside geometric and sacred-geometry trends; echoes pointillism.', 'Stippled shading, meditative gradients, often combined with mandalas and geometry.', 'Dotwork belongs to the Blackwork & Geometric family. Entire designs created from individual dots, producing soft texture and gradients. Its story begins here: Modern style evolved alongside geometric and sacred-geometry trends; echoes pointillism. On skin, it is recognized by stippled shading, meditative gradients, often combined with mandalas and geometry. Its visual vocabulary often includes mandalas, gradients, and celestial bodies. The craft is commonly built with Dotwork, Stippling, and Hand Poke (Stick & Poke). For a broader design conversation, compare it with Geometric, Mandala / Ornamental, Ornamental, and Blackwork.', 'en', '{"id":"dotwork_style","name":"Dotwork","category":"blackwork","description":"Entire designs created from individual dots, producing soft texture and gradients.","history":"Modern style evolved alongside geometric and sacred-geometry trends; echoes pointillism.","distinctFeatures":"Stippled shading, meditative gradients, often combined with mandalas and geometry.","commonMotifs":["mandalas","gradients","celestial bodies"],"relatedTechniques":["dotwork_technique","stippling","hand_poke"],"relatedStyles":["geometric","mandala","ornamental","blackwork_style"],"sourcePaper":"STY-03","fieldNote":"Shadow assembled point by point; the Dotfather taught the needle to whisper instead of shout.","keyFacts":[{"text":"Modern tattoo dotwork is credited to UK artist Xed LeHead (\\"The Dotfather\\"), who experimented with dot impressionism from around 1980.","evidence":"community_attested"},{"text":"LeHead was not the first to use dots in tattooing generally, but is credited with discovering new dot-gradient/patterning techniques that spread through the UK and internationally.","evidence":"direct"}]}'),
  ('geometric', 'blackwork', 'Geometric', 'Designs built from precise shapes and repeating patterns, often symmetrical.', 'Influenced by ancient spiritual symbols and modern graphic design.', 'Mathematical precision, symmetry, clean lines, pattern repetition.', 'Geometric belongs to the Blackwork & Geometric family. Designs built from precise shapes and repeating patterns, often symmetrical. Its story begins here: Influenced by ancient spiritual symbols and modern graphic design. On skin, it is recognized by mathematical precision, symmetry, clean lines, pattern repetition. Its visual vocabulary often includes polygons, fractals, sacred geometry, and tessellations. The craft is commonly built with Fine Line, Bold Line, Dotwork, and Geometric Precision. For a broader design conversation, compare it with Dotwork, Sacred Geometry, Mandala / Ornamental, and Blackwork.', 'en', '{"id":"geometric","name":"Geometric","category":"blackwork","description":"Designs built from precise shapes and repeating patterns, often symmetrical.","history":"Influenced by ancient spiritual symbols and modern graphic design.","distinctFeatures":"Mathematical precision, symmetry, clean lines, pattern repetition.","commonMotifs":["polygons","fractals","sacred geometry","tessellations"],"relatedTechniques":["fine_line","bold_line","dotwork_technique","geometric_technique"],"relatedStyles":["dotwork_style","sacred_geometry","mandala","blackwork_style"],"sourcePaper":"STY-03","fieldNote":"Precision drawn to follow the body''s own contours — line as structure, mapped to muscle.","keyFacts":[{"text":"Chaim Machlev (b. Nov. 7, 1980), known as DotsToLines, began tattooing in Berlin in 2012 with no prior formal fine-art training, after leaving an IT career.","evidence":"direct"},{"text":"Machlev''s background in computer science and psychology is cited as an influence on the precision/structure of his line-based, body-contour-following designs.","evidence":"direct"}]}'),
  ('sacred_geometry', 'blackwork', 'Sacred Geometry', 'Geometric style using symbolic figures: flower of life, Metatron''s cube, platonic solids.', 'Draws on spiritual mathematics of ancient cultures; popular from the 2000s.', 'Symbolic precision figures, mandala integration, dotwork shading.', 'Sacred Geometry belongs to the Blackwork & Geometric family. Geometric style using symbolic figures: flower of life, Metatron''s cube, platonic solids. Its story begins here: Draws on spiritual mathematics of ancient cultures; popular from the 2000s. On skin, it is recognized by symbolic precision figures, mandala integration, dotwork shading. Its visual vocabulary often includes flower of life, Metatron''s cube, and sri yantra. The craft is commonly built with Fine Line, Dotwork, and Geometric Precision. For a broader design conversation, compare it with Geometric, Mandala / Ornamental, and Dotwork.', 'en', '{"id":"sacred_geometry","name":"Sacred Geometry","category":"blackwork","description":"Geometric style using symbolic figures: flower of life, Metatron''s cube, platonic solids.","history":"Draws on spiritual mathematics of ancient cultures; popular from the 2000s.","distinctFeatures":"Symbolic precision figures, mandala integration, dotwork shading.","commonMotifs":["flower of life","Metatron''s cube","sri yantra"],"relatedTechniques":["fine_line","dotwork_technique","geometric_technique"],"relatedStyles":["geometric","mandala","dotwork_style"],"sourcePaper":"STY-03","fieldNote":"The Flower of Life and Metatron''s Cube; carry their symmetry, but do not oversell their ancient claims.","keyFacts":[{"text":"Sacred geometry tattoos are built from named figures including the Flower of Life, Metatron''s Cube, and Sri Yantra, frequently combined with dotwork and mandala framing.","evidence":"direct"},{"text":"Chaim Machlev and Dr. Woo are cited in trade sources as popularizers of sacred-geometry tattooing via social media.","evidence":"community_attested"},{"text":"Claims that ancient Egyptians and Greeks used sacred-geometric figures in spiritual practice are common in trade/New Age literature but not rigorously sourced in materials reviewed.","evidence":"contested"}]}'),
  ('mandala', 'blackwork', 'Mandala / Ornamental', 'Radially symmetric ornamental compositions inspired by mehndi, lace and sacred art.', 'Fusion of South Asian mandala and henna traditions with European ornament.', 'Radial symmetry, lace-like detail, dotwork accents, jewelry-like placement.', 'Mandala / Ornamental belongs to the Blackwork & Geometric family. Radially symmetric ornamental compositions inspired by mehndi, lace and sacred art. Its story begins here: Fusion of South Asian mandala and henna traditions with European ornament. On skin, it is recognized by radial symmetry, lace-like detail, dotwork accents, jewelry-like placement. Its visual vocabulary often includes mandala, lace, henna patterns, and chandelier ornaments. The craft is commonly built with Fine Line, Dotwork, and Stippling. For a broader design conversation, compare it with Ornamental, Dotwork, and Geometric.', 'en', '{"id":"mandala","name":"Mandala / Ornamental","category":"blackwork","description":"Radially symmetric ornamental compositions inspired by mehndi, lace and sacred art.","history":"Fusion of South Asian mandala and henna traditions with European ornament.","distinctFeatures":"Radial symmetry, lace-like detail, dotwork accents, jewelry-like placement.","commonMotifs":["mandala","lace","henna patterns","chandelier ornaments"],"relatedTechniques":["fine_line","dotwork_technique","stippling"],"relatedStyles":["ornamental","dotwork_style","geometric"],"sourcePaper":"STY-03","fieldNote":"''Circle,'' in Sanskrit — a meditative diagram; wear it knowing the devotion it comes from.","keyFacts":[{"text":"\\"Mandala\\" is Sanskrit for \\"circle,\\" a cosmic/meditative diagram central to Hindu and Buddhist practice, including Tibetan Buddhist sand mandalas.","evidence":"direct"},{"text":"Contemporary mandala tattooing draws heavily on South Asian Mehndi (henna) pattern vocabulary, a temporary body-art tradition thousands of years old.","evidence":"direct"}]}'),
  ('ornamental', 'blackwork', 'Ornamental', 'Decorative, jewelry-like designs that adorn the body rather than depict subjects.', 'Contemporary style drawing on filigree, baroque ornament and body-jewelry aesthetics.', 'Flowing decorative lines fitted to anatomy, pendants and chains, symmetry.', 'Ornamental belongs to the Blackwork & Geometric family. Decorative, jewelry-like designs that adorn the body rather than depict subjects. Its story begins here: Contemporary style drawing on filigree, baroque ornament and body-jewelry aesthetics. On skin, it is recognized by flowing decorative lines fitted to anatomy, pendants and chains, symmetry. Its visual vocabulary often includes filigree, gems, chains, and arches. The craft is commonly built with Fine Line, Dotwork, and Single Needle. For a broader design conversation, compare it with Mandala / Ornamental, Fine Line, and Geometric.', 'en', '{"id":"ornamental","name":"Ornamental","category":"blackwork","description":"Decorative, jewelry-like designs that adorn the body rather than depict subjects.","history":"Contemporary style drawing on filigree, baroque ornament and body-jewelry aesthetics.","distinctFeatures":"Flowing decorative lines fitted to anatomy, pendants and chains, symmetry.","commonMotifs":["filigree","gems","chains","arches"],"relatedTechniques":["fine_line","dotwork_technique","single_needle"],"relatedStyles":["mandala","fineline_style","geometric"],"sourcePaper":"STY-03","fieldNote":"Jewelry made of ink — filigree and lace fitted to the body as if it were always meant to be worn there.","keyFacts":[{"text":"Ornamental tattooing encompasses mandala-adjacent and broader jewelry-like, filigree, and pattern-grid compositions fitted to body contours.","evidence":"direct"},{"text":"Named contemporary practitioners include Alex Binnie, Thomas Hooper, Roxx, Raimundo Ramirez, and Johno.","evidence":"community_attested"}]}'),
  ('blackout_style', 'blackwork', 'Blackout / Heavy Blackwork', 'Large areas of skin saturated in solid black, often as bold negative-space compositions or cover-ups.', '2010s movement growing out of blackwork and cover-up practice.', 'Massive solid black fields, negative-space designs carved out of black.', 'Blackout / Heavy Blackwork belongs to the Blackwork & Geometric family. Large areas of skin saturated in solid black, often as bold negative-space compositions or cover-ups. Its story begins here: 2010s movement growing out of blackwork and cover-up practice. On skin, it is recognized by massive solid black fields, negative-space designs carved out of black. Its visual vocabulary often includes solid sleeves and negative-space patterns. The craft is commonly built with Blackout, Negative Space, and Color Packing. For a broader design conversation, compare it with Blackwork and Tribal (Modern).', 'en', '{"id":"blackout_style","name":"Blackout / Heavy Blackwork","category":"blackwork","description":"Large areas of skin saturated in solid black, often as bold negative-space compositions or cover-ups.","history":"2010s movement growing out of blackwork and cover-up practice.","distinctFeatures":"Massive solid black fields, negative-space designs carved out of black.","commonMotifs":["solid sleeves","negative-space patterns"],"relatedTechniques":["blackout_technique","negative_space","color_packing"],"relatedStyles":["blackwork_style","tribal"],"sourcePaper":"STY-03","fieldNote":"Whole limbs turned to solid black — striking, heavy, and a decision to make slowly, never on a dare.","keyFacts":[{"text":"Blackout tattoos are credited to Singaporean artist Chester Lee (Oracle Tattoo), practicing from around 2011.","evidence":"contested"},{"text":"The style''s global visibility surge is dated to 2016, driven by Chester Lee''s viral Instagram exposure and celebrity/athlete adoption (Lionel Messi, Tyler Joseph of Twenty One Pilots).","evidence":"direct"}]}'),
  ('black_grey', 'blackwork', 'Black & Grey', 'Shades of diluted black creating a softer, subtler tonal range than pure blackwork.', 'Perfected in 1970s East LA using single needles and diluted ink (''jailhouse style'' refined).', 'Grey wash gradients, smoky softness, no color.', 'Black & Grey belongs to the Blackwork & Geometric family. Shades of diluted black creating a softer, subtler tonal range than pure blackwork. Its story begins here: Perfected in 1970s East LA using single needles and diluted ink (''jailhouse style'' refined). On skin, it is recognized by grey wash gradients, smoky softness, no color. Its visual vocabulary often includes portraits, religious scenes, roses, and clocks. The craft is commonly built with Black & Grey Wash, Soft Shading, and Single Needle. For a broader design conversation, compare it with Chicano and Black & Grey Realism.', 'en', '{"id":"black_grey","name":"Black & Grey","category":"blackwork","description":"Shades of diluted black creating a softer, subtler tonal range than pure blackwork.","history":"Perfected in 1970s East LA using single needles and diluted ink (''jailhouse style'' refined).","distinctFeatures":"Grey wash gradients, smoky softness, no color.","commonMotifs":["portraits","religious scenes","roses","clocks"],"relatedTechniques":["black_and_grey_wash","soft_shading","single_needle"],"relatedStyles":["chicano","realism_bg"],"sourcePaper":"STY-03","fieldNote":"Diluted black across a full tonal range — the prison-born grammar that still reads as pure atmosphere.","keyFacts":[{"text":"Black & grey originated in 1960s–70s California prisons among Chicano inmates, using diluted black ink and homemade single-needle machines, and was professionalized at Good Time Charlie''s Tattooland (East LA, 1975).","evidence":"direct"},{"text":"Black & grey''s traditional (non-photorealistic) subject matter includes religious scenes, roses, clocks, and script lettering, distinct from but technically continuous with the photorealistic realism_bg specialization.","evidence":"synthesized"}]}'),
  ('etching', 'illustrative', 'Etching / Engraving (Woodcut)', 'Mimics old engravings, woodcuts and linocuts with parallel-line shading.', 'Inspired by medieval and Renaissance printmaking (Dürer, Doré); modern wave from the 2010s.', 'Cross-hatching, parallel whip lines, antique-book aesthetic, black only.', 'Etching / Engraving (Woodcut) belongs to the Illustrative & Artistic family. Mimics old engravings, woodcuts and linocuts with parallel-line shading. Its story begins here: Inspired by medieval and Renaissance printmaking (Dürer, Doré); modern wave from the 2010s. On skin, it is recognized by cross-hatching, parallel whip lines, antique-book aesthetic, black only. Its visual vocabulary often includes medieval scenes, botanical plates, skeletons, and banners. The craft is commonly built with Etching / Engraving, Whip Shading, Fine Line, and Crosshatching. For a broader design conversation, compare it with Blackwork, Illustrative, and Sketch Style.', 'en', '{"id":"etching","name":"Etching / Engraving (Woodcut)","category":"illustrative","description":"Mimics old engravings, woodcuts and linocuts with parallel-line shading.","history":"Inspired by medieval and Renaissance printmaking (Dürer, Doré); modern wave from the 2010s.","distinctFeatures":"Cross-hatching, parallel whip lines, antique-book aesthetic, black only.","commonMotifs":["medieval scenes","botanical plates","skeletons","banners"],"relatedTechniques":["etching_technique","whip_shading","fine_line","crosshatching"],"relatedStyles":["blackwork_style","illustrative","sketch"],"sourcePaper":"STY-06","fieldNote":"The look of a Dürer engraving — hatched line pretending to be a printing plate on living skin.","keyFacts":[{"text":"Etching-style tattooing references named Renaissance/early-modern printmakers (Dürer, Schongauer, Rembrandt, Goya, Doré) and dates its tattoo-specific practice to roughly the 2010s.","evidence":"direct"},{"text":"Yvonne (Blut & Eisen, Berlin) and Duncan X (Into You, London) are credited as early practitioners bringing art-historical print references into tattooing.","evidence":"direct"}]}'),
  ('illustrative', 'illustrative', 'Illustrative', 'Combines traditional illustration with tattoo art for a storybook-like appearance.', 'Broad contemporary style drawing on drawing, printmaking and animation.', 'Visible line art plus painterly or flat color, stylized rather than photographic.', 'Illustrative belongs to the Illustrative & Artistic family. Combines traditional illustration with tattoo art for a storybook-like appearance. Its story begins here: Broad contemporary style drawing on drawing, printmaking and animation. On skin, it is recognized by visible line art plus painterly or flat color, stylized rather than photographic. Its visual vocabulary often includes fairy-tale scenes, animals, and botanical art. The craft is commonly built with Fine Line, Bold Line, Color Shading, and Whip Shading. For a broader design conversation, compare it with Neo-Traditional, Sketch Style, and Watercolor.', 'en', '{"id":"illustrative","name":"Illustrative","category":"illustrative","description":"Combines traditional illustration with tattoo art for a storybook-like appearance.","history":"Broad contemporary style drawing on drawing, printmaking and animation.","distinctFeatures":"Visible line art plus painterly or flat color, stylized rather than photographic.","commonMotifs":["fairy-tale scenes","animals","botanical art"],"relatedTechniques":["fine_line","bold_line","color_shading","whip_shading"],"relatedStyles":["neo_traditional","sketch","watercolor_style"],"sourcePaper":"STY-06","fieldNote":"The broad hand of the illustrator — line and gesture chosen over photographic fidelity.","keyFacts":[{"text":"Illustrative tattooing functions as a broad umbrella spanning etching/engraving, sketch-like gestures, Old Masters preliminary outlines, and other art-historical currents.","evidence":"direct"},{"text":"Leonardo da Vinci''s Vitruvian Man sketch and Mexican muralist/illustrator traditions (Kahlo, Rivera, Helguera, Izquierdo, Siqueiros) are cited as reference points for illustrative-style artists.","evidence":"direct"}]}'),
  ('sketch', 'illustrative', 'Sketch Style', 'Looks like a hand-drawn pencil sketch with raw, loose lines and unfinished edges.', 'Emerged in the 2000s, inspired by artists'' preliminary drawings.', 'Overlapping construction lines, hatching, deliberate ''unfinished'' rawness.', 'Sketch Style belongs to the Illustrative & Artistic family. Looks like a hand-drawn pencil sketch with raw, loose lines and unfinished edges. Its story begins here: Emerged in the 2000s, inspired by artists'' preliminary drawings. On skin, it is recognized by overlapping construction lines, hatching, deliberate ''unfinished'' rawness. Its visual vocabulary often includes animals in motion, figures, and architectural sketches. The craft is commonly built with Broken Line, Whip Shading, Crosshatching, and Fine Line. For a broader design conversation, compare it with Illustrative, Trash Polka, and Abstract.', 'en', '{"id":"sketch","name":"Sketch Style","category":"illustrative","description":"Looks like a hand-drawn pencil sketch with raw, loose lines and unfinished edges.","history":"Emerged in the 2000s, inspired by artists'' preliminary drawings.","distinctFeatures":"Overlapping construction lines, hatching, deliberate ''unfinished'' rawness.","commonMotifs":["animals in motion","figures","architectural sketches"],"relatedTechniques":["broken_line","whip_shading","crosshatching","fine_line"],"relatedStyles":["illustrative","trash_polka","abstract"],"sourcePaper":"STY-06","fieldNote":"The unfinished pencil, deliberately left open — the construction lines kept as the beauty.","keyFacts":[{"text":"Sketch style tattoos mimic hand-drawn pencil/charcoal sketches with deliberately loose, unfinished lines and visible construction lines.","evidence":"direct"},{"text":"Sources disagree on dating: one describes an \\"early 20th century\\" emergence while also describing a \\"last two decades\\" popularity arc, an internal inconsistency this paper flags.","evidence":"contested"}]}'),
  ('watercolor_style', 'illustrative', 'Watercolor', 'Mimics watercolor paintings with soft, flowing color splashes and no hard borders.', 'Popularized in the 21st century, inspired by contemporary painting.', 'Color bleeds, splatters, gradient washes, minimal or absent outlines.', 'Watercolor belongs to the Illustrative & Artistic family. Mimics watercolor paintings with soft, flowing color splashes and no hard borders. Its story begins here: Popularized in the 21st century, inspired by contemporary painting. On skin, it is recognized by color bleeds, splatters, gradient washes, minimal or absent outlines. Its visual vocabulary often includes flowers, birds, abstract splashes, and landscapes. The craft is commonly built with Watercolor Technique, Color Blending, and Brush Stroke. For a broader design conversation, compare it with Abstract, Illustrative, and Sketch Style.', 'en', '{"id":"watercolor_style","name":"Watercolor","category":"illustrative","description":"Mimics watercolor paintings with soft, flowing color splashes and no hard borders.","history":"Popularized in the 21st century, inspired by contemporary painting.","distinctFeatures":"Color bleeds, splatters, gradient washes, minimal or absent outlines.","commonMotifs":["flowers","birds","abstract splashes","landscapes"],"relatedTechniques":["watercolor_technique","color_blending","brush_stroke"],"relatedStyles":["abstract","illustrative","sketch"],"sourcePaper":"STY-06","fieldNote":"Wachob''s washes and splatters, floating free of the outline; lovely, and honest about how soft edges age.","keyFacts":[{"text":"Amanda Wachob pioneered watercolor-style tattooing in 2008, incorporating brushstrokes, washes, splatters, and spills inspired by modern painting.","evidence":"direct"},{"text":"Wachob''s \\"greylining\\" technique dilutes black ink with water to render outlines nearly invisible, shifting emphasis to color.","evidence":"direct"}]}'),
  ('abstract', 'illustrative', 'Abstract', 'Non-representational compositions of shape, color and texture.', 'Parallels 20th-century abstract art movements; grows with avant-garde tattooing.', 'Free composition, expressive marks, no literal subject.', 'Abstract belongs to the Illustrative & Artistic family. Non-representational compositions of shape, color and texture. Its story begins here: Parallels 20th-century abstract art movements; grows with avant-garde tattooing. On skin, it is recognized by free composition, expressive marks, no literal subject. Its visual vocabulary often includes brush marks, color fields, and geometric fragments. The craft is commonly built with Brush Stroke, Watercolor Technique, and Negative Space. For a broader design conversation, compare it with Watercolor, Trash Polka, and Ignorant Style.', 'en', '{"id":"abstract","name":"Abstract","category":"illustrative","description":"Non-representational compositions of shape, color and texture.","history":"Parallels 20th-century abstract art movements; grows with avant-garde tattooing.","distinctFeatures":"Free composition, expressive marks, no literal subject.","commonMotifs":["brush marks","color fields","geometric fragments"],"relatedTechniques":["brush_stroke","watercolor_technique","negative_space"],"relatedStyles":["watercolor_style","trash_polka","ignorant"],"sourcePaper":"STY-06","fieldNote":"Kandinsky''s freedom on skin — mark and color answering only to feeling.","keyFacts":[{"text":"Abstract tattooing draws on early-20th-century fine-art abstraction (Kandinsky, Mondrian, Pollock) while developing its own tattoo-specific visual language.","evidence":"direct"},{"text":"Amanda Wachob''s abstract work is directly inspired by Hans Hofmann''s Abstract Expressionism, developed alongside her watercolor technique.","evidence":"direct"}]}'),
  ('pop_art', 'illustrative', 'Pop Art / Comic', 'Bold comic-book aesthetics: halftone dots, primary colors, thick outlines.', 'Inspired by Lichtenstein, Warhol and vintage comics.', 'Ben-Day dots, speech bubbles, flat saturated color, heavy keylines.', 'Pop Art / Comic belongs to the Illustrative & Artistic family. Bold comic-book aesthetics: halftone dots, primary colors, thick outlines. Its story begins here: Inspired by Lichtenstein, Warhol and vintage comics. On skin, it is recognized by ben-Day dots, speech bubbles, flat saturated color, heavy keylines. Its visual vocabulary often includes comic panels, onomatopoeia, and retro ads. The craft is commonly built with Bold Line, Color Packing, and Dotwork. For a broader design conversation, compare it with New School, Cartoon, and Anime / Manga.', 'en', '{"id":"pop_art","name":"Pop Art / Comic","category":"illustrative","description":"Bold comic-book aesthetics: halftone dots, primary colors, thick outlines.","history":"Inspired by Lichtenstein, Warhol and vintage comics.","distinctFeatures":"Ben-Day dots, speech bubbles, flat saturated color, heavy keylines.","commonMotifs":["comic panels","onomatopoeia","retro ads"],"relatedTechniques":["bold_line","color_packing","dotwork_technique"],"relatedStyles":["new_school","cartoon","anime"],"sourcePaper":"STY-06","fieldNote":"Ben-Day dots and flat primaries — the comic panel worn as a wink.","keyFacts":[{"text":"Pop Art tattooing replicates the visual codes (Ben-Day dots, flat primary color, heavy keylines) of the mid-20th-century Pop Art movement (Lichtenstein, Warhol, Haring).","evidence":"direct"},{"text":"Roy Lichtenstein''s use of Ben-Day dots and comic-derived imagery has been criticized within art history as under-crediting original comic illustrators.","evidence":"direct"},{"text":"Tattoo-specific dating is contested: one source places pop-art-influenced tattooing''s emergence in the 1970s–1980s as a New School substyle, another in \\"the early 2000s.\\"","evidence":"contested"}]}'),
  ('cartoon', 'illustrative', 'Cartoon', 'Recreations of animated characters or original designs in cartoon language.', 'Longstanding niche boosted by nostalgia waves and streaming-era fandoms.', 'Simple shapes, flat colors, expressive faces, clean outlines.', 'Cartoon belongs to the Illustrative & Artistic family. Recreations of animated characters or original designs in cartoon language. Its story begins here: Longstanding niche boosted by nostalgia waves and streaming-era fandoms. On skin, it is recognized by simple shapes, flat colors, expressive faces, clean outlines. Its visual vocabulary often includes classic cartoon characters and mascots. The craft is commonly built with Bold Line and Color Packing. For a broader design conversation, compare it with New School, Anime / Manga, and Pop Art / Comic.', 'en', '{"id":"cartoon","name":"Cartoon","category":"illustrative","description":"Recreations of animated characters or original designs in cartoon language.","history":"Longstanding niche boosted by nostalgia waves and streaming-era fandoms.","distinctFeatures":"Simple shapes, flat colors, expressive faces, clean outlines.","commonMotifs":["classic cartoon characters","mascots"],"relatedTechniques":["bold_line","color_packing"],"relatedStyles":["new_school","anime","pop_art"],"sourcePaper":"STY-06","fieldNote":"Popeye and Betty Boop in ink — the animated line, bold enough to keep smiling for decades.","keyFacts":[{"text":"Popeye and Betty Boop (Fleischer Studios) and Looney Tunes characters (Warner Bros., debuted 1930) are cited as among the earliest cartoon characters tattooed.","evidence":"direct"},{"text":"Cartoon tattoos are executable across any base rendering technique (traditional, new-school, realism, blackwork) rather than constituting a single fixed visual grammar.","evidence":"direct"}]}'),
  ('sticker_patchwork', 'modern', 'Sticker / Patchwork', 'Collections of small standalone designs scattered like stickers or sewn patches, no background.', '2020s trend (''patchwork sleeves'') driven by Gen-Z clients and social media.', 'Independent mini-designs, white keyline ''sticker'' borders, gap-filled sleeves.', 'Sticker / Patchwork belongs to the Modern & Experimental family. Collections of small standalone designs scattered like stickers or sewn patches, no background. Its story begins here: 2020s trend (''patchwork sleeves'') driven by Gen-Z clients and social media. On skin, it is recognized by independent mini-designs, white keyline ''sticker'' borders, gap-filled sleeves. Its visual vocabulary often includes mini icons, flash pieces, and pop-culture stickers. The craft is commonly built with Fine Line, Bold Line, Color Packing, and White Ink Work. For a broader design conversation, compare it with Cartoon, Fine Line, and Embroidery / Patch.', 'en', '{"id":"sticker_patchwork","name":"Sticker / Patchwork","category":"modern","description":"Collections of small standalone designs scattered like stickers or sewn patches, no background.","history":"2020s trend (''patchwork sleeves'') driven by Gen-Z clients and social media.","distinctFeatures":"Independent mini-designs, white keyline ''sticker'' borders, gap-filled sleeves.","commonMotifs":["mini icons","flash pieces","pop-culture stickers"],"relatedTechniques":["fine_line","bold_line","color_packing","white_ink_technique"],"relatedStyles":["cartoon","fineline_style","embroidery"],"sourcePaper":"STY-07","fieldNote":"A body collected like a suitcase of stickers — small, separate, and deliberately unplanned.","keyFacts":[{"text":"Sticker/patchwork tattooing is a 2020s, Gen-Z-associated trend of collecting small, independent tattoos with deliberate negative-space separation, rejecting single-cohesive-sleeve planning.","evidence":"direct"},{"text":"Multiple 2024–2026 industry trend-forecasters (Painful Pleasures, Temporalis, Anomalie Tattoo Co.) independently identify sticker-style patchwork as a top tattoo trend of the mid-2020s.","evidence":"direct"},{"text":"No single credited originating artist or studio is identified in sources reviewed; the trend is best characterized as diffuse and platform-driven.","evidence":"hypothesis"}]}'),
  ('embroidery', 'modern', 'Embroidery / Patch', 'Trompe-l''œil imitation of embroidered patches with visible ''stitches'' and thread texture.', 'Viral 2010s–20s novelty style from Latin American artists.', 'Thread-like strokes, highlight sheen, patch borders, hyper-textured color.', 'Embroidery / Patch belongs to the Modern & Experimental family. Trompe-l''œil imitation of embroidered patches with visible ''stitches'' and thread texture. Its story begins here: Viral 2010s–20s novelty style from Latin American artists. On skin, it is recognized by thread-like strokes, highlight sheen, patch borders, hyper-textured color. Its visual vocabulary often includes cartoon patches, flowers, and sports logos. The craft is commonly built with Color Packing, White Highlights, Layering, and Optical Illusion. For a broader design conversation, compare it with Sticker / Patchwork and 3D / Optical Illusion.', 'en', '{"id":"embroidery","name":"Embroidery / Patch","category":"modern","description":"Trompe-l''œil imitation of embroidered patches with visible ''stitches'' and thread texture.","history":"Viral 2010s–20s novelty style from Latin American artists.","distinctFeatures":"Thread-like strokes, highlight sheen, patch borders, hyper-textured color.","commonMotifs":["cartoon patches","flowers","sports logos"],"relatedTechniques":["color_packing","white_highlights","layering","optical_illusion_technique"],"relatedStyles":["sticker_patchwork","3d_style"],"sourcePaper":"STY-07","fieldNote":"Thread that isn''t there — the raised-patch illusion, stitched in pigment, born in Latin America.","keyFacts":[{"text":"Embroidery/patch tattooing emerged in the mid-2010s (specifically cited as 2017) in Latin America.","evidence":"direct"},{"text":"Brazilian artist Eduardo \\"Duda\\" Lozano is most consistently credited as an early, highly influential practitioner, known for \\"broken thread\\" details.","evidence":"direct"}]}'),
  ('cyber_sigilism', 'modern', 'Cyber Sigilism', 'Spiky, web-like abstract linework resembling futuristic sigils and neo-tribal circuitry.', 'Emerged ~2020 from internet subcultures blending Y2K, goth and tribal revival.', 'Thin sharp spikes, symmetrical webs, chrome or pure black, sternum/spine placements.', 'Cyber Sigilism belongs to the Modern & Experimental family. Spiky, web-like abstract linework resembling futuristic sigils and neo-tribal circuitry. Its story begins here: Emerged ~2020 from internet subcultures blending Y2K, goth and tribal revival. On skin, it is recognized by thin sharp spikes, symmetrical webs, chrome or pure black, sternum/spine placements. Its visual vocabulary often includes sigil webs, spiked hearts, and chrome flourishes. The craft is commonly built with Fine Line, Single Needle, and Whip Shading. For a broader design conversation, compare it with Neo-Tribal, Blackwork, and Gothic.', 'en', '{"id":"cyber_sigilism","name":"Cyber Sigilism","category":"modern","description":"Spiky, web-like abstract linework resembling futuristic sigils and neo-tribal circuitry.","history":"Emerged ~2020 from internet subcultures blending Y2K, goth and tribal revival.","distinctFeatures":"Thin sharp spikes, symmetrical webs, chrome or pure black, sternum/spine placements.","commonMotifs":["sigil webs","spiked hearts","chrome flourishes"],"relatedTechniques":["fine_line","single_needle","whip_shading"],"relatedStyles":["neotribal","blackwork_style","goth"],"sourcePaper":"STY-07","fieldNote":"Spiked, glinting glyphs out of the Berlin club night — the sigil for a screen-lit generation.","keyFacts":[{"text":"Cyber sigilism emerged from the late-2010s Berlin club scene, associated with artist Aingelblood, moving into high fashion and celebrity adoption in the early 2020s.","evidence":"direct"},{"text":"The style descends visually from 1990s neo-tribal (Leo Zulueta).","evidence":"direct"}]}'),
  ('neotribal', 'modern', 'Neo-Tribal', 'Revival of 90s tribal filtered through modern blackwork and cyber aesthetics.', '2020s revival wave reinterpreting tribal spikes with contemporary composition.', 'Sharper, more aggressive spikes than classic tribal, asymmetry allowed, body-hugging flow.', 'Neo-Tribal belongs to the Modern & Experimental family. Revival of 90s tribal filtered through modern blackwork and cyber aesthetics. Its story begins here: 2020s revival wave reinterpreting tribal spikes with contemporary composition. On skin, it is recognized by sharper, more aggressive spikes than classic tribal, asymmetry allowed, body-hugging flow. Its visual vocabulary often includes spiked forms, flame shapes, and spine pieces. The craft is commonly built with Color Packing, Bold Line, and Tribal Blackfill. For a broader design conversation, compare it with Tribal (Modern), Cyber Sigilism, and Blackwork.', 'en', '{"id":"neotribal","name":"Neo-Tribal","category":"modern","description":"Revival of 90s tribal filtered through modern blackwork and cyber aesthetics.","history":"2020s revival wave reinterpreting tribal spikes with contemporary composition.","distinctFeatures":"Sharper, more aggressive spikes than classic tribal, asymmetry allowed, body-hugging flow.","commonMotifs":["spiked forms","flame shapes","spine pieces"],"relatedTechniques":["color_packing","bold_line","tribal_blackfill"],"relatedStyles":["tribal","cyber_sigilism","blackwork_style"],"sourcePaper":"STY-07","fieldNote":"The 90s tribal returning sharper and stranger — asymmetry where there was once symmetry.","keyFacts":[{"text":"Neo-tribal is a 2020s revival of 1990s tribal blackwork with sharper spikes and greater asymmetry than the earlier movement.","evidence":"direct"}]}'),
  ('ignorant', 'modern', 'Ignorant Style', 'Deliberately crude, childlike doodles with punk humor — anti-technique as aesthetic.', 'Born from Parisian graffiti (Fuzi UVTPK) in the 2000s.', 'Shaky single-weight lines, naive figures, ironic captions, no shading.', 'Ignorant Style belongs to the Modern & Experimental family. Deliberately crude, childlike doodles with punk humor — anti-technique as aesthetic. Its story begins here: Born from Parisian graffiti (Fuzi UVTPK) in the 2000s. On skin, it is recognized by shaky single-weight lines, naive figures, ironic captions, no shading. Its visual vocabulary often includes stick figures, sarcastic slogans, and doodle animals. The craft is commonly built with Fine Line, Hand Poke (Stick & Poke), and Broken Line. For a broader design conversation, compare it with Graffiti, Minimalist, and Abstract.', 'en', '{"id":"ignorant","name":"Ignorant Style","category":"modern","description":"Deliberately crude, childlike doodles with punk humor — anti-technique as aesthetic.","history":"Born from Parisian graffiti (Fuzi UVTPK) in the 2000s.","distinctFeatures":"Shaky single-weight lines, naive figures, ironic captions, no shading.","commonMotifs":["stick figures","sarcastic slogans","doodle animals"],"relatedTechniques":["fine_line","hand_poke","broken_line"],"relatedStyles":["graffiti","minimalist","abstract"],"sourcePaper":"STY-07","fieldNote":"Fuzi''s deliberately crude line — the joke, and the freedom, of drawing ''badly'' on purpose.","keyFacts":[{"text":"French graffiti artist Fuzi Uvtpk pioneered \\"Ignorant Style\\" graffiti in the mid-1990s and applied it to tattooing from 2008.","evidence":"direct"},{"text":"The style mainstreamed through 2010s celebrity adoption (Miley Cyrus, Pete Davidson, Machine Gun Kelly, Brooke Candy).","evidence":"direct"}]}'),
  ('glitch', 'modern', 'Glitch / Pixel', 'Digital-error aesthetics: RGB splits, scanlines, pixelation and vaporwave artifacts.', '2010s style importing digital glitch art onto skin.', 'Offset color channels (cyan/red), pixel blocks, distortion of otherwise clean images.', 'Glitch / Pixel belongs to the Modern & Experimental family. Digital-error aesthetics: RGB splits, scanlines, pixelation and vaporwave artifacts. Its story begins here: 2010s style importing digital glitch art onto skin. On skin, it is recognized by offset color channels (cyan/red), pixel blocks, distortion of otherwise clean images. Its visual vocabulary often includes glitched portraits, pixel hearts, and loading bars. The craft is commonly built with Color Packing, Fine Line, and Optical Illusion. For a broader design conversation, compare it with 3D / Optical Illusion, Pop Art / Comic, and Abstract.', 'en', '{"id":"glitch","name":"Glitch / Pixel","category":"modern","description":"Digital-error aesthetics: RGB splits, scanlines, pixelation and vaporwave artifacts.","history":"2010s style importing digital glitch art onto skin.","distinctFeatures":"Offset color channels (cyan/red), pixel blocks, distortion of otherwise clean images.","commonMotifs":["glitched portraits","pixel hearts","loading bars"],"relatedTechniques":["color_packing","fine_line","optical_illusion_technique"],"relatedStyles":["3d_style","pop_art","abstract"],"sourcePaper":"STY-07","fieldNote":"RGB split and scan-lines on skin — the error made ornament.","keyFacts":[{"text":"Glitch tattoos replicate RGB channel splitting, scan-line banding, and pixelation, most commonly applied to portraits.","evidence":"direct"},{"text":"No specific named tattoo-world pioneer or precise founding date was identified in sources reviewed for this paper.","evidence":"unknown"}]}'),
  ('3d_style', 'modern', '3D / Optical Illusion', 'Creates an illusion of depth making the tattoo appear three-dimensional or the skin transformed.', 'Modern style leveraging shading and perspective for lifelike trompe-l''œil effects.', 'Cast shadows, perspective tricks, torn-skin and embossed effects.', '3D / Optical Illusion belongs to the Modern & Experimental family. Creates an illusion of depth making the tattoo appear three-dimensional or the skin transformed. Its story begins here: Modern style leveraging shading and perspective for lifelike trompe-l''œil effects. On skin, it is recognized by cast shadows, perspective tricks, torn-skin and embossed effects. Its visual vocabulary often includes torn skin, embossed symbols, and insects that look real. The craft is commonly built with Depth Effects, Optical Illusion, Soft Shading, and White Highlights. For a broader design conversation, compare it with Hyperrealism, Biomechanical, and Embroidery / Patch.', 'en', '{"id":"3d_style","name":"3D / Optical Illusion","category":"modern","description":"Creates an illusion of depth making the tattoo appear three-dimensional or the skin transformed.","history":"Modern style leveraging shading and perspective for lifelike trompe-l''œil effects.","distinctFeatures":"Cast shadows, perspective tricks, torn-skin and embossed effects.","commonMotifs":["torn skin","embossed symbols","insects that look real"],"relatedTechniques":["depth_effects","optical_illusion_technique","soft_shading","white_highlights"],"relatedStyles":["hyperrealism","biomechanical","embroidery"],"sourcePaper":"STY-07","fieldNote":"Torn skin, lifted edges, objects that seem to sit above the arm — illusion that must respect the curve beneath.","keyFacts":[{"text":"3D/optical illusion tattoos use shading, perspective, and embossed/torn-skin effects, sometimes incorporating Escher-referencing impossible geometry.","evidence":"community_attested"},{"text":"No specific named tattoo-world pioneer or precise founding date was identified in sources reviewed for this paper.","evidence":"unknown"}]}'),
  ('minimalist', 'fineline', 'Minimalist', 'Simple, understated designs with clean lines and minimal detail.', 'Gained popularity in the 21st century with minimalism in art and design.', 'Economy of line, small scale, high negative space, restrained palette.', 'Minimalist belongs to the Minimalist & Fine Line family. Simple, understated designs with clean lines and minimal detail. Its story begins here: Gained popularity in the 21st century with minimalism in art and design. On skin, it is recognized by economy of line, small scale, high negative space, restrained palette. Its visual vocabulary often includes tiny symbols, single-word script, and small outlines. The craft is commonly built with Fine Line, Single Needle, and Negative Space. For a broader design conversation, compare it with Fine Line, Linework, and Ignorant Style.', 'en', '{"id":"minimalist","name":"Minimalist","category":"fineline","description":"Simple, understated designs with clean lines and minimal detail.","history":"Gained popularity in the 21st century with minimalism in art and design.","distinctFeatures":"Economy of line, small scale, high negative space, restrained palette.","commonMotifs":["tiny symbols","single-word script","small outlines"],"relatedTechniques":["fine_line","single_needle","negative_space"],"relatedStyles":["fineline_style","linework_style","ignorant"],"sourcePaper":"STY-08","fieldNote":"The fewest lines that still tell the truth — restraint you must earn, not fake.","keyFacts":[{"text":"Minimalist tattooing functions as an umbrella term for fine-line, linework, and single-line subcategories, unified by economy of line and high negative space.","evidence":"synthesized"},{"text":"The contemporary mainstream minimalist/fine-line boom is closely associated with celebrity tattoo artists working in New York in the mid-2000s–2010s.","evidence":"direct"}]}'),
  ('fineline_style', 'fineline', 'Fine Line', 'Delicate designs executed with the thinnest possible lines and subtle shading.', 'Roots in Chicano single-needle work; mainstream boom in the 2010s (celebrity tattoos).', 'Hair-thin lines, soft micro-shading, elegance and precision at small scale.', 'Fine Line belongs to the Minimalist & Fine Line family. Delicate designs executed with the thinnest possible lines and subtle shading. Its story begins here: Roots in Chicano single-needle work; mainstream boom in the 2010s (celebrity tattoos). On skin, it is recognized by hair-thin lines, soft micro-shading, elegance and precision at small scale. Its visual vocabulary often includes botanical stems, script, micro portraits, and constellations. The craft is commonly built with Fine Line, Single Needle, and Soft Shading. For a broader design conversation, compare it with Micro Realism, Minimalist, Ornamental, and Chicano.', 'en', '{"id":"fineline_style","name":"Fine Line","category":"fineline","description":"Delicate designs executed with the thinnest possible lines and subtle shading.","history":"Roots in Chicano single-needle work; mainstream boom in the 2010s (celebrity tattoos).","distinctFeatures":"Hair-thin lines, soft micro-shading, elegance and precision at small scale.","commonMotifs":["botanical stems","script","micro portraits","constellations"],"relatedTechniques":["fine_line","single_needle","soft_shading"],"relatedStyles":["micro_realism","minimalist","ornamental","chicano"],"sourcePaper":"STY-08","fieldNote":"The thread-thin line Bang Bang put on the culture''s radar in 2007 — delicate, and quietly at war with time.","keyFacts":[{"text":"Keith \\"Bang Bang\\" McCurdy (b. Nov. 28, 1985) tattooed a fine-line Sanskrit script on Rihanna''s hip in 2007, an event credited with launching his career and the style''s celebrity visibility.","evidence":"direct"},{"text":"Jonathan \\"JonBoy\\" Valena, a former Hillsong Church youth minister, is credited as \\"the pioneer of the ''tiny tattoo'' movement,\\" tattooing minimalist designs on numerous high-profile celebrities.","evidence":"direct"}]}'),
  ('linework_style', 'fineline', 'Linework', 'Design created entirely through lines — from single continuous contours to dense pattern fields.', 'Fundamental to tattooing; popularized as a standalone minimalist aesthetic recently.', 'No shading fills; rhythm, weight and spacing of lines carry the whole design.', 'Linework belongs to the Minimalist & Fine Line family. Design created entirely through lines — from single continuous contours to dense pattern fields. Its story begins here: Fundamental to tattooing; popularized as a standalone minimalist aesthetic recently. On skin, it is recognized by no shading fills; rhythm, weight and spacing of lines carry the whole design. Its visual vocabulary often includes one-line figures, line portraits, and op-art fields. The craft is commonly built with Continuous Line, Fine Line, Bold Line, and Broken Line. For a broader design conversation, compare it with Minimalist, Geometric, and Abstract.', 'en', '{"id":"linework_style","name":"Linework","category":"fineline","description":"Design created entirely through lines — from single continuous contours to dense pattern fields.","history":"Fundamental to tattooing; popularized as a standalone minimalist aesthetic recently.","distinctFeatures":"No shading fills; rhythm, weight and spacing of lines carry the whole design.","commonMotifs":["one-line figures","line portraits","op-art fields"],"relatedTechniques":["continuous_line","fine_line","bold_line","broken_line"],"relatedStyles":["minimalist","geometric","abstract"],"sourcePaper":"STY-08","fieldNote":"Pure line, no fill — the drawing reduced to its own skeleton.","keyFacts":[{"text":"Linework tattooing is built entirely from lines with no shading fills, distinguished from fine-line specifically by not requiring thin/delicate line weight.","evidence":"synthesized"}]}'),
  ('single_line', 'fineline', 'Single / Continuous Line', 'Whole image drawn with one unbroken line, Picasso-style.', 'Inspired by one-line drawing exercises of modernist artists.', 'One flowing uninterrupted contour forming a complete figure.', 'Single / Continuous Line belongs to the Minimalist & Fine Line family. Whole image drawn with one unbroken line, Picasso-style. Its story begins here: Inspired by one-line drawing exercises of modernist artists. On skin, it is recognized by one flowing uninterrupted contour forming a complete figure. Its visual vocabulary often includes faces, animals, hands, and hearts. The craft is commonly built with Continuous Line and Fine Line. For a broader design conversation, compare it with Linework and Minimalist.', 'en', '{"id":"single_line","name":"Single / Continuous Line","category":"fineline","description":"Whole image drawn with one unbroken line, Picasso-style.","history":"Inspired by one-line drawing exercises of modernist artists.","distinctFeatures":"One flowing uninterrupted contour forming a complete figure.","commonMotifs":["faces","animals","hands","hearts"],"relatedTechniques":["continuous_line","fine_line"],"relatedStyles":["linework_style","minimalist"],"sourcePaper":"STY-08","fieldNote":"Picasso''s one unbroken stroke, laid into skin without lifting the needle — economy as elegance.","keyFacts":[{"text":"Pablo Picasso produced a celebrated series of single-line animal drawings in the 1940s–1950s, reducing complex forms to one unbroken stroke.","evidence":"direct"},{"text":"Henri Matisse and Jean Cocteau are cited as having pursued comparable single-line drawing practices in the same period.","evidence":"direct"}]}'),
  ('lettering_script', 'lettering', 'Lettering / Script', 'The art of tattooed typography, from elegant calligraphy to bold graffiti fonts.', 'As old as tattooing itself; elevated by Chicano script and graffiti hand-styles.', 'Letterform craftsmanship, flow matched to body curves, flourishes and swashes.', 'Lettering / Script belongs to the Lettering & Script family. The art of tattooed typography, from elegant calligraphy to bold graffiti fonts. Its story begins here: As old as tattooing itself; elevated by Chicano script and graffiti hand-styles. On skin, it is recognized by letterform craftsmanship, flow matched to body curves, flourishes and swashes. Its visual vocabulary often includes names, quotes, dates, and ambigrams. The craft is commonly built with Script Lettering, Fine Line, Bold Line, and Single Needle. For a broader design conversation, compare it with Chicano, Graffiti, and Calligraphy / Calligraffiti.', 'en', '{"id":"lettering_script","name":"Lettering / Script","category":"lettering","description":"The art of tattooed typography, from elegant calligraphy to bold graffiti fonts.","history":"As old as tattooing itself; elevated by Chicano script and graffiti hand-styles.","distinctFeatures":"Letterform craftsmanship, flow matched to body curves, flourishes and swashes.","commonMotifs":["names","quotes","dates","ambigrams"],"relatedTechniques":["script_lettering","fine_line","bold_line","single_needle"],"relatedStyles":["chicano","graffiti","calligraphy"],"sourcePaper":"STY-08","fieldNote":"Cholo and blackletter script from the streets of L.A. — every swash weighted to stay legible for years.","keyFacts":[{"text":"Contemporary Los Angeles Chicano artist Big Sleeps grew up immersed in blackletter, Old English, and Cholo scripts passed down through barrio murals and prison tattoos before becoming a leading calligraffiti figure.","evidence":"direct"}]}'),
  ('calligraphy', 'lettering', 'Calligraphy / Calligraffiti', 'Expressive brush-and-nib letter art, including abstract unreadable calligraffiti.', 'Fusion of classical calligraphy with graffiti energy (2010s).', 'Dynamic stroke contrast, ink-splatter energy, letterforms as abstract texture.', 'Calligraphy / Calligraffiti belongs to the Lettering & Script family. Expressive brush-and-nib letter art, including abstract unreadable calligraffiti. Its story begins here: Fusion of classical calligraphy with graffiti energy (2010s). On skin, it is recognized by dynamic stroke contrast, ink-splatter energy, letterforms as abstract texture. Its visual vocabulary often includes Arabic/Gothic scripts and abstract strokes. The craft is commonly built with Brush Stroke, Script Lettering, and Whip Shading. For a broader design conversation, compare it with Lettering / Script, Abstract, and Graffiti.', 'en', '{"id":"calligraphy","name":"Calligraphy / Calligraffiti","category":"lettering","description":"Expressive brush-and-nib letter art, including abstract unreadable calligraffiti.","history":"Fusion of classical calligraphy with graffiti energy (2010s).","distinctFeatures":"Dynamic stroke contrast, ink-splatter energy, letterforms as abstract texture.","commonMotifs":["Arabic/Gothic scripts","abstract strokes"],"relatedTechniques":["brush_stroke","script_lettering","whip_shading"],"relatedStyles":["lettering_script","abstract","graffiti"],"sourcePaper":"STY-08","fieldNote":"Meulman''s calligraffiti — the brushstroke''s swell and taper, translated by a patient hand.","keyFacts":[{"text":"Dutch artist Niels \\"Shoe\\" Meulman (b. 1967) coined the term \\"Calligraffiti\\" in 2007, blending wildstyle graffiti lettering with Gothic blackletter, Roman capitals, and Asian brushwork.","evidence":"direct"},{"text":"A separate Middle Eastern lineage (the Hurufiyya movement, mid-20th century, associated with Hassan Massoudy, Hossein Zenderoudi, Parviz Tanavoli) fused calligraphic scripts with modern abstraction.","evidence":"direct"}]}'),
  ('horror', 'dark', 'Horror', 'Dark and macabre imagery inspired by horror films, literature and nightmares.', 'Rooted in Gothic aesthetics; boomed with horror realism in the late 20th century.', 'High-contrast black and grey (or blood-red accents), gore textures, cinematic lighting.', 'Horror belongs to the Dark Art & Horror family. Dark and macabre imagery inspired by horror films, literature and nightmares. Its story begins here: Rooted in Gothic aesthetics; boomed with horror realism in the late 20th century. On skin, it is recognized by high-contrast black and grey (or blood-red accents), gore textures, cinematic lighting. Its visual vocabulary often includes movie monsters, skulls, demons, and haunted scenes. The craft is commonly built with Soft Shading, Black & Grey Wash, Smoke Effect, and Layering. For a broader design conversation, compare it with Black & Grey Realism, Dark Art / Occult, and Surrealism.', 'en', '{"id":"horror","name":"Horror","category":"dark","description":"Dark and macabre imagery inspired by horror films, literature and nightmares.","history":"Rooted in Gothic aesthetics; boomed with horror realism in the late 20th century.","distinctFeatures":"High-contrast black and grey (or blood-red accents), gore textures, cinematic lighting.","commonMotifs":["movie monsters","skulls","demons","haunted scenes"],"relatedTechniques":["soft_shading","black_and_grey_wash","smoke_effect","layering"],"relatedStyles":["realism_bg","dark_art","surrealism"],"sourcePaper":"STY-09","fieldNote":"Booth''s theatre of the macabre — fear rendered convincingly enough to make you look twice.","keyFacts":[{"text":"Paul Booth opened Last Rites Tattoo Theatre in New Jersey in 1998, later relocating to New York City, operating until its 2020 pandemic-driven closure.","evidence":"direct"},{"text":"Booth received significant mainstream press coverage (Rolling Stone, 2002) tied to his popularity with heavy-metal musicians.","evidence":"direct"}]}'),
  ('dark_art', 'dark', 'Dark Art / Occult', 'Esoteric, satanic and witchcraft-adjacent blackwork: sigils, goats, moons and rituals.', 'Contemporary blackwork current drawing on occult illustration and etching.', 'Dense black, etching textures, symmetry, symbolic composition.', 'Dark Art / Occult belongs to the Dark Art & Horror family. Esoteric, satanic and witchcraft-adjacent blackwork: sigils, goats, moons and rituals. Its story begins here: Contemporary blackwork current drawing on occult illustration and etching. On skin, it is recognized by dense black, etching textures, symmetry, symbolic composition. Its visual vocabulary often includes baphomet, sigils, moth, third eye, and moons. The craft is commonly built with Whip Shading, Dotwork, Etching / Engraving, and Color Packing. For a broader design conversation, compare it with Blackwork, Etching / Engraving (Woodcut), Horror, and Gothic.', 'en', '{"id":"dark_art","name":"Dark Art / Occult","category":"dark","description":"Esoteric, satanic and witchcraft-adjacent blackwork: sigils, goats, moons and rituals.","history":"Contemporary blackwork current drawing on occult illustration and etching.","distinctFeatures":"Dense black, etching textures, symmetry, symbolic composition.","commonMotifs":["baphomet","sigils","moth","third eye","moons"],"relatedTechniques":["whip_shading","dotwork_technique","etching_technique","color_packing"],"relatedStyles":["blackwork_style","etching","horror","goth"],"sourcePaper":"STY-09","fieldNote":"The occult and the surreal-dark, held between horror and devotion — beauty that unsettles.","keyFacts":[{"text":"Paul Booth''s dark surrealist style spans both horror and occult/esoteric subject matter, described by Booth as focusing on \\"the macabre and the darker sides of human nature.\\"","evidence":"direct"},{"text":"Booth''s technique proceeds through distinct \\"packing\\" (solid black saturation) and \\"blending\\" (feathered dilution) stages to build depth and atmosphere.","evidence":"direct"}]}'),
  ('goth', 'dark', 'Gothic', 'Gothic architecture, blackletter and romantic-dark imagery.', 'Draws on medieval gothic art and modern goth subculture.', 'Blackletter type, cathedral windows, thorns, monochrome.', 'Gothic belongs to the Dark Art & Horror family. Gothic architecture, blackletter and romantic-dark imagery. Its story begins here: Draws on medieval gothic art and modern goth subculture. On skin, it is recognized by blackletter type, cathedral windows, thorns, monochrome. Its visual vocabulary often includes blackletter words, crosses, roses with thorns, and bats. The craft is commonly built with Bold Line, Whip Shading, and Script Lettering. For a broader design conversation, compare it with Dark Art / Occult, Lettering / Script, and Blackwork.', 'en', '{"id":"goth","name":"Gothic","category":"dark","description":"Gothic architecture, blackletter and romantic-dark imagery.","history":"Draws on medieval gothic art and modern goth subculture.","distinctFeatures":"Blackletter type, cathedral windows, thorns, monochrome.","commonMotifs":["blackletter words","crosses","roses with thorns","bats"],"relatedTechniques":["bold_line","whip_shading","script_lettering"],"relatedStyles":["dark_art","lettering_script","blackwork_style"],"sourcePaper":"STY-09","fieldNote":"Blackletter and the gothic mood — centuries of European script worn as atmosphere.","keyFacts":[{"text":"Blackletter (Textura, Rotunda, Schwabacher, Fraktur) was the dominant Western European script for roughly four centuries, developed by monastic scribes from the 12th century.","evidence":"direct"},{"text":"Blackletter''s specific tattoo-cultural entry point is documented as 1940s–50s East Los Angeles Chicano/Pachuco culture (\\"placas\\"), using makeshift implements, predating its separate adoption by biker/metal subcultures.","evidence":"direct"}]}'),
  ('religious', 'dark', 'Religious / Spiritual', 'Sacred imagery across faiths: Christ, Madonna, Buddha, deities and prayer scenes.', 'Among the oldest tattoo motifs — pilgrimage tattoos date back centuries (Coptic, Jerusalem).', 'Reverent black-and-grey realism or iconographic styling, light rays, drapery.', 'Religious / Spiritual belongs to the Dark Art & Horror family. Sacred imagery across faiths: Christ, Madonna, Buddha, deities and prayer scenes. Its story begins here: Among the oldest tattoo motifs — pilgrimage tattoos date back centuries (Coptic, Jerusalem). On skin, it is recognized by reverent black-and-grey realism or iconographic styling, light rays, drapery. Its visual vocabulary often includes praying hands, crosses, saints, Buddha, and Ganesha. The craft is commonly built with Black & Grey Wash, Soft Shading, and Single Needle. For a broader design conversation, compare it with Chicano, Black & Grey Realism, and Black & Grey.', 'en', '{"id":"religious","name":"Religious / Spiritual","category":"dark","description":"Sacred imagery across faiths: Christ, Madonna, Buddha, deities and prayer scenes.","history":"Among the oldest tattoo motifs — pilgrimage tattoos date back centuries (Coptic, Jerusalem).","distinctFeatures":"Reverent black-and-grey realism or iconographic styling, light rays, drapery.","commonMotifs":["praying hands","crosses","saints","Buddha","Ganesha"],"relatedTechniques":["black_and_grey_wash","soft_shading","single_needle"],"relatedStyles":["chicano","realism_bg","black_grey"],"sourcePaper":"STY-09","fieldNote":"Devotion carried since the Razzouk needles of Coptic Egypt — the oldest continuous pilgrimage in ink.","keyFacts":[{"text":"The Razzouk family, Coptic Christians, began tattooing in Egypt in the 14th century (c. 1300) and relocated the tradition to Jerusalem around 1750.","evidence":"direct"},{"text":"The tradition of Christian pilgrims receiving tattoos in the Holy Land is documented since the 8th century.","evidence":"direct"}]}'),
  ('uv_style', 'special', 'UV / Blacklight', 'Tattoos with UV-reactive ink, invisible or subtle in daylight and glowing under blacklight.', 'Emerged in the 1990s rave culture; inks remain a niche due to safety debate.', 'Glow under UV, often paired with normal ink as hidden layer.', 'UV / Blacklight belongs to the Special Purpose & Novelty family. Tattoos with UV-reactive ink, invisible or subtle in daylight and glowing under blacklight. Its story begins here: Emerged in the 1990s rave culture; inks remain a niche due to safety debate. On skin, it is recognized by glow under UV, often paired with normal ink as hidden layer. Its visual vocabulary often includes hidden messages, cosmic accents, and circuit lines. The craft is commonly built with UV Ink and Fine Line. For a broader design conversation, compare it with Glitch / Pixel and Minimalist.', 'en', '{"id":"uv_style","name":"UV / Blacklight","category":"special","description":"Tattoos with UV-reactive ink, invisible or subtle in daylight and glowing under blacklight.","history":"Emerged in the 1990s rave culture; inks remain a niche due to safety debate.","distinctFeatures":"Glow under UV, often paired with normal ink as hidden layer.","commonMotifs":["hidden messages","cosmic accents","circuit lines"],"relatedTechniques":["uv_ink","fine_line"],"relatedStyles":["glitch","minimalist"],"sourcePaper":"STY-10","fieldNote":"Ink that glows under blacklight and hides in daylight — thrilling, and unapproved for skin, so I name the risk first.","keyFacts":[{"text":"The FDA does not approve any tattoo ink, including UV ink, for injection into human skin.","evidence":"direct"},{"text":"UV ink''s fluorescent compounds have historically been approved by the FDA only for non-human (agricultural/fishing-industry) uses.","evidence":"community_attested"}]}'),
  ('white_ink_style', 'special', 'White Ink', 'Subtle tattoos in white ink only, resembling scarification or embossing.', '2000s niche trend for discreet tattoos.', 'Ghostly low-contrast marks, works best on light untanned skin, ages fast.', 'White Ink belongs to the Special Purpose & Novelty family. Subtle tattoos in white ink only, resembling scarification or embossing. Its story begins here: 2000s niche trend for discreet tattoos. On skin, it is recognized by ghostly low-contrast marks, works best on light untanned skin, ages fast. Its visual vocabulary often includes lace, script, and snowflakes. The craft is commonly built with White Ink Work and Fine Line. For a broader design conversation, compare it with Minimalist and Ornamental.', 'en', '{"id":"white_ink_style","name":"White Ink","category":"special","description":"Subtle tattoos in white ink only, resembling scarification or embossing.","history":"2000s niche trend for discreet tattoos.","distinctFeatures":"Ghostly low-contrast marks, works best on light untanned skin, ages fast.","commonMotifs":["lace","script","snowflakes"],"relatedTechniques":["white_ink_technique","fine_line"],"relatedStyles":["minimalist","ornamental"],"sourcePaper":"STY-10","fieldNote":"Pigment like a scar of light — beautiful fresh, but honest artists warn it fades fast and unevenly.","keyFacts":[{"text":"White ink tattoos fade significantly faster than other pigment colors, often showing significant fading within 1–3 years and oxidizing toward yellow/cream/grey tones.","evidence":"direct"},{"text":"Titanium dioxide (the common white-ink pigment) reacts more strongly to UV light than black ink, accelerating fading/yellowing.","evidence":"direct"},{"text":"Sources conflict on white ink''s visibility by skin tone: some describe it as striking on darker skin, while most describe poor contrast/chalky appearance on darker skin and better performance on fair skin.","evidence":"contested"}]}'),
  ('negative_space_style', 'special', 'Negative Space', 'The untouched skin forms the image while ink provides the background.', 'Design principle elevated to a style within modern blackwork.', 'Figure-ground reversal, bold black fields defining bright skin shapes.', 'Negative Space belongs to the Special Purpose & Novelty family. The untouched skin forms the image while ink provides the background. Its story begins here: Design principle elevated to a style within modern blackwork. On skin, it is recognized by figure-ground reversal, bold black fields defining bright skin shapes. Its visual vocabulary often includes patterns in black bands and silhouettes cut from black. The craft is commonly built with Negative Space, Color Packing, and Blackout. For a broader design conversation, compare it with Blackwork, Blackout / Heavy Blackwork, and Geometric.', 'en', '{"id":"negative_space_style","name":"Negative Space","category":"special","description":"The untouched skin forms the image while ink provides the background.","history":"Design principle elevated to a style within modern blackwork.","distinctFeatures":"Figure-ground reversal, bold black fields defining bright skin shapes.","commonMotifs":["patterns in black bands","silhouettes cut from black"],"relatedTechniques":["negative_space","color_packing","blackout_technique"],"relatedStyles":["blackwork_style","blackout_style","geometric"],"sourcePaper":"STY-10","fieldNote":"The image is the skin you leave untouched — a decision that demands flawless edges.","keyFacts":[{"text":"Negative space tattooing is a design principle (untouched skin as image) elevated to a standalone style within the blackwork/blackout movement.","evidence":"synthesized"}]}'),
  ('silhouette_style', 'special', 'Silhouette', 'Solid single-tone shapes of figures, often filled with scenes or galaxies.', 'Classic graphic device adapted to tattooing.', 'Hard-edged solid figures, optional double-exposure interior scenes.', 'Silhouette belongs to the Special Purpose & Novelty family. Solid single-tone shapes of figures, often filled with scenes or galaxies. Its story begins here: Classic graphic device adapted to tattooing. On skin, it is recognized by hard-edged solid figures, optional double-exposure interior scenes. Its visual vocabulary often includes wolf silhouettes, forests inside figures, and birds. The craft is commonly built with Silhouette, Color Packing, and Negative Space. For a broader design conversation, compare it with Blackwork and Minimalist.', 'en', '{"id":"silhouette_style","name":"Silhouette","category":"special","description":"Solid single-tone shapes of figures, often filled with scenes or galaxies.","history":"Classic graphic device adapted to tattooing.","distinctFeatures":"Hard-edged solid figures, optional double-exposure interior scenes.","commonMotifs":["wolf silhouettes","forests inside figures","birds"],"relatedTechniques":["silhouette_technique","color_packing","negative_space"],"relatedStyles":["blackwork_style","minimalist"],"sourcePaper":"STY-10","fieldNote":"The figure as a single solid shadow — bold, graphic, and built to hold.","keyFacts":[{"text":"Silhouette tattooing uses solid, hard-edged single-tone figure fills, sometimes with interior \\"double-exposure\\" scene detail.","evidence":"synthesized"}]}'),
  ('handpoke_style', 'special', 'Handpoke / Stick-and-Poke', 'Machine-free tattoos with a distinct soft, dotted, DIY-craft character.', 'The original tattoo method worldwide; modern revival as a slow-craft movement.', 'Dot-built lines, softer healing, intimate small-scale designs.', 'Handpoke / Stick-and-Poke belongs to the Special Purpose & Novelty family. Machine-free tattoos with a distinct soft, dotted, DIY-craft character. Its story begins here: The original tattoo method worldwide; modern revival as a slow-craft movement. On skin, it is recognized by dot-built lines, softer healing, intimate small-scale designs. Its visual vocabulary often includes folk symbols, small doodles, and dotwork ornaments. The craft is commonly built with Hand Poke (Stick & Poke), Dotwork, and Stippling. For a broader design conversation, compare it with Ignorant Style, Dotwork, and Minimalist.', 'en', '{"id":"handpoke_style","name":"Handpoke / Stick-and-Poke","category":"special","description":"Machine-free tattoos with a distinct soft, dotted, DIY-craft character.","history":"The original tattoo method worldwide; modern revival as a slow-craft movement.","distinctFeatures":"Dot-built lines, softer healing, intimate small-scale designs.","commonMotifs":["folk symbols","small doodles","dotwork ornaments"],"relatedTechniques":["hand_poke","dotwork_technique","stippling"],"relatedStyles":["ignorant","dotwork_style","minimalist"],"sourcePaper":"STY-10","fieldNote":"The oldest method, worn on Ötzi himself — a slower, quieter mark made point by point.","keyFacts":[{"text":"The oldest known tattoos, on the 5,300-year-old mummy Ötzi the Iceman, were created by hand-poke-adjacent incision-and-charcoal methods.","evidence":"direct"},{"text":"The specific contemporary Western \\"stick-and-poke\\" revival is dated to 1970s–1980s punk/hardcore DIY subculture, functioning as anti-establishment rejection of commercial tattoo-parlor culture.","evidence":"direct"}]}'),
  ('cosmetic', 'special', 'Cosmetic / Paramedical', 'Functional tattooing: permanent makeup, scar camouflage, areola restoration, scalp micropigmentation.', 'Medical-adjacent branch professionalized since the 1980s.', 'Skin-tone pigments, natural-effect micro-strokes, medical hygiene protocols.', 'Cosmetic / Paramedical belongs to the Special Purpose & Novelty family. Functional tattooing: permanent makeup, scar camouflage, areola restoration, scalp micropigmentation. Its story begins here: Medical-adjacent branch professionalized since the 1980s. On skin, it is recognized by skin-tone pigments, natural-effect micro-strokes, medical hygiene protocols. Its visual vocabulary often includes brows (microblading), areola 3D, scar camouflage, and hair follicle dots. The craft is commonly built with Single Needle, Stippling, and Layering. For a broader design conversation, compare it with Color Realism.', 'en', '{"id":"cosmetic","name":"Cosmetic / Paramedical","category":"special","description":"Functional tattooing: permanent makeup, scar camouflage, areola restoration, scalp micropigmentation.","history":"Medical-adjacent branch professionalized since the 1980s.","distinctFeatures":"Skin-tone pigments, natural-effect micro-strokes, medical hygiene protocols.","commonMotifs":["brows (microblading)","areola 3D","scar camouflage","hair follicle dots"],"relatedTechniques":["single_needle","stippling","layering"],"relatedStyles":["realism_color"],"sourcePaper":"STY-10","fieldNote":"Ink as healing — areola and scar restoration; here I defer to the paramedical hand and the doctor, always.","keyFacts":[{"text":"Paramedical/cosmetic tattooing covers areola/nipple restoration, scar and stretch-mark camouflage, vitiligo/skin-discoloration camouflage, and scalp micropigmentation, practiced by professionals holding specific certifications (e.g., CPCP, CPTP).","evidence":"direct"},{"text":"No specific named originating pioneer, studio, or founding date for paramedical tattooing as a professionalized field was identified in sources reviewed.","evidence":"unknown"}]}'),
  ('vintage_americana', 'traditional', 'Vintage / Flash Revival', 'Faithful recreation of antique flash sheets, including aged ''faded'' looks.', 'Revival movement honoring pre-war flash artists (Cap Coleman, Bert Grimm).', 'Deliberately aged palettes, historical motifs, classic placements.', 'Vintage / Flash Revival belongs to the Traditional & Old School family. Faithful recreation of antique flash sheets, including aged ''faded'' looks. Its story begins here: Revival movement honoring pre-war flash artists (Cap Coleman, Bert Grimm). On skin, it is recognized by deliberately aged palettes, historical motifs, classic placements. Its visual vocabulary often includes circus ladies, panthers, and gypsy heads. The craft is commonly built with Bold Line, Color Packing, and Whip Shading. For a broader design conversation, compare it with American Traditional and Old School.', 'en', '{"id":"vintage_americana","name":"Vintage / Flash Revival","category":"traditional","description":"Faithful recreation of antique flash sheets, including aged ''faded'' looks.","history":"Revival movement honoring pre-war flash artists (Cap Coleman, Bert Grimm).","distinctFeatures":"Deliberately aged palettes, historical motifs, classic placements.","commonMotifs":["circus ladies","panthers","gypsy heads"],"relatedTechniques":["bold_line","color_packing","whip_shading"],"relatedStyles":["american_traditional","old_school"],"sourcePaper":"STY-01","fieldNote":"A deliberate return to the old flash, painted with a historian''s care — nostalgia made permanent.","keyFacts":[{"text":"A contemporary (c. 1990s–present) revival reproducing the early American Traditional idiom with historical accuracy.","evidence":"direct"},{"text":"Theorized by Matt Lodder as the \\"new old style,\\" simultaneously old and new.","evidence":"direct"}]}')
ON DUPLICATE KEY UPDATE
  `category_id` = VALUES(`category_id`),
  `name` = VALUES(`name`),
  `description` = VALUES(`description`),
  `history` = VALUES(`history`),
  `distinct_features` = VALUES(`distinct_features`),
  `narrative_description` = VALUES(`narrative_description`),
  `narrative_language` = VALUES(`narrative_language`),
  `source_payload` = VALUES(`source_payload`);

INSERT INTO `techniques` (`technique_id`, `category_id`, `name`, `description`, `difficulty`, `narrative_description`, `narrative_language`, `source_payload`)
VALUES
  ('soft_shading', 'shading', 'Soft Shading', 'Gentle gradients for subtle tonal transitions; needle moved lightly in overlapping passes.', 'advanced', 'Soft Shading is an advanced-level method within Shading. Gentle gradients for subtle tonal transitions; needle moved lightly in overlapping passes. In practice, it shapes the way ink, line and skin meet rather than defining the subject by itself. It is especially at home in Black & Grey Realism, Color Realism, Portrait, Black & Grey, and Horror. Its success depends on deliberate execution, anatomical placement and enough spacing for the tattoo to age clearly.', 'en', '{"id":"soft_shading","name":"Soft Shading","category":"shading","description":"Gentle gradients for subtle tonal transitions; needle moved lightly in overlapping passes.","usedInStyles":["realism_bg","realism_color","portrait","black_grey","horror"],"difficulty":"advanced","sourcePaper":"TEC-02","fieldNote":"Overlapping passes that melt one tone into the next — the shadow that breathes rather than steps.","keyFacts":[{"text":"Soft shading and gradient blending achieve tonal transition through needle-pass overlap/layering rather than ink dilution, distinct from black_and_grey_wash''s dilution-based mechanism.","evidence":"synthesized"},{"text":"Hard shading is characterized by abrupt tonal boundaries rather than smooth gradient, foundational to American Traditional''s visual grammar.","evidence":"direct"}]}'),
  ('hard_shading', 'shading', 'Hard Shading', 'Bold, high-contrast shading with abrupt tonal edges.', 'intermediate', 'Hard Shading is an intermediate-level method within Shading. Bold, high-contrast shading with abrupt tonal edges. In practice, it shapes the way ink, line and skin meet rather than defining the subject by itself. It is especially at home in American Traditional, Old School, and Japanese Irezumi. Its success depends on deliberate execution, anatomical placement and enough spacing for the tattoo to age clearly.', 'en', '{"id":"hard_shading","name":"Hard Shading","category":"shading","description":"Bold, high-contrast shading with abrupt tonal edges.","usedInStyles":["american_traditional","old_school","irezumi"],"difficulty":"intermediate","sourcePaper":"TEC-02","fieldNote":"The opposite of soft: abrupt black against light, the backbone of traditional contrast and irezumi backgrounds.","keyFacts":[{"text":"Abrupt-contrast shading without smooth gradient, foundational to American Traditional/Old School and Irezumi background rendering; the technical opposite of soft_shading.","evidence":"synthesized"}]}'),
  ('whip_shading', 'shading', 'Whip Shading', 'Flicking ''whip'' motion leaving tapered dotted-line gradients; signature dynamic texture.', 'intermediate', 'Whip Shading is an intermediate-level method within Shading. Flicking ''whip'' motion leaving tapered dotted-line gradients; signature dynamic texture. In practice, it shapes the way ink, line and skin meet rather than defining the subject by itself. It is especially at home in Etching / Engraving (Woodcut), Sketch Style, Dark Art / Occult, and American Traditional. Its success depends on deliberate execution, anatomical placement and enough spacing for the tattoo to age clearly.', 'en', '{"id":"whip_shading","name":"Whip Shading","category":"shading","description":"Flicking ''whip'' motion leaving tapered dotted-line gradients; signature dynamic texture.","usedInStyles":["etching","sketch","dark_art","american_traditional"],"difficulty":"intermediate","sourcePaper":"TEC-02","fieldNote":"A flick of the needle off the skin — texture that fades to nothing at its tail.","keyFacts":[{"text":"Whip shading, pepper shading, and crosshatching are three technically distinct needle-motion/mark-pattern techniques frequently conflated in casual trade usage.","evidence":"hypothesis"},{"text":"Crosshatching directly translates Renaissance/early-modern print-hatching technique into tattoo form, credited to artists including Yvonne and Duncan X.","evidence":"direct"}]}'),
  ('pepper_shading', 'shading', 'Pepper Shading', 'Fast scattered speckle shading producing a grainy, ''peppered'' tone.', 'intermediate', 'Pepper Shading is an intermediate-level method within Shading. Fast scattered speckle shading producing a grainy, ''peppered'' tone. In practice, it shapes the way ink, line and skin meet rather than defining the subject by itself. It is especially at home in American Traditional, Sketch Style, and Etching / Engraving (Woodcut). Its success depends on deliberate execution, anatomical placement and enough spacing for the tattoo to age clearly.', 'en', '{"id":"pepper_shading","name":"Pepper Shading","category":"shading","description":"Fast scattered speckle shading producing a grainy, ''peppered'' tone.","usedInStyles":["american_traditional","sketch","etching"],"difficulty":"intermediate","sourcePaper":"TEC-02","fieldNote":"Scattered specks like grain — grit and atmosphere, best kept coarse enough to survive healing.","keyFacts":[{"text":"Fast, scattered speckle-shading technique producing grainy texture; associated with American Traditional, Sketch, and Etching, distinguished from both whip_shading (directional taper) and dotwork.","evidence":"synthesized"}]}'),
  ('black_and_grey_wash', 'shading', 'Black & Grey Wash', 'Diluted black ink applied in layers for smooth monochromatic gradients.', 'advanced', 'Black & Grey Wash is an advanced-level method within Shading. Diluted black ink applied in layers for smooth monochromatic gradients. In practice, it shapes the way ink, line and skin meet rather than defining the subject by itself. It is especially at home in Black & Grey, Black & Grey Realism, Chicano, Religious / Spiritual, and Portrait. Its success depends on deliberate execution, anatomical placement and enough spacing for the tattoo to age clearly.', 'en', '{"id":"black_and_grey_wash","name":"Black & Grey Wash","category":"shading","description":"Diluted black ink applied in layers for smooth monochromatic gradients.","usedInStyles":["black_grey","realism_bg","chicano","religious","portrait"],"difficulty":"advanced","sourcePaper":"TEC-02","fieldNote":"Carbon black, diluted like watercolor — a whole grey range from one honest pigment.","keyFacts":[{"text":"Black & grey wash depends on diluting carbon-black ink to produce a controllable grey range, originating in 1960s–70s East LA Chicano prison culture.","evidence":"direct"}]}'),
  ('crosshatching', 'shading', 'Crosshatching', 'Intersecting line sets that build tone like pen-and-ink drawing.', 'intermediate', 'Crosshatching is an intermediate-level method within Shading. Intersecting line sets that build tone like pen-and-ink drawing. In practice, it shapes the way ink, line and skin meet rather than defining the subject by itself. It is especially at home in Etching / Engraving (Woodcut), Sketch Style, and Illustrative. Its success depends on deliberate execution, anatomical placement and enough spacing for the tattoo to age clearly.', 'en', '{"id":"crosshatching","name":"Crosshatching","category":"shading","description":"Intersecting line sets that build tone like pen-and-ink drawing.","usedInStyles":["etching","sketch","illustrative"],"difficulty":"intermediate","sourcePaper":"TEC-02","fieldNote":"Renaissance print-hatching brought to skin — tone built from crossed lines, not a smoothed gradient.","keyFacts":[{"text":"Intersecting-line tonal-building technique translating Renaissance/early-modern print-hatching into tattoo form, foundational to Etching and Sketch styles.","evidence":"synthesized"}]}'),
  ('gradient_blending', 'shading', 'Gradient Blending', 'Seamless transition between tonal values across large areas.', 'advanced', 'Gradient Blending is an advanced-level method within Shading. Seamless transition between tonal values across large areas. In practice, it shapes the way ink, line and skin meet rather than defining the subject by itself. It is especially at home in Black & Grey Realism, Color Realism, and 3D / Optical Illusion. Its success depends on deliberate execution, anatomical placement and enough spacing for the tattoo to age clearly.', 'en', '{"id":"gradient_blending","name":"Gradient Blending","category":"shading","description":"Seamless transition between tonal values across large areas.","usedInStyles":["realism_bg","realism_color","3d_style"],"difficulty":"advanced","sourcePaper":"TEC-02","fieldNote":"The long, layered fade across a large field — earned over sessions, never in one pass.","keyFacts":[{"text":"Seamless large-area tonal-transition technique dependent on multi-session layering, foundational to large-scale color realism and hyperrealism.","evidence":"synthesized"}]}'),
  ('fine_line', 'linework', 'Fine Line', 'Delicate thin lines for fragile detail; small needle groupings (1RL–3RL).', 'advanced', 'Fine Line is an advanced-level method within Linework. Delicate thin lines for fragile detail; small needle groupings (1RL–3RL). In practice, it shapes the way ink, line and skin meet rather than defining the subject by itself. It is especially at home in Fine Line, Micro Realism, Minimalist, Ornamental, and Chicano. Its success depends on deliberate execution, anatomical placement and enough spacing for the tattoo to age clearly.', 'en', '{"id":"fine_line","name":"Fine Line","category":"linework","description":"Delicate thin lines for fragile detail; small needle groupings (1RL–3RL).","usedInStyles":["fineline_style","micro_realism","minimalist","ornamental","chicano"],"difficulty":"advanced","sourcePaper":"TEC-01","fieldNote":"The thinnest mark the needle can hold — precise, delicate, and the first to blur, so choose its placement with care.","keyFacts":[{"text":"Needle grouping (RL, RS, bugpin gauge) and voltage/depth settings determine line weight and, correspondingly, long-term pigment retention.","evidence":"synthesized"},{"text":"Fine-line/single-needle technique carries materially higher blur/migration risk than bold-line technique, consistent with documented \\"tattoo blowout\\" and immune-mediated fading mechanisms.","evidence":"direct"}]}'),
  ('bold_line', 'linework', 'Bold Line', 'Thick, confident outlines built with large liners; backbone of traditional styles.', 'intermediate', 'Bold Line is an intermediate-level method within Linework. Thick, confident outlines built with large liners; backbone of traditional styles. In practice, it shapes the way ink, line and skin meet rather than defining the subject by itself. It is especially at home in American Traditional, Japanese Irezumi, Tribal (Modern), New School, and Gothic. Its success depends on deliberate execution, anatomical placement and enough spacing for the tattoo to age clearly.', 'en', '{"id":"bold_line","name":"Bold Line","category":"linework","description":"Thick, confident outlines built with large liners; backbone of traditional styles.","usedInStyles":["american_traditional","irezumi","tribal","new_school","goth"],"difficulty":"intermediate","sourcePaper":"TEC-01","fieldNote":"The two-to-four-millimetre line that outlasts everything — when longevity matters, this is where we begin.","keyFacts":[{"text":"Thick (2–4mm), uniform-weight line executed with larger needle groupings and liner machines at higher voltage/depth, the structural backbone of American Traditional, Old School, Vintage/Flash Revival, and most Blackwork-family styles.","evidence":"synthesized"},{"text":"The most durable line-weight technique documented in this corpus.","evidence":"synthesized"}]}'),
  ('broken_line', 'linework', 'Broken Line', 'Deliberately interrupted strokes for a sketchy, artistic effect.', 'basic', 'Broken Line is a basic-level method within Linework. Deliberately interrupted strokes for a sketchy, artistic effect. In practice, it shapes the way ink, line and skin meet rather than defining the subject by itself. It is especially at home in Sketch Style, Ignorant Style, and Abstract. Its success depends on deliberate execution, anatomical placement and enough spacing for the tattoo to age clearly.', 'en', '{"id":"broken_line","name":"Broken Line","category":"linework","description":"Deliberately interrupted strokes for a sketchy, artistic effect.","usedInStyles":["sketch","ignorant","abstract"],"difficulty":"basic","sourcePaper":"TEC-01","fieldNote":"The line that starts and stops on purpose — sketch and ''ignorant'' work embrace the interruption.","keyFacts":[{"text":"Broken-line and continuous-line techniques are stroke-continuity choices independent of needle gauge, each serving a distinct aesthetic goal (sketchy incompleteness vs. singular unbroken form).","evidence":"synthesized"}]}'),
  ('continuous_line', 'linework', 'Continuous Line', 'One flowing uninterrupted line forming a complete design.', 'intermediate', 'Continuous Line is an intermediate-level method within Linework. One flowing uninterrupted line forming a complete design. In practice, it shapes the way ink, line and skin meet rather than defining the subject by itself. It is especially at home in Single / Continuous Line, Linework, and Minimalist. Its success depends on deliberate execution, anatomical placement and enough spacing for the tattoo to age clearly.', 'en', '{"id":"continuous_line","name":"Continuous Line","category":"linework","description":"One flowing uninterrupted line forming a complete design.","usedInStyles":["single_line","linework_style","minimalist"],"difficulty":"intermediate","sourcePaper":"TEC-01","fieldNote":"One stroke, needle never lifted — the discipline of drawing a thing without a single pause.","keyFacts":[{"text":"Single unbroken-line execution for an entire design element, the technical foundation of Single/Continuous Line tattooing, directly descended from the early-20th-century fine-art single-line drawing tradition (Picasso, Matisse, Cocteau).","evidence":"synthesized"}]}'),
  ('single_needle', 'linework', 'Single Needle', 'Tattooing with one needle (1RL) for the finest possible marks and micro-shading.', 'expert', 'Single Needle is an expert-level method within Linework. Tattooing with one needle (1RL) for the finest possible marks and micro-shading. In practice, it shapes the way ink, line and skin meet rather than defining the subject by itself. It is especially at home in Chicano, Fine Line, Micro Realism, and Cosmetic / Paramedical. Its success depends on deliberate execution, anatomical placement and enough spacing for the tattoo to age clearly.', 'en', '{"id":"single_needle","name":"Single Needle","category":"linework","description":"Tattooing with one needle (1RL) for the finest possible marks and micro-shading.","usedInStyles":["chicano","fineline_style","micro_realism","cosmetic"],"difficulty":"expert","sourcePaper":"TEC-01","fieldNote":"A lone 1RL — the hardware Chicano artists were forced into, then chose for its whisper of detail.","keyFacts":[{"text":"The specific 1RL hardware configuration, historically forced by the physical limits of homemade Chicano prison machines and subsequently adopted deliberately by professional artists (Good Time Charlie''s Tattooland) for controlled fine detail and grey-wash shading precision.","evidence":"synthesized"}]}'),
  ('script_lettering', 'linework', 'Script Lettering', 'Precise letterform construction: consistent weight, spacing and flourish control.', 'advanced', 'Script Lettering is an advanced-level method within Linework. Precise letterform construction: consistent weight, spacing and flourish control. In practice, it shapes the way ink, line and skin meet rather than defining the subject by itself. It is especially at home in Lettering / Script, Chicano, Calligraphy / Calligraffiti, and Gothic. Its success depends on deliberate execution, anatomical placement and enough spacing for the tattoo to age clearly.', 'en', '{"id":"script_lettering","name":"Script Lettering","category":"linework","description":"Precise letterform construction: consistent weight, spacing and flourish control.","usedInStyles":["lettering_script","chicano","calligraphy","goth"],"difficulty":"advanced","sourcePaper":"TEC-01","fieldNote":"Letterforms as their own craft — consistent weight and controlled flourish so the words stay readable for years.","keyFacts":[{"text":"Script lettering spans Chicano Old English, global calligraffiti, and gothic blackletter traditions, each with documented distinct historical origins.","evidence":"direct"},{"text":"Tapered-line technique has no independently documented named pioneer distinct from the broader illustrative/calligraphic current.","evidence":"unknown"}]}'),
  ('tapered_lines', 'linework', 'Tapered Lines', 'Lines that swell and thin like brush strokes, controlled by speed and hand pressure.', 'advanced', 'Tapered Lines is an advanced-level method within Linework. Lines that swell and thin like brush strokes, controlled by speed and hand pressure. In practice, it shapes the way ink, line and skin meet rather than defining the subject by itself. It is especially at home in Calligraphy / Calligraffiti, Illustrative, and Neo-Traditional. Its success depends on deliberate execution, anatomical placement and enough spacing for the tattoo to age clearly.', 'en', '{"id":"tapered_lines","name":"Tapered Lines","category":"linework","description":"Lines that swell and thin like brush strokes, controlled by speed and hand pressure.","usedInStyles":["calligraphy","illustrative","neo_traditional"],"difficulty":"advanced","sourcePaper":"TEC-01","fieldNote":"A line that swells and thins within a single stroke — the loaded brush, faked through speed and pressure.","keyFacts":[{"text":"Dynamic swelling/thinning line weight within a single stroke, mimicking loaded-brush or calligraphy-pen marks, controlled via needle speed and hand pressure; foundational to Calligraphy/Calligraffiti''s Arabic and Latin brush-stroke traditions and to Illustrative styles generally.","evidence":"synthesized"}]}'),
  ('color_packing', 'coloring', 'Color Packing', 'Dense, even saturation of solid color (or black) with magnum needles in tight circles.', 'intermediate', 'Color Packing is an intermediate-level method within Coloring. Dense, even saturation of solid color (or black) with magnum needles in tight circles. In practice, it shapes the way ink, line and skin meet rather than defining the subject by itself. It is especially at home in American Traditional, New School, Japanese Irezumi, Blackwork, and Anime / Manga. Its success depends on deliberate execution, anatomical placement and enough spacing for the tattoo to age clearly.', 'en', '{"id":"color_packing","name":"Color Packing","category":"coloring","description":"Dense, even saturation of solid color (or black) with magnum needles in tight circles.","usedInStyles":["american_traditional","new_school","irezumi","blackwork_style","anime"],"difficulty":"intermediate","sourcePaper":"TEC-03","fieldNote":"Dense, flat, saturated fill — the traditional and irezumi way of making color truly solid.","keyFacts":[{"text":"Color packing (flat, dense, magnum-applied) is foundational to American Traditional and Irezumi; color shading (single-hue gradient) distinguishes Neo-Traditional; color blending (multi-hue transition) is foundational to Color Realism.","evidence":"direct"}]}'),
  ('color_shading', 'coloring', 'Color Shading', 'Gradients and transitions within color: light-to-dark of one hue.', 'intermediate', 'Color Shading is an intermediate-level method within Coloring. Gradients and transitions within color: light-to-dark of one hue. In practice, it shapes the way ink, line and skin meet rather than defining the subject by itself. It is especially at home in Neo-Traditional, Japanese Irezumi, and Illustrative. Its success depends on deliberate execution, anatomical placement and enough spacing for the tattoo to age clearly.', 'en', '{"id":"color_shading","name":"Color Shading","category":"coloring","description":"Gradients and transitions within color: light-to-dark of one hue.","usedInStyles":["neo_traditional","irezumi","illustrative"],"difficulty":"intermediate","sourcePaper":"TEC-03","fieldNote":"One hue pulled light to dark — the dimension that lifts neo-traditional color off the skin.","keyFacts":[{"text":"Light-to-dark single-hue gradient technique distinguishing Neo-Traditional''s dimensional color rendering from flat color_packing.","evidence":"synthesized"}]}'),
  ('color_blending', 'coloring', 'Color Blending', 'Merging multiple hues seamlessly, wet-in-wet painting logic on skin.', 'advanced', 'Color Blending is an advanced-level method within Coloring. Merging multiple hues seamlessly, wet-in-wet painting logic on skin. In practice, it shapes the way ink, line and skin meet rather than defining the subject by itself. It is especially at home in Color Realism, Watercolor, and Neo-Japanese. Its success depends on deliberate execution, anatomical placement and enough spacing for the tattoo to age clearly.', 'en', '{"id":"color_blending","name":"Color Blending","category":"coloring","description":"Merging multiple hues seamlessly, wet-in-wet painting logic on skin.","usedInStyles":["realism_color","watercolor_style","neo_japanese"],"difficulty":"advanced","sourcePaper":"TEC-03","fieldNote":"Wet-in-wet hues melting together — the painterly heart of color realism.","keyFacts":[{"text":"Multi-hue seamless-transition technique using wet-in-wet painting logic, foundational to Color Realism and Watercolor.","evidence":"synthesized"}]}'),
  ('white_highlights', 'coloring', 'White Highlights', 'Final white accents creating gloss, moisture and pop.', 'intermediate', 'White Highlights is an intermediate-level method within Coloring. Final white accents creating gloss, moisture and pop. In practice, it shapes the way ink, line and skin meet rather than defining the subject by itself. It is especially at home in Color Realism, Portrait, Embroidery / Patch, Hyperrealism, and Anime / Manga. Its success depends on deliberate execution, anatomical placement and enough spacing for the tattoo to age clearly.', 'en', '{"id":"white_highlights","name":"White Highlights","category":"coloring","description":"Final white accents creating gloss, moisture and pop.","usedInStyles":["realism_color","portrait","embroidery","hyperrealism","anime"],"difficulty":"intermediate","sourcePaper":"TEC-03","fieldNote":"The final spark of white that makes an eye wet and a chrome edge shine — used last, and sparingly.","keyFacts":[{"text":"White highlights function as a finishing accent technique across Color Realism, Portrait, Embroidery, Hyperrealism, and Anime, distinct from white_ink_technique''s full-design application.","evidence":"synthesized"},{"text":"White ink work carries documented, disputed skin-tone-visibility characteristics and unusually rapid fading.","evidence":"contested"}]}'),
  ('white_ink_technique', 'coloring', 'White Ink Work', 'Designs executed entirely or mostly in white ink.', 'advanced', 'White Ink Work is an advanced-level method within Coloring. Designs executed entirely or mostly in white ink. In practice, it shapes the way ink, line and skin meet rather than defining the subject by itself. It is especially at home in White Ink and Sticker / Patchwork. Its success depends on deliberate execution, anatomical placement and enough spacing for the tattoo to age clearly.', 'en', '{"id":"white_ink_technique","name":"White Ink Work","category":"coloring","description":"Designs executed entirely or mostly in white ink.","usedInStyles":["white_ink_style","sticker_patchwork"],"difficulty":"advanced","sourcePaper":"TEC-03","fieldNote":"Whole designs in white pigment — I use it knowing the record on its fading, and I tell you that record.","keyFacts":[{"text":"Full-design, entirely-white-pigment application technique underlying White Ink style, carrying documented, disputed skin-tone-visibility characteristics and unusually rapid fading (1–3 years to significant visible change per STY-10, Section 3).","evidence":"synthesized"}]}'),
  ('watercolor_technique', 'coloring', 'Watercolor Technique', 'Loose washes, bleeds and splatter mimicking wet paint; low or no outline.', 'advanced', 'Watercolor Technique is an advanced-level method within Coloring. Loose washes, bleeds and splatter mimicking wet paint; low or no outline. In practice, it shapes the way ink, line and skin meet rather than defining the subject by itself. It is especially at home in Watercolor, Abstract, and Illustrative. Its success depends on deliberate execution, anatomical placement and enough spacing for the tattoo to age clearly.', 'en', '{"id":"watercolor_technique","name":"Watercolor Technique","category":"coloring","description":"Loose washes, bleeds and splatter mimicking wet paint; low or no outline.","usedInStyles":["watercolor_style","abstract","illustrative"],"difficulty":"advanced","sourcePaper":"TEC-03","fieldNote":"Wachob''s washes and greylining — brush behavior coaxed out of a needle.","keyFacts":[{"text":"Watercolor technique, including \\"greylining,\\" was pioneered by Amanda Wachob from 2008.","evidence":"direct"}]}'),
  ('dotwork_technique', 'dotwork', 'Dotwork', 'Composing tone and texture from individual dots of varied density.', 'advanced', 'Dotwork is an advanced-level method within Dotwork & Pointillism. Composing tone and texture from individual dots of varied density. In practice, it shapes the way ink, line and skin meet rather than defining the subject by itself. It is especially at home in Dotwork, Geometric, Mandala / Ornamental, Sacred Geometry, and Dark Art / Occult. Its success depends on deliberate execution, anatomical placement and enough spacing for the tattoo to age clearly.', 'en', '{"id":"dotwork_technique","name":"Dotwork","category":"dotwork","description":"Composing tone and texture from individual dots of varied density.","usedInStyles":["dotwork_style","geometric","mandala","sacred_geometry","dark_art"],"difficulty":"advanced","sourcePaper":"TEC-04","fieldNote":"Image built from deliberate dots — the modern craft the Dotfather opened around 1980.","keyFacts":[{"text":"Dotwork''s modern named-style origin is credited to Xed LeHead (c. 1980 onward), developed further by the Into You London studio scene.","evidence":"direct"}]}'),
  ('stippling', 'dotwork', 'Stippling', 'Fine speckled dot shading for soft gradients without lines.', 'intermediate', 'Stippling is an intermediate-level method within Dotwork & Pointillism. Fine speckled dot shading for soft gradients without lines. In practice, it shapes the way ink, line and skin meet rather than defining the subject by itself. It is especially at home in Dotwork, Handpoke / Stick-and-Poke, Cosmetic / Paramedical, and Mandala / Ornamental. Its success depends on deliberate execution, anatomical placement and enough spacing for the tattoo to age clearly.', 'en', '{"id":"stippling","name":"Stippling","category":"dotwork","description":"Fine speckled dot shading for soft gradients without lines.","usedInStyles":["dotwork_style","handpoke_style","cosmetic","mandala"],"difficulty":"intermediate","sourcePaper":"TEC-04","fieldNote":"Fine, line-free dots for the softest gradient — patience measured in thousands of taps.","keyFacts":[{"text":"Stippling denotes fine, line-free dot application producing soft gradients, applied both in machine dotwork and the deeper hand-poke tradition predating the electric machine.","evidence":"synthesized"}]}'),
  ('dot_gradients', 'dotwork', 'Dot Gradients', 'Systematic dot-density transitions from dark to light.', 'advanced', 'Dot Gradients is an advanced-level method within Dotwork & Pointillism. Systematic dot-density transitions from dark to light. In practice, it shapes the way ink, line and skin meet rather than defining the subject by itself. It is especially at home in Dotwork, Geometric, and Sacred Geometry. Its success depends on deliberate execution, anatomical placement and enough spacing for the tattoo to age clearly.', 'en', '{"id":"dot_gradients","name":"Dot Gradients","category":"dotwork","description":"Systematic dot-density transitions from dark to light.","usedInStyles":["dotwork_style","geometric","sacred_geometry"],"difficulty":"advanced","sourcePaper":"TEC-04","fieldNote":"Engineered density, dark to light — a gradient you can count, not just feel.","keyFacts":[{"text":"Dot gradients denote systematic, engineered dark-to-light density transitions distinct from stippling''s uniform soft tone, used in geometric and sacred-geometric compositions requiring precise directional value control.","evidence":"synthesized"}]}'),
  ('realism_rendering', 'dimensional', 'Realistic Rendering', 'Full realist workflow: reference mapping, value structure, texture passes.', 'expert', 'Realistic Rendering is an expert-level method within 3D & Optical. Full realist workflow: reference mapping, value structure, texture passes. In practice, it shapes the way ink, line and skin meet rather than defining the subject by itself. It is especially at home in Black & Grey Realism, Color Realism, Portrait, and Hyperrealism. Its success depends on deliberate execution, anatomical placement and enough spacing for the tattoo to age clearly.', 'en', '{"id":"realism_rendering","name":"Realistic Rendering","category":"dimensional","description":"Full realist workflow: reference mapping, value structure, texture passes.","usedInStyles":["realism_bg","realism_color","portrait","hyperrealism"],"difficulty":"expert","sourcePaper":"TEC-05","fieldNote":"The full realist workflow — reference mapped to value to texture, layer by patient layer.","keyFacts":[{"text":"Realistic rendering is the full realist workflow (reference mapping, value structure, texture passes) underlying the entire realism style family.","evidence":"direct"}]}'),
  ('depth_effects', 'dimensional', 'Depth Effects', 'Cast shadows, perspective and atmospheric fade producing three-dimensional appearance.', 'expert', 'Depth Effects is an expert-level method within 3D & Optical. Cast shadows, perspective and atmospheric fade producing three-dimensional appearance. In practice, it shapes the way ink, line and skin meet rather than defining the subject by itself. It is especially at home in 3D / Optical Illusion, Biomechanical, Hyperrealism, and Embroidery / Patch. Its success depends on deliberate execution, anatomical placement and enough spacing for the tattoo to age clearly.', 'en', '{"id":"depth_effects","name":"Depth Effects","category":"dimensional","description":"Cast shadows, perspective and atmospheric fade producing three-dimensional appearance.","usedInStyles":["3d_style","biomechanical","hyperrealism","embroidery"],"difficulty":"expert","sourcePaper":"TEC-05","fieldNote":"Cast shadow and lifted edge — the tricks that make ink seem to sit above or below the skin.","keyFacts":[{"text":"Depth effects technique is credited to H.R. Giger''s fine-art source material and Guy Aitchison''s/Aaron Cain''s late-1980s–early-1990s tattoo-specific adaptation for Biomechanical tattooing.","evidence":"direct"}]}'),
  ('optical_illusion_technique', 'dimensional', 'Optical Illusion', 'Trompe-l''œil, impossible figures and figure-ground tricks.', 'expert', 'Optical Illusion is an expert-level method within 3D & Optical. Trompe-l''œil, impossible figures and figure-ground tricks. In practice, it shapes the way ink, line and skin meet rather than defining the subject by itself. It is especially at home in 3D / Optical Illusion, Glitch / Pixel, Geometric, and Embroidery / Patch. Its success depends on deliberate execution, anatomical placement and enough spacing for the tattoo to age clearly.', 'en', '{"id":"optical_illusion_technique","name":"Optical Illusion","category":"dimensional","description":"Trompe-l''œil, impossible figures and figure-ground tricks.","usedInStyles":["3d_style","glitch","geometric","embroidery"],"difficulty":"expert","sourcePaper":"TEC-05","fieldNote":"Perspective and shadow bending the eye — no single founder, just the craft of fooling it well.","keyFacts":[{"text":"No specific named tattoo-world pioneer or precise founding date was identified for optical illusion technique''s application in 3D/Optical Illusion or Glitch styles.","evidence":"unknown"},{"text":"Glitch''s RGB-splitting effect is executed via deliberately offset color-channel layering using standard color-blending technique directed toward a digital-error reference.","evidence":"synthesized"}]}'),
  ('hand_poke', 'manual', 'Hand Poke (Stick & Poke)', 'Manual dot-by-dot application with a hand-held needle; no machine.', 'intermediate', 'Hand Poke (Stick & Poke) is an intermediate-level method within Manual (Machine-free). Manual dot-by-dot application with a hand-held needle; no machine. In practice, it shapes the way ink, line and skin meet rather than defining the subject by itself. It is especially at home in Handpoke / Stick-and-Poke, Ignorant Style, and Dotwork. Its success depends on deliberate execution, anatomical placement and enough spacing for the tattoo to age clearly.', 'en', '{"id":"hand_poke","name":"Hand Poke (Stick & Poke)","category":"manual","description":"Manual dot-by-dot application with a hand-held needle; no machine.","usedInStyles":["handpoke_style","ignorant","dotwork_style"],"difficulty":"intermediate","sourcePaper":"TEC-06","fieldNote":"Point by point, by hand — the method older than the machine, worn by Ötzi five thousand years ago.","keyFacts":[{"text":"Hand poke is the technologically prior universal tattoo method, evidenced on Ötzi the Iceman, predating the electric machine.","evidence":"direct"}]}'),
  ('tebori_technique', 'manual', 'Tebori', 'Japanese hand-carving with needles mounted on a rod (nomi); renowned for soft gradation.', 'expert', 'Tebori is an expert-level method within Manual (Machine-free). Japanese hand-carving with needles mounted on a rod (nomi); renowned for soft gradation. In practice, it shapes the way ink, line and skin meet rather than defining the subject by itself. It is especially at home in Tebori (Hand-carved Japanese) and Japanese Irezumi. Its success depends on deliberate execution, anatomical placement and enough spacing for the tattoo to age clearly.', 'en', '{"id":"tebori_technique","name":"Tebori","category":"manual","description":"Japanese hand-carving with needles mounted on a rod (nomi); renowned for soft gradation.","usedInStyles":["tebori_style","irezumi"],"difficulty":"expert","sourcePaper":"TEC-06","fieldNote":"A needle-bundle on a rod, worked by hand — the Japanese pace that no motor reproduces.","keyFacts":[{"text":"Tebori uses a bundle of needles on a rod, worked by hand; Horiyoshi III adopted hybrid machine/tebori technique from the late 1990s.","evidence":"direct"}]}'),
  ('hand_tapped', 'manual', 'Hand-Tapped (Tatau)', 'Polynesian method: ink tapped in with a comb (au) struck by a mallet.', 'expert', 'Hand-Tapped (Tatau) is an expert-level method within Manual (Machine-free). Polynesian method: ink tapped in with a comb (au) struck by a mallet. In practice, it shapes the way ink, line and skin meet rather than defining the subject by itself. It is especially at home in Samoan (Pe''a / Malu), Polynesian, Māori / Tā Moko, and Marquesan. Its success depends on deliberate execution, anatomical placement and enough spacing for the tattoo to age clearly.', 'en', '{"id":"hand_tapped","name":"Hand-Tapped (Tatau)","category":"manual","description":"Polynesian method: ink tapped in with a comb (au) struck by a mallet.","usedInStyles":["samoan","polynesian","maori","marquesan"],"difficulty":"expert","sourcePaper":"TEC-06","fieldNote":"The au tapped by a tufuga — Sāmoan tatau applied under hereditary authority, never casually.","keyFacts":[{"text":"Samoan tatau is applied via hand-tapped au technique under hereditary tufuga authority, documented with unbroken continuity since before European contact.","evidence":"direct"}]}'),
  ('skin_stitching', 'manual', 'Skin Stitching', 'Inuit/Arctic method pulling soot-coated thread through skin; revived in cultural reclamation.', 'expert', 'Skin Stitching is an expert-level method within Manual (Machine-free). Inuit/Arctic method pulling soot-coated thread through skin; revived in cultural reclamation. In practice, it shapes the way ink, line and skin meet rather than defining the subject by itself. It is especially at home in Tribal (Modern). Its success depends on deliberate execution, anatomical placement and enough spacing for the tattoo to age clearly.', 'en', '{"id":"skin_stitching","name":"Skin Stitching","category":"manual","description":"Inuit/Arctic method pulling soot-coated thread through skin; revived in cultural reclamation.","usedInStyles":["tribal"],"difficulty":"expert","sourcePaper":"TEC-06","fieldNote":"Sinew drawn beneath the skin with a bone needle — the Arctic method, carrying its own lineage.","keyFacts":[{"text":"Skin stitching uses a bone/ivory/bird-bone needle threaded with soot-pigmented sinew, drawn beneath the skin to deposit continuous pigment lines.","evidence":"direct"},{"text":"The practice is documented by some accounts as dating back at least 10,000 years among Inuit peoples.","evidence":"community_attested"}]}'),
  ('blackout_technique', 'specialized', 'Blackout', 'Saturating large areas in uniform solid black.', 'advanced', 'Blackout is an advanced-level method within Specialized & Effects. Saturating large areas in uniform solid black. In practice, it shapes the way ink, line and skin meet rather than defining the subject by itself. It is especially at home in Blackout / Heavy Blackwork, Blackwork, and Negative Space. Its success depends on deliberate execution, anatomical placement and enough spacing for the tattoo to age clearly.', 'en', '{"id":"blackout_technique","name":"Blackout","category":"specialized","description":"Saturating large areas in uniform solid black.","usedInStyles":["blackout_style","blackwork_style","negative_space_style"],"difficulty":"advanced","sourcePaper":"TEC-07","fieldNote":"Large magnums and dedicated black — saturating whole zones evenly is harder than it looks, and permanent.","keyFacts":[{"text":"Blackout technique requires large magnum needle groupings and specialized non-shading black ink, credited to Chester Lee from c. 2011.","evidence":"direct"},{"text":"Negative space depends on precise edge control since the ink/skin boundary carries the entire representational content.","evidence":"direct"}]}'),
  ('negative_space', 'specialized', 'Negative Space', 'Using untouched skin as the design element against inked ground.', 'advanced', 'Negative Space is an advanced-level method within Specialized & Effects. Using untouched skin as the design element against inked ground. In practice, it shapes the way ink, line and skin meet rather than defining the subject by itself. It is especially at home in Negative Space, Blackwork, Geometric, and Minimalist. Its success depends on deliberate execution, anatomical placement and enough spacing for the tattoo to age clearly.', 'en', '{"id":"negative_space","name":"Negative Space","category":"specialized","description":"Using untouched skin as the design element against inked ground.","usedInStyles":["negative_space_style","blackwork_style","geometric","minimalist"],"difficulty":"advanced","sourcePaper":"TEC-07","fieldNote":"Leaving skin as the image — figure-ground reversal that lives or dies on edge control.","keyFacts":[{"text":"Figure-ground-reversal technique using untouched skin as the image-bearing element, depending on exceptionally precise edge control since the entire representational content is carried by the ink/skin boundary.","evidence":"synthesized"}]}'),
  ('geometric_technique', 'specialized', 'Geometric Precision', 'Ruler/stencil-precise shapes, repeating patterns and symmetry control on curved skin.', 'advanced', 'Geometric Precision is an advanced-level method within Specialized & Effects. Ruler/stencil-precise shapes, repeating patterns and symmetry control on curved skin. In practice, it shapes the way ink, line and skin meet rather than defining the subject by itself. It is especially at home in Geometric, Sacred Geometry, Mandala / Ornamental, and Ornamental. Its success depends on deliberate execution, anatomical placement and enough spacing for the tattoo to age clearly.', 'en', '{"id":"geometric_technique","name":"Geometric Precision","category":"specialized","description":"Ruler/stencil-precise shapes, repeating patterns and symmetry control on curved skin.","usedInStyles":["geometric","sacred_geometry","mandala","ornamental"],"difficulty":"advanced","sourcePaper":"TEC-07","fieldNote":"Precision mapped to the body''s curve — the line that must meet itself exactly, as Machlev showed.","keyFacts":[{"text":"Geometric precision technique is credited significantly to Chaim Machlev''s contemporary practice (from 2012), requiring adaptation of flat-pattern symmetry to curved body surfaces.","evidence":"direct"},{"text":"Silhouette technique uses solid color-packing to produce hard-edged figures, sometimes with double-exposure interior detail.","evidence":"synthesized"}]}'),
  ('brush_stroke', 'specialized', 'Brush Stroke', 'Strokes imitating loaded paintbrush marks, including dry-brush texture.', 'advanced', 'Brush Stroke is an advanced-level method within Specialized & Effects. Strokes imitating loaded paintbrush marks, including dry-brush texture. In practice, it shapes the way ink, line and skin meet rather than defining the subject by itself. It is especially at home in Calligraphy / Calligraffiti, Trash Polka, Abstract, and Watercolor. Its success depends on deliberate execution, anatomical placement and enough spacing for the tattoo to age clearly.', 'en', '{"id":"brush_stroke","name":"Brush Stroke","category":"specialized","description":"Strokes imitating loaded paintbrush marks, including dry-brush texture.","usedInStyles":["calligraphy","trash_polka","abstract","watercolor_style"],"difficulty":"advanced","sourcePaper":"TEC-08","fieldNote":"The gesture of a loaded brush, faked in ink — texture that reads as paint.","keyFacts":[{"text":"Etching technique is credited to Yvonne (Blut & Eisen, Berlin) and Duncan X (Into You, London) from the 2010s.","evidence":"direct"},{"text":"Brush stroke technique underlies Calligraphy/Calligraffiti''s Latin and Arabic-script traditions and Trash Polka''s collage aesthetic.","evidence":"synthesized"}]}'),
  ('etching_technique', 'specialized', 'Etching / Engraving', 'Parallel-line and hatch systems recreating printmaking''s carved look.', 'advanced', 'Etching / Engraving is an advanced-level method within Specialized & Effects. Parallel-line and hatch systems recreating printmaking''s carved look. In practice, it shapes the way ink, line and skin meet rather than defining the subject by itself. It is especially at home in Etching / Engraving (Woodcut), Dark Art / Occult, and Illustrative. Its success depends on deliberate execution, anatomical placement and enough spacing for the tattoo to age clearly.', 'en', '{"id":"etching_technique","name":"Etching / Engraving","category":"specialized","description":"Parallel-line and hatch systems recreating printmaking''s carved look.","usedInStyles":["etching","dark_art","illustrative"],"difficulty":"advanced","sourcePaper":"TEC-08","fieldNote":"Parallel lines and cross-hatch imitating a printing plate — Yvonne and Duncan X''s revival of the engraved look.","keyFacts":[{"text":"Parallel-line/cross-hatch printmaking-imitating technique, credited to Yvonne and Duncan X''s 2010s revival, foundational to Etching, Dark Art, and Illustrative styles.","evidence":"synthesized"}]}'),
  ('silhouette_technique', 'specialized', 'Silhouette', 'Solid hard-edged figure fills, often with interior negative scenes.', 'basic', 'Silhouette is a basic-level method within Specialized & Effects. Solid hard-edged figure fills, often with interior negative scenes. In practice, it shapes the way ink, line and skin meet rather than defining the subject by itself. It is especially at home in Silhouette, Blackwork, and Minimalist. Its success depends on deliberate execution, anatomical placement and enough spacing for the tattoo to age clearly.', 'en', '{"id":"silhouette_technique","name":"Silhouette","category":"specialized","description":"Solid hard-edged figure fills, often with interior negative scenes.","usedInStyles":["silhouette_style","blackwork_style","minimalist"],"difficulty":"basic","sourcePaper":"TEC-07","fieldNote":"A single solid tone as the whole figure — sometimes hiding a second scene inside its shadow.","keyFacts":[{"text":"Solid, hard-edged single-tone figure-fill technique, sometimes incorporating interior double-exposure scene detail; a comparatively technically accessible (\\"basic\\" difficulty per this corpus''s foundational technical catalog) but precision-demanding edge-control technique.","evidence":"synthesized"}]}'),
  ('tribal_blackfill', 'specialized', 'Tribal Blackfill', 'Even solid black in traditional pattern vocabularies, flowing with anatomy.', 'intermediate', 'Tribal Blackfill is an intermediate-level method within Specialized & Effects. Even solid black in traditional pattern vocabularies, flowing with anatomy. In practice, it shapes the way ink, line and skin meet rather than defining the subject by itself. It is especially at home in Tribal (Modern), Polynesian, Māori / Tā Moko, and Neo-Tribal. Its success depends on deliberate execution, anatomical placement and enough spacing for the tattoo to age clearly.', 'en', '{"id":"tribal_blackfill","name":"Tribal Blackfill","category":"specialized","description":"Even solid black in traditional pattern vocabularies, flowing with anatomy.","usedInStyles":["tribal","polynesian","maori","neotribal"],"difficulty":"intermediate","sourcePaper":"TEC-07","fieldNote":"The solid fill of living Pacific and Māori pattern — technique inseparable from cultural authority.","keyFacts":[{"text":"Tribal blackfill executes pattern vocabularies specific to living Polynesian, Māori, and related Indigenous traditions carrying sacred, gendered, and/or hereditary-practitioner restrictions.","evidence":"direct"}]}'),
  ('uv_ink', 'specialized', 'UV Ink', 'UV-reactive pigments visible under blacklight.', 'advanced', 'UV Ink is an advanced-level method within Specialized & Effects. UV-reactive pigments visible under blacklight. In practice, it shapes the way ink, line and skin meet rather than defining the subject by itself. It is especially at home in UV / Blacklight. Its success depends on deliberate execution, anatomical placement and enough spacing for the tattoo to age clearly.', 'en', '{"id":"uv_ink","name":"UV Ink","category":"specialized","description":"UV-reactive pigments visible under blacklight.","usedInStyles":["uv_style"],"difficulty":"advanced","sourcePaper":"TEC-08","fieldNote":"Pigment that answers only to blacklight — and carries a regulatory gap I will always disclose before you commit.","keyFacts":[{"text":"UV ink carries a documented, unresolved FDA regulatory gap and historical phosphorus-related safety concerns.","evidence":"direct"}]}'),
  ('smoke_effect', 'specialized', 'Smoke Effect', 'Soft billowing greywash forms for a smoky, ethereal look.', 'advanced', 'Smoke Effect is an advanced-level method within Specialized & Effects. Soft billowing greywash forms for a smoky, ethereal look. In practice, it shapes the way ink, line and skin meet rather than defining the subject by itself. It is especially at home in Horror, Black & Grey Realism, Surrealism, and Black & Grey. Its success depends on deliberate execution, anatomical placement and enough spacing for the tattoo to age clearly.', 'en', '{"id":"smoke_effect","name":"Smoke Effect","category":"specialized","description":"Soft billowing greywash forms for a smoky, ethereal look.","usedInStyles":["horror","realism_bg","surrealism","black_grey"],"difficulty":"advanced","sourcePaper":"TEC-08","fieldNote":"Soft grey drifting into negative space — atmosphere rendered as if it could move.","keyFacts":[{"text":"Smoke effect and fire effect are specialized rendering techniques within the broader realism/traditional-tattoo shading vocabulary; no independently documented named pioneers were identified.","evidence":"unknown"}]}'),
  ('fire_effect', 'specialized', 'Fire Effect', 'Dynamic flame rendering with layered oranges, yellows and negative-space glow.', 'advanced', 'Fire Effect is an advanced-level method within Specialized & Effects. Dynamic flame rendering with layered oranges, yellows and negative-space glow. In practice, it shapes the way ink, line and skin meet rather than defining the subject by itself. It is especially at home in Color Realism, New School, and Japanese Irezumi. Its success depends on deliberate execution, anatomical placement and enough spacing for the tattoo to age clearly.', 'en', '{"id":"fire_effect","name":"Fire Effect","category":"specialized","description":"Dynamic flame rendering with layered oranges, yellows and negative-space glow.","usedInStyles":["realism_color","new_school","irezumi"],"difficulty":"advanced","sourcePaper":"TEC-08","fieldNote":"Layered oranges and yellows around a negative-space glow — flame that seems lit from within.","keyFacts":[{"text":"Layered-color flame-rendering technique using oranges, yellows, and negative-space glow, used across Color Realism, New School, and Irezumi.","evidence":"synthesized"}]}'),
  ('freehand', 'process', 'Freehand', 'Drawing directly on skin with markers instead of a stencil, fitting design to anatomy live.', 'expert', 'Freehand is an expert-level method within Process & Craft. Drawing directly on skin with markers instead of a stencil, fitting design to anatomy live. In practice, it shapes the way ink, line and skin meet rather than defining the subject by itself. It is especially at home in Tribal (Modern), Abstract, Biomechanical, and Calligraphy / Calligraffiti. Its success depends on deliberate execution, anatomical placement and enough spacing for the tattoo to age clearly.', 'en', '{"id":"freehand","name":"Freehand","category":"process","description":"Drawing directly on skin with markers instead of a stencil, fitting design to anatomy live.","usedInStyles":["tribal","abstract","biomechanical","calligraphy"],"difficulty":"expert","sourcePaper":"TEC-09","fieldNote":"Drawn straight onto the body — letting the anatomy, not the paper, decide where the line goes.","keyFacts":[{"text":"Freehand technique is foundational to Tribal, Abstract, and Biomechanical composition, and is Paul Booth''s signature no-outline method for Horror/Dark Art.","evidence":"direct"}]}'),
  ('cover_up', 'process', 'Cover-Up', 'Designing over an existing tattoo to conceal it using value mapping and strategic density.', 'expert', 'Cover-Up is an expert-level method within Process & Craft. Designing over an existing tattoo to conceal it using value mapping and strategic density. In practice, it shapes the way ink, line and skin meet rather than defining the subject by itself. It is especially at home in Blackout / Heavy Blackwork, Japanese Irezumi, Blackwork, and Black & Grey Realism. Its success depends on deliberate execution, anatomical placement and enough spacing for the tattoo to age clearly.', 'en', '{"id":"cover_up","name":"Cover-Up","category":"process","description":"Designing over an existing tattoo to conceal it using value mapping and strategic density.","usedInStyles":["blackout_style","irezumi","blackwork_style","realism_bg"],"difficulty":"expert","sourcePaper":"TEC-10","fieldNote":"New design absorbing old ink — Dietzel hid scars under rosebuds a century ago; the judgment is the craft.","keyFacts":[{"text":"Amund Dietzel is documented covering vaccination marks and scars with rosebuds or butterflies, an early cosmetic cover-work function.","evidence":"direct"},{"text":"Blackout technique represents the concealment-maximal case of cover-up logic, guaranteeing full concealment via total solid-black saturation.","evidence":"direct"}]}'),
  ('blast_over', 'process', 'Blast-Over', 'Bold new design tattooed directly over an old one, letting both remain visible in layers.', 'advanced', 'Blast-Over is an advanced-level method within Process & Craft. Bold new design tattooed directly over an old one, letting both remain visible in layers. In practice, it shapes the way ink, line and skin meet rather than defining the subject by itself. It is especially at home in Blackwork, Ignorant Style, and Tribal (Modern). Its success depends on deliberate execution, anatomical placement and enough spacing for the tattoo to age clearly.', 'en', '{"id":"blast_over","name":"Blast-Over","category":"process","description":"Bold new design tattooed directly over an old one, letting both remain visible in layers.","usedInStyles":["blackwork_style","ignorant","tribal"],"difficulty":"advanced","sourcePaper":"TEC-10","fieldNote":"Bold new work laid over old on purpose — coexistence, not concealment.","keyFacts":[{"text":"Blast-over deliberately layers new bold work over old ink without concealment intent, associated with Blackwork, Ignorant, and Tribal styles; no specific named pioneer was identified.","evidence":"unknown"}]}'),
  ('layering', 'process', 'Layering', 'Building color/value in multiple passes and sessions for depth and durability.', 'advanced', 'Layering is an advanced-level method within Process & Craft. Building color/value in multiple passes and sessions for depth and durability. In practice, it shapes the way ink, line and skin meet rather than defining the subject by itself. It is especially at home in Color Realism, Hyperrealism, Portrait, and Embroidery / Patch. Its success depends on deliberate execution, anatomical placement and enough spacing for the tattoo to age clearly.', 'en', '{"id":"layering","name":"Layering","category":"process","description":"Building color/value in multiple passes and sessions for depth and durability.","usedInStyles":["realism_color","hyperrealism","portrait","embroidery"],"difficulty":"advanced","sourcePaper":"TEC-09","fieldNote":"Value and color accumulated across sittings — the slow build realism and dark art both depend on.","keyFacts":[{"text":"Layering is foundational to Color Realism/Hyperrealism''s multi-session buildup and is Paul Booth''s specific packing-and-blending method.","evidence":"direct"}]}')
ON DUPLICATE KEY UPDATE
  `category_id` = VALUES(`category_id`),
  `name` = VALUES(`name`),
  `description` = VALUES(`description`),
  `difficulty` = VALUES(`difficulty`),
  `narrative_description` = VALUES(`narrative_description`),
  `narrative_language` = VALUES(`narrative_language`),
  `source_payload` = VALUES(`source_payload`);

