VALUES
  ('sdxl_base', 'stable_diffusion', 'Stability AI', 'Stable Diffusion XL', '1.0', 'active', '{"form":"tags","joiner":", ","slot_order":["subject","style","technique","palette","composition","surface","lighting","detail"],"style_suffix":" tattoo","weights":{"syntax":"sd_parens","emphasis":1.2,"slots":["style","technique"]},"negative":{"mode":"field","joiner":", "},"parameters":{"mode":"fields"},"aspect":{"mode":"dimensions","base":1024}}', '{"supports_negative_prompt":true,"supports_weights":true,"supports_parameters":true,"supports_conversational_edit":false,"supports_reference_image":true,"max_prompt_chars":1500}', '{"steps":34,"cfg_scale":6,"sampler":"DPM++ 2M Karras","clip_skip":2}', 'The reference target. Tag-weighted positives, a real negative prompt, and explicit sampler settings.', 10, 1),
  ('sd35_large', 'stable_diffusion', 'Stability AI', 'Stable Diffusion 3.5 Large', '3.5', 'active', '{"form":"hybrid","joiner":", ","slot_order":["subject","style","technique","palette","composition","surface","lighting","detail"],"style_suffix":" tattoo","weights":{"syntax":"sd_parens","emphasis":1.1,"slots":["style"]},"negative":{"mode":"field","joiner":", "},"parameters":{"mode":"fields"},"aspect":{"mode":"dimensions","base":1024}}', '{"supports_negative_prompt":true,"supports_weights":true,"supports_parameters":true,"supports_conversational_edit":false,"supports_reference_image":true,"max_prompt_chars":2000}', '{"steps":28,"cfg_scale":4.5,"sampler":"DPM++ 2M","shift":3}', 'Follows longer, better-punctuated phrasing than SDXL while still honouring a negative prompt.', 20, 0),
  ('flux_1_dev', 'flux', 'Black Forest Labs', 'Flux.1 dev', '1.0', 'active', '{"form":"prose","joiner":" ","slot_order":["subject","style","technique","palette","composition","surface","lighting","detail"],"weights":{"syntax":"none"},"negative":{"mode":"prose"},"parameters":{"mode":"fields"},"aspect":{"mode":"ratio"},"templates":{"flash":"A clean tattoo flash design of {{subject}}, drawn in {{style}} with {{technique}}. {{composition}}. Colors: {{palette}}. {{surface}}. {{detail}}.","on_skin":"A professional studio photograph of a finished {{style}} tattoo on {{placement}}. The design is {{subject}}, rendered with {{technique}} in {{palette}}. {{composition}}. {{surface}}. {{lighting}}. {{detail}}."}}', '{"supports_negative_prompt":false,"supports_weights":false,"supports_parameters":true,"supports_conversational_edit":false,"supports_reference_image":true,"max_prompt_chars":2500}', '{"steps":28,"guidance":3.5}', 'Rewards descriptive prose over keyword salad; negatives are expressed positively inside the sentence.', 30, 0),
  ('midjourney_v7', 'midjourney', 'Midjourney', 'Midjourney v7', '7', 'active', '{"form":"tags","joiner":", ","slot_order":["subject","style","technique","palette","composition","surface","lighting","detail"],"style_suffix":" tattoo","weights":{"syntax":"none"},"negative":{"mode":"flag","flag":"--no","joiner":", "},"parameters":{"mode":"flags","flags":{"aspect":"--ar","style":"--style","stylize":"--stylize"}},"aspect":{"mode":"ratio"}}', '{"supports_negative_prompt":true,"supports_weights":false,"supports_parameters":true,"supports_conversational_edit":false,"supports_reference_image":true,"max_prompt_chars":4000}', '{"style":"raw","stylize":200}', 'Tag phrasing plus trailing flags; --style raw and a low stylize value keep linework literal.', 40, 0),
  ('nano_banana', 'gemini', 'Google', 'Nano Banana (Gemini 2.5 Flash Image)', '2.5', 'active', '{"form":"prose","joiner":" ","slot_order":["subject","style","technique","palette","composition","surface","lighting","detail"],"weights":{"syntax":"none"},"negative":{"mode":"prose"},"parameters":{"mode":"none"},"aspect":{"mode":"sentence"},"templates":{"flash":"Create a {{style}} tattoo design of {{subject}}. Use {{technique}} and a palette of {{palette}}. {{composition}}. {{surface}}. {{detail}}.","on_skin":"Show a {{style}} tattoo of {{subject}} placed on {{placement}}, as a realistic studio photograph. It is rendered with {{technique}} in {{palette}}. {{composition}}. {{surface}}. {{lighting}}. {{detail}}."}}', '{"supports_negative_prompt":false,"supports_weights":false,"supports_parameters":false,"supports_conversational_edit":true,"supports_reference_image":true,"max_prompt_chars":3000}', '{}', 'Conversational. No flags — describe the image, then refine by chat; it holds the subject between turns.', 50, 0),
  ('sd15_legacy', 'stable_diffusion', 'Stability AI', 'Stable Diffusion 1.5', '1.5', 'deprecated', '{"form":"tags","joiner":", ","slot_order":["subject","style","technique","palette","surface","detail"],"style_suffix":" tattoo","weights":{"syntax":"sd_parens","emphasis":1.3,"slots":["style"]},"negative":{"mode":"field","joiner":", "},"parameters":{"mode":"fields"},"aspect":{"mode":"dimensions","base":512}}', '{"supports_negative_prompt":true,"supports_weights":true,"supports_parameters":true,"supports_conversational_edit":false,"supports_reference_image":true,"max_prompt_chars":900}', '{"steps":28,"cfg_scale":7,"sampler":"Euler a"}', 'Kept for older local pipelines. Short prompts, heavy negatives, 512px base — not recommended for fine-line work.', 90, 0)
