  ('surface_flash', 'surface', 'flash', 'all', 'isolated on a clean white background, tattoo flash sheet, centered, illustration only, not a photograph', 1.2, 10, 1),
  ('surface_on_skin', 'surface', 'on_skin', 'all', 'real healed ink on natural skin with visible pores and texture', 1.2, 10, 1),
  ('quality_flash', 'quality', 'flash', 'all', 'crisp confident linework, high detail, sharp focus', 1.2, 20, 1),
  ('quality_on_skin', 'quality', 'on_skin', 'all', 'high detail, natural color, shallow depth of field', NULL, 20, 1),
  ('lighting_studio', 'lighting', 'on_skin', 'all', 'soft directional studio lighting', NULL, 30, 1),
  ('longevity_accents', 'longevity', 'both', 'all', 'key outlines thickened so the design still reads after ten years', NULL, 40, 1),
  ('cultural_inspired', 'cultural', 'both', 'all', 'an original abstraction inspired by the tradition, not a replica of a sacred or closed design', NULL, 50, 1),
  ('negative_flash', 'negative', 'flash', 'all', 'blurry, muddy lines, color bleed, washed out, watermark, signature, text, jpeg artifacts, photographic background, skin, deformed anatomy, extra limbs', NULL, 10, 1),
  ('negative_on_skin', 'negative', 'on_skin', 'all', 'flat sticker look, plastic skin, blurry, color bleed, watermark, signature, text, deformed anatomy, extra limbs, unhealed wound', NULL, 10, 1),
  ('negative_fineline', 'negative', 'both', 'stable_diffusion', 'broken lines, double lines, wobbly outlines, sketchy scratchy strokes', NULL, 20, 1)
